        public static uint GetWindowStyleSafe(IntPtr hWnd, int nIndex)
        {
            if (hWnd == IntPtr.Zero) return 0;
            try
            {
                if (IntPtr.Size == 8)
                    return unchecked((uint)GetWindowLongPtr64(hWnd, nIndex).ToInt64());
                return unchecked((uint)GetWindowLong32(hWnd, nIndex));
            }
            catch { return 0; }
        }

