                    "RamCleanProtectForegroundGame|" + RamCleanProtectForegroundGame
                };

                foreach (var a in Alarms)
                {
                    lines.Add(string.Format("ALARM|{0}|{1}|{2}|{3}|{4}|{5}|{6}|{7}",
                        a.Id,
                        (a.Title ?? "").Replace('|', ' '),
                        (a.Description ?? "").Replace('|', ' '),
