                    return cfg;
                }

                foreach (string line in File.ReadAllLines(path, Encoding.UTF8))
                {
                    if (string.IsNullOrWhiteSpace(line)) continue;
                    string[] parts = line.Split('|');
                    if (parts.Length < 2) continue;
                    string key = parts[0].Trim();

                    bool bVal; int nVal;
                    if (key == "PowerTimerActive" && bool.TryParse(parts[1], out bVal)) cfg.PowerTimerActive = bVal;
                    else if (key == "PowerTimerMode") cfg.PowerTimerMode = parts[1].Trim();
                    else if (key == "PowerTimerHours" && int.TryParse(parts[1], out nVal)) cfg.PowerTimerHours = nVal;
                    else if (key == "PowerTimerMinutes" && int.TryParse(parts[1], out nVal)) cfg.PowerTimerMinutes = nVal;
                    else if (key == "PowerTimerSpecificTime") cfg.PowerTimerSpecificTime = parts[1].Trim();
                    else if (key == "PowerTimerAction") cfg.PowerTimerAction = parts[1].Trim();
                    else if (key == "PowerTimerPostponeIfNetBusy" && bool.TryParse(parts[1], out bVal)) cfg.PowerTimerPostponeIfNetBusy = bVal;
                    else if (key == "PowerTimerNetThresholdKBps" && int.TryParse(parts[1], out nVal)) cfg.PowerTimerNetThresholdKBps = nVal;
                    else if (key == "PowerTimerPostponeIfCpuBusy" && bool.TryParse(parts[1], out bVal)) cfg.PowerTimerPostponeIfCpuBusy = bVal;
                    else if (key == "PowerTimerCpuThresholdPercent" && int.TryParse(parts[1], out nVal)) cfg.PowerTimerCpuThresholdPercent = nVal;
                    else if (key == "PowerTimer5MinWarn" && bool.TryParse(parts[1], out bVal)) cfg.PowerTimer5MinWarn = bVal;
                    else if (key == "AlarmCustomSoundPath") cfg.AlarmCustomSoundPath = parts[1].Trim();
                    else if (key == "AlarmMaxPlayDurationSec" && int.TryParse(parts[1], out nVal)) cfg.AlarmMaxPlayDurationSec = nVal;
                    else if (key == "HealthRemindersEnabled" && bool.TryParse(parts[1], out bVal)) cfg.HealthRemindersEnabled = bVal;
                    else if (key == "HealthReminderIntervalMin" && int.TryParse(parts[1], out nVal)) cfg.HealthReminderIntervalMin = nVal;
                    else if (key == "NotificationMonitorDevice") cfg.NotificationMonitorDevice = parts[1].Trim();
                    else if (key == "NotificationMonitorIndex" && int.TryParse(parts[1], out nVal)) cfg.NotificationMonitorIndex = nVal;
                    else if (key == "NotificationPosition") cfg.NotificationPosition = parts[1].Trim();
                    else if (key == "AutoRamCleanActive" && bool.TryParse(parts[1], out bVal)) cfg.AutoRamCleanActive = bVal;
                    else if (key == "RamFreeThresholdPercent" && int.TryParse(parts[1], out nVal)) cfg.RamFreeThresholdPercent = nVal;
                    else if (key == "RamCleanProtectForegroundGame" && bool.TryParse(parts[1], out bVal)) cfg.RamCleanProtectForegroundGame = bVal;
                    else if (key == "ALARM" && parts.Length >= 8)
                    {
                        CustomAlarmItem itm = new CustomAlarmItem();
                        itm.Id = parts[1].Trim();
                        itm.Title = parts[2].Trim();
                        itm.Description = parts[3].Trim();
                        bool.TryParse(parts[4], out itm.IsEnabled);
                        itm.AlarmType = parts[5].Trim();
                        int.TryParse(parts[6], out itm.PeriodMinutes);
                        itm.SpecificTimeHHmm = parts[7].Trim();
                        if (parts.Length >= 9) DateTime.TryParse(parts[8], out itm.NextTrigger);
                        cfg.Alarms.Add(itm);
                    }
                    else if (key == "GAMENOTE" && parts.Length >= 7)
                    {
                        GameLaunchNoteItem gn = new GameLaunchNoteItem();
                        gn.Id = parts[1].Trim();
                        gn.ProcessName = parts[2].Trim();
                        gn.GameTitle = parts[3].Trim();
                        gn.NoteText = parts[4].Trim().Replace("\\n", "\r\n");
                        bool.TryParse(parts[5], out gn.IsEnabled);
                        bool.TryParse(parts[6], out gn.PeriodicInGame);
                        if (parts.Length >= 8) int.TryParse(parts[7], out gn.PeriodicIntervalMinutes);
                        cfg.GameNotes.Add(gn);
                    }
                }
            }
            catch { }

            // Program kapalıyken geçmişte kalmış tüm alarm zamanlarını mevcut andan sonraki ilk periyoda taşı (açılışta geçmiş alarm patlamasını engeller)
            cfg.FastForwardMissedAlarms(DateTime.Now);
            return cfg;
        }

        public void FastForwardMissedAlarms(DateTime now)
        {
            if (Alarms == null || Alarms.Count == 0) return;
            for (int i = 0; i < Alarms.Count; i++)
            {
                CustomAlarmItem a = Alarms[i];
                if (a != null && a.IsEnabled && a.NextTrigger <= now)
                {
                    CryptoAlarmHelpers.FastForwardAlarmToNextFuture(a, now);
                }
            }
        }
    }

    public static class CryptoAlarmHelpers
    {
        public static DateTime GetNextCrypto4HCandleTime(DateTime fromTime = default(DateTime))
        {
            DateTime now = (fromTime <= DateTime.MinValue.AddDays(1)) ? DateTime.Now : fromTime;
            int[] hours = new int[] { 3, 7, 11, 15, 19, 23 };
            foreach (int h in hours)
            {
                DateTime cand = new DateTime(now.Year, now.Month, now.Day, h, 0, 0);
                if (cand > now) return cand;
            }
            DateTime t = now.AddDays(1);
            return new DateTime(t.Year, t.Month, t.Day, 3, 0, 0);
        }

        public static DateTime GetNextCryptoDailyCloseTime(DateTime fromTime = default(DateTime))
        {
            DateTime now = (fromTime <= DateTime.MinValue.AddDays(1)) ? DateTime.Now : fromTime;
            DateTime cand = new DateTime(now.Year, now.Month, now.Day, 3, 0, 0);
            if (cand > now) return cand;
            DateTime t = now.AddDays(1);
            return new DateTime(t.Year, t.Month, t.Day, 3, 0, 0);
        }

        public static DateTime GetNextCryptoWeeklyCloseTime(DateTime fromTime = default(DateTime))
        {
            DateTime now = (fromTime <= DateTime.MinValue.AddDays(1)) ? DateTime.Now : fromTime;
            DateTime cand = new DateTime(now.Year, now.Month, now.Day, 3, 0, 0);
            while (cand <= now || cand.DayOfWeek != DayOfWeek.Monday)
            {
                cand = cand.AddDays(1);
            }
            return cand;
        }

        public static void FastForwardAlarmToNextFuture(CustomAlarmItem a, DateTime fromTime = default(DateTime))
        {
            if (a == null) return;
            DateTime now = (fromTime <= DateTime.MinValue.AddDays(1)) ? DateTime.Now : fromTime;
            string type = a.AlarmType ?? "PERIODIC";

            if (type == "CRYPTO_4H")
            {
                a.NextTrigger = GetNextCrypto4HCandleTime(now);
            }
            else if (type == "CRYPTO_DAILY")
            {
                a.NextTrigger = GetNextCryptoDailyCloseTime(now);
            }
            else if (type == "CRYPTO_WEEKLY")
            {
                a.NextTrigger = GetNextCryptoWeeklyCloseTime(now);
            }
            else if (type == "PERIODIC")
            {
                int p = Math.Max(1, a.PeriodMinutes);
                a.NextTrigger = now.AddMinutes(p);
            }
            else if (type == "SPECIFIC_TIME")
            {
                DateTime targetClock;
                if (!string.IsNullOrEmpty(a.SpecificTimeHHmm) && DateTime.TryParse(a.SpecificTimeHHmm, out targetClock))
                {
                    DateTime sched = new DateTime(now.Year, now.Month, now.Day, targetClock.Hour, targetClock.Minute, 0);
                    if (sched <= now) sched = sched.AddDays(1);
                    a.NextTrigger = sched;
                }
                else
                {
                    a.IsEnabled = false;
                }
            }
            else
            {
                a.IsEnabled = false;
            }
        }
    }

    public static class AudioAlertPlayer
    {
        private static System.Threading.Timer cutoffTimer;
        private static readonly object playLock = new object();

        public static void PlayAlert(string soundFilePath, int maxDurationSeconds)
        {
            lock (playLock)
            {
                StopAlert();

                bool playedCustom = false;
                if (!string.IsNullOrEmpty(soundFilePath) && File.Exists(soundFilePath))
                {
                    try
                    {
                        NativeMethods.mciSendString("close argon_alert_audio", null, 0, IntPtr.Zero);
                        string openCmd = string.Format("open \"{0}\" type mpegvideo alias argon_alert_audio", soundFilePath);
                        int resOpen = NativeMethods.mciSendString(openCmd, null, 0, IntPtr.Zero);
                        if (resOpen == 0)
                        {
                            NativeMethods.mciSendString("play argon_alert_audio from 0", null, 0, IntPtr.Zero);
                            playedCustom = true;
                        }
                    }
                    catch { }
                }

                if (!playedCustom)
                {
                    try
                    {
                        System.Media.SystemSounds.Exclamation.Play();
                    }
                    catch { }
                }

                int safeDurationSec = Math.Max(3, Math.Min(60, maxDurationSeconds));
                cutoffTimer = new System.Threading.Timer(delegate
                {
                    StopAlert();
                }, null, safeDurationSec * 1000, Timeout.Infinite);
            }
        }

        public static void StopAlert()
        {
            try
            {
                if (cutoffTimer != null)
                {
                    cutoffTimer.Dispose();
                    cutoffTimer = null;
                }
                NativeMethods.mciSendString("stop argon_alert_audio", null, 0, IntPtr.Zero);
                NativeMethods.mciSendString("close argon_alert_audio", null, 0, IntPtr.Zero);
            }
            catch { }
        }
    }

    public class QoLToastForm : Form
    {
        private static readonly List<QoLToastForm> activeToasts = new List<QoLToastForm>();
        private static readonly object activeToastsLock = new object();

        private System.Windows.Forms.Timer autoCloseTimer;
        private System.Windows.Forms.Timer pulseTimer;
        private int pulseCount = 0;
        private Action onActionClick;
        private Color accentColor;

        public QoLToastForm(string title, string message, string actionButtonText, Action action, Color accent, int autoCloseSeconds, bool pulseEvery3Sec)
            : this(title, message, actionButtonText, action, accent, autoCloseSeconds, pulseEvery3Sec, "BOTTOM_RIGHT", -1, "PRIMARY")
        {
        }

        public QoLToastForm(string title, string message, string actionButtonText, Action action, Color accent, int autoCloseSeconds, bool pulseEvery3Sec, string position, int monitorIndex, string monitorDevice)
        {
            this.FormBorderStyle = FormBorderStyle.None;
            this.StartPosition = FormStartPosition.Manual;
            this.ShowInTaskbar = false;
            this.TopMost = true;
            this.Size = new Size(380, 105);
            this.BackColor = Color.FromArgb(20, 26, 38);
            this.accentColor = accent;
            this.onActionClick = action;

            // Resolve target monitor
            Screen targetScreen = Screen.PrimaryScreen;
            try
            {
                Screen[] allScreens = Screen.AllScreens;
                if (allScreens != null && allScreens.Length > 0)
                {
                    bool found = false;
                    if (!string.IsNullOrEmpty(monitorDevice) && !monitorDevice.Equals("PRIMARY", StringComparison.OrdinalIgnoreCase))
                    {
                        foreach (Screen s in allScreens)
                        {
                            if (string.Equals(s.DeviceName, monitorDevice, StringComparison.OrdinalIgnoreCase))
                            {
                                targetScreen = s;
                                found = true;
                                break;
                            }
                        }
                    }
                    if (!found && monitorIndex >= 0 && monitorIndex < allScreens.Length)
                    {
                        targetScreen = allScreens[monitorIndex];
                    }
                }
            }
            catch { }
            if (targetScreen == null) targetScreen = Screen.PrimaryScreen;

            // Track active toasts to avoid overlaps and stack cleanly
            int stackOffsetIndex = 0;
            lock (activeToastsLock)
            {
                for (int i = activeToasts.Count - 1; i >= 0; i--)
                {
                    if (activeToasts[i] == null || activeToasts[i].IsDisposed)
                    {
                        activeToasts.RemoveAt(i);
                    }
                }
                stackOffsetIndex = activeToasts.Count;
                activeToasts.Add(this);
            }

            this.FormClosed += (s, e) =>
            {
                lock (activeToastsLock)
                {
                    activeToasts.Remove(this);
                }
            };

            // Calculate exact position on selected monitor
            Rectangle workArea = targetScreen.WorkingArea;
            int marginX = 20;
            int marginY = 20;
            int stackDelta = Math.Min(3, stackOffsetIndex) * (this.Height + 10);
            string pos = (position ?? "BOTTOM_RIGHT").ToUpperInvariant();

            int posX = workArea.Right - this.Width - marginX;
            int posY = workArea.Bottom - this.Height - marginY;

            if (pos == "TOP_RIGHT")
            {
                posX = workArea.Right - this.Width - marginX;
                posY = workArea.Top + marginY + stackDelta;
                if (posY + this.Height > workArea.Bottom) posY = workArea.Bottom - this.Height - marginY;
            }
            else if (pos == "TOP_LEFT")
            {
                posX = workArea.Left + marginX;
                posY = workArea.Top + marginY + stackDelta;
                if (posY + this.Height > workArea.Bottom) posY = workArea.Bottom - this.Height - marginY;
            }
            else if (pos == "BOTTOM_LEFT")
            {
                posX = workArea.Left + marginX;
                posY = workArea.Bottom - this.Height - marginY - stackDelta;
                if (posY < workArea.Top) posY = workArea.Top + marginY;
            }
            else // "BOTTOM_RIGHT" or default (Saat bölgesi)
            {
                posX = workArea.Right - this.Width - marginX;
                posY = workArea.Bottom - this.Height - marginY - stackDelta;
                if (posY < workArea.Top) posY = workArea.Top + marginY;
            }

            this.Location = new Point(posX, posY);

            this.Paint += (s, e) =>
            {
                using (Pen borderPen = new Pen(Color.FromArgb(45, 55, 75), 1))
                {
                    e.Graphics.DrawRectangle(borderPen, 0, 0, this.Width - 1, this.Height - 1);
                }
                using (SolidBrush accentBrush = new SolidBrush(this.accentColor))
                {
                    e.Graphics.FillRectangle(accentBrush, 0, 0, 6, this.Height);
                }
            };

            Label lblTitle = new Label
            {
                Text = title,
                Font = new Font("Segoe UI", 9.2f, FontStyle.Bold),
                ForeColor = accent,
                Location = new Point(16, 10),
                AutoSize = true
            };
            this.Controls.Add(lblTitle);

            Label lblMsg = new Label
            {
                Text = message,
                Font = new Font("Segoe UI", 8.2f, FontStyle.Regular),
                ForeColor = Color.FromArgb(226, 232, 240),
                Location = new Point(16, 34),
                Size = new Size(346, 36),
                AutoEllipsis = true
            };
            this.Controls.Add(lblMsg);

            Button btnClose = new Button
            {
                Text = "✕",
                Font = new Font("Segoe UI", 8.0f, FontStyle.Bold),
                ForeColor = Color.FromArgb(148, 163, 184),
                FlatStyle = FlatStyle.Flat,
                Size = new Size(24, 22),
                Location = new Point(this.Width - 28, 6),
                Cursor = Cursors.Hand
            };
            btnClose.FlatAppearance.BorderSize = 0;
            btnClose.Click += (s, e) => this.Close();
            this.Controls.Add(btnClose);

            if (!string.IsNullOrEmpty(actionButtonText))
            {
                Button btnAction = new Button
                {
                    Text = actionButtonText,
                    Font = new Font("Segoe UI", 7.8f, FontStyle.Bold),
                    ForeColor = Color.White,
                    BackColor = Color.FromArgb(220, 38, 38),
                    FlatStyle = FlatStyle.Flat,
                    Size = new Size(125, 24),
                    Location = new Point(this.Width - 140, 72),
                    Cursor = Cursors.Hand
                };
                btnAction.FlatAppearance.BorderSize = 0;
                btnAction.Click += (s, e) =>
                {
                    if (onActionClick != null) onActionClick();
                    this.Close();
                };
                this.Controls.Add(btnAction);
            }

            if (autoCloseSeconds > 0)
            {
                autoCloseTimer = new System.Windows.Forms.Timer { Interval = autoCloseSeconds * 1000 };
                autoCloseTimer.Tick += (s, e) =>
                {
                    autoCloseTimer.Stop();
                    this.Close();
                };
                autoCloseTimer.Start();
            }

            if (pulseEvery3Sec)
            {
                pulseTimer = new System.Windows.Forms.Timer { Interval = 3000 };
                pulseTimer.Tick += (s, e) =>
                {
                    pulseCount++;
                    this.BackColor = (pulseCount % 2 == 1) ? Color.FromArgb(46, 26, 60) : Color.FromArgb(20, 26, 38);
                    this.Invalidate();
                    if (pulseCount >= 5) // 5 x 3s = 15 saniye alarm darbe döngüsü
                    {
                        pulseTimer.Stop();
                    }
                };
                pulseTimer.Start();
            }
        }

        protected override bool ShowWithoutActivation
        {
            get { return true; }
        }
    }

    #endregion

    #region Linux-like Trackball & Mouse Scrolling Engine (MarbleScrollPlus Integration)

    public enum ScrollTriggerButton
    {
        MiddleClick = 0,
        XButton1 = 1,
        XButton2 = 2
    }

    public class LinuxlikeScrollAxisConfig
    {
        public bool Enabled = true;
        public bool Invert = false;
        public int Sensitivity = 1;
        public int Speed = 10;
        public bool Smoothing = false;

        public int Multiplier
        {
            get { return (Invert ? -1 : 1) * Speed * Sensitivity; }
        }
    }

    public class LinuxlikeScrollConfig
    {
        public bool AutoStartWithArgon = true;
        public bool Enabled = true;
        public ScrollTriggerButton Trigger = ScrollTriggerButton.MiddleClick;
        public bool AxisLock = true;
        public int AxisDetectPx = 4;

        public LinuxlikeScrollAxisConfig Vertical = new LinuxlikeScrollAxisConfig
        {
            Enabled = true,
            Invert = true,
            Sensitivity = 1,
            Speed = 8,
            Smoothing = true
        };

        public LinuxlikeScrollAxisConfig Horizontal = new LinuxlikeScrollAxisConfig
        {
            Enabled = true,
            Invert = false,
            Sensitivity = 1,
            Speed = 12,
            Smoothing = true
        };

        public void ResetToDefaults()
        {
            AutoStartWithArgon = true;
            Trigger = ScrollTriggerButton.MiddleClick;
            AxisLock = true;
            AxisDetectPx = 4;

            Vertical.Enabled = true;
            Vertical.Invert = true;
            Vertical.Sensitivity = 1;
            Vertical.Speed = 8;
            Vertical.Smoothing = true;

            Horizontal.Enabled = true;
            Horizontal.Invert = false;
            Horizontal.Sensitivity = 1;
            Horizontal.Speed = 12;
            Horizontal.Smoothing = true;
        }

        public void SaveToFile(string path)
        {
            if (string.IsNullOrEmpty(path)) return;
            try
            {
                List<string> lines = new List<string>
                {
                    "ARGON_LINUXLIKE_SCROLL_CONFIG|2",
                    "AutoStartWithArgon|" + AutoStartWithArgon,
                    "Enabled|" + Enabled,
                    "Trigger|" + Trigger,
                    "AxisLock|" + AxisLock,
                    "AxisDetectPx|" + Math.Max(2, Math.Min(16, AxisDetectPx)),
                    "VertEnabled|" + Vertical.Enabled,
                    "VertInvert|" + Vertical.Invert,
                    "VertSens|" + Vertical.Sensitivity,
                    "VertSpeed|" + Vertical.Speed,
                    "VertSmoothing|" + Vertical.Smoothing,
                    "HorizEnabled|" + Horizontal.Enabled,
                    "HorizInvert|" + Horizontal.Invert,
                    "HorizSens|" + Horizontal.Sensitivity,
                    "HorizSpeed|" + Horizontal.Speed,
                    "HorizSmoothing|" + Horizontal.Smoothing
                };
                StateVault.WriteAllLinesAtomic(path, lines.ToArray());
            }
            catch { }
        }

        public static LinuxlikeScrollConfig LoadFromFile(string path)
        {
            LinuxlikeScrollConfig cfg = new LinuxlikeScrollConfig();
            try
            {
                if (!File.Exists(path))
                {
                    // Auto-import user's existing MarbleScrollPlus registry preferences on first run
                    try
                    {
                        using (RegistryKey root = Registry.CurrentUser.OpenSubKey(@"Software\thp.io\MarbleScrollPlus"))
                        {
                            if (root != null)
                            {
                                object ax = root.GetValue("axislock");
                                if (ax != null) cfg.AxisLock = (Convert.ToInt32(ax) != 0);

                                using (RegistryKey vk = root.OpenSubKey("Vertical"))
                                {
                                    if (vk != null)
                                    {
                                        object en = vk.GetValue("enabled");
                                        if (en != null) cfg.Vertical.Enabled = (Convert.ToInt32(en) != 0);
                                        object inv = vk.GetValue("invert");
                                        if (inv != null) cfg.Vertical.Invert = (Convert.ToInt32(inv) != 0);
                                    }
                                }

                                using (RegistryKey hk = root.OpenSubKey("Horizontal"))
                                {
                                    if (hk != null)
                                    {
                                        object en = hk.GetValue("enabled");
                                        if (en != null) cfg.Horizontal.Enabled = (Convert.ToInt32(en) != 0);
                                        object inv = hk.GetValue("invert");
                                        if (inv != null) cfg.Horizontal.Invert = (Convert.ToInt32(inv) != 0);
                                    }
                                }
                            }
                        }
                    }
                    catch { }

                    // Do not silently contend if standalone MarbleScrollPlus is actively running
                    if (LinuxlikeScrollEngine.DetectExternalProcess())
                    {
                        cfg.Enabled = false;
                    }

                    cfg.SaveToFile(path);
                    return cfg;
                }

                int configVersion = 1;
                foreach (string line in File.ReadAllLines(path, Encoding.UTF8))
                {
                    if (string.IsNullOrWhiteSpace(line)) continue;
                    string[] parts = line.Split('|');
                    if (parts.Length < 2) continue;
                    string key = parts[0].Trim();
                    string val = parts[1].Trim();

                    if (key == "ARGON_LINUXLIKE_SCROLL_CONFIG")
                    {
                        int.TryParse(val, out configVersion);
                    }
                    else if (key == "AutoStartWithArgon") bool.TryParse(val, out cfg.AutoStartWithArgon);
                    else if (key == "Enabled") bool.TryParse(val, out cfg.Enabled);
                    else if (key == "Trigger")
                    {
                        try { cfg.Trigger = (ScrollTriggerButton)Enum.Parse(typeof(ScrollTriggerButton), val, true); } catch { }
                    }
                    else if (key == "AxisLock") bool.TryParse(val, out cfg.AxisLock);
                    else if (key == "AxisDetectPx")
                    {
                        int v;
                        if (int.TryParse(val, out v)) cfg.AxisDetectPx = Math.Max(2, Math.Min(16, v));
                    }
                    else if (key == "VertEnabled") bool.TryParse(val, out cfg.Vertical.Enabled);
                    else if (key == "VertInvert") bool.TryParse(val, out cfg.Vertical.Invert);
                    else if (key == "VertSens")
                    {
                        int v;
                        if (int.TryParse(val, out v)) cfg.Vertical.Sensitivity = Math.Max(1, Math.Min(20, v));
                    }
                    else if (key == "VertSpeed")
                    {
                        int v;
                        if (int.TryParse(val, out v)) cfg.Vertical.Speed = Math.Max(1, Math.Min(30, v));
                    }
                    else if (key == "VertSmoothing") bool.TryParse(val, out cfg.Vertical.Smoothing);
                    else if (key == "HorizEnabled") bool.TryParse(val, out cfg.Horizontal.Enabled);
                    else if (key == "HorizInvert") bool.TryParse(val, out cfg.Horizontal.Invert);
                    else if (key == "HorizSens")
                    {
                        int v;
                        if (int.TryParse(val, out v)) cfg.Horizontal.Sensitivity = Math.Max(1, Math.Min(20, v));
                    }
                    else if (key == "HorizSpeed")
                    {
                        int v;
                        if (int.TryParse(val, out v)) cfg.Horizontal.Speed = Math.Max(1, Math.Min(30, v));
                    }
                    else if (key == "HorizSmoothing") bool.TryParse(val, out cfg.Horizontal.Smoothing);
                }

                // Upgrade untouched v1 quantized defaults cleanly to sharp 1:1 pixel mode
                if (configVersion < 2 && cfg.Vertical.Sensitivity == 3 && cfg.Vertical.Speed == 7 && !cfg.Vertical.Smoothing)
                {
                    cfg.Vertical.Sensitivity = 1;
                    cfg.Vertical.Speed = 8;
                    cfg.Vertical.Smoothing = true;
                    cfg.Horizontal.Sensitivity = 1;
                    cfg.Horizontal.Speed = 12;
                    cfg.Horizontal.Smoothing = true;
                    cfg.AxisDetectPx = 4;
                    cfg.SaveToFile(path);
                }
            }
            catch { }
            return cfg;
        }
    }

    /// <summary>
    /// High-responsiveness Windows WH_MOUSE_LL 1:1 scroll engine with fast directional axis lock,
    /// sub-pixel accumulation, zero-inertia reversal, and direct synchronous wheel dispatch.
    /// </summary>
    public class LinuxlikeScrollEngine : IDisposable
    {
        private IntPtr hookId = IntPtr.Zero;
        private uint hookThreadId = 0;
        private Thread hookThread;
        private Thread dispatchThread;
        private ManualResetEvent hookReadyEvent;
        private readonly AutoResetEvent dispatchWakeEvent = new AutoResetEvent(false);
        private volatile bool hookInstallSucceeded = false;
        private volatile bool stopRequested = false;

        private NativeMethods.LowLevelMouseProc hookCallback;
        private bool isScroll = false;
        private bool disableTriggerUp = false;
        private ScrollTriggerButton activeTrigger = ScrollTriggerButton.MiddleClick;
        private int startX, startY;
        private double fracX, fracY;
        private int lastDirX, lastDirY;
        private int lockedAxis; // 0: Undecided, 1: Horizontal (X), 2: Vertical (Y)
        private int netX, netY;
        private double recX, recY;

        private int pendingWheelX = 0;
        private int pendingWheelY = 0;
        private int pendingTapButton = 0; // 0: none, 1: Middle, 2: X1, 3: X2
        private int lastUiNotifyTick = 0;
        private int uiAccumX = 0;
        private int uiAccumY = 0;

        private readonly object syncLock = new object();

        private const int WHEEL_DELTA = 120;
        private const int MAX_STEP_PX = 120;
        private const double AXIS_LOCK_RATIO = 1.35;
        private const double AXIS_SOFT_WINDOW = 14.0;
        private const double AXIS_SWITCH_MIN = 8.0;
        private const double AXIS_SWITCH_RATIO = 1.75;

        private const ulong SYNTHETIC_TAG = 0x4152474EUL; // 'ARGN'
        private static readonly UIntPtr ARGON_SYNTHETIC_MARKER = new UIntPtr(SYNTHETIC_TAG);
        private static readonly int INPUT_SIZE = Marshal.SizeOf(typeof(NativeMethods.INPUT));

        public LinuxlikeScrollConfig Config { get; set; }
        public bool IsRunning
        {
            get { return !stopRequested && hookId != IntPtr.Zero && hookThread != null && hookThread.IsAlive; }
        }

        public event Action<bool> StateChanged;
        public event Action<int, int> Scrolled;

        public LinuxlikeScrollEngine(LinuxlikeScrollConfig config)
        {
            this.Config = config ?? new LinuxlikeScrollConfig();
            this.hookCallback = new NativeMethods.LowLevelMouseProc(this.HookProc);
        }

        /// <summary>
        /// Installs the global WH_MOUSE_LL hook on a dedicated STA native message-loop thread
        /// and dispatches coalesced SendInput events on a separate worker thread to prevent UI freezes.
        /// </summary>
        public bool Start()
        {
            bool startedOk = false;
            lock (syncLock)
            {
                if (!stopRequested && hookId != IntPtr.Zero && hookThread != null && hookThread.IsAlive)
                {
                    return true;
                }

                StopLocked();

                stopRequested = false;
                hookInstallSucceeded = false;
                hookId = IntPtr.Zero;
                hookThreadId = 0;
                isScroll = false;
                disableTriggerUp = false;
                pendingWheelX = 0;
                pendingWheelY = 0;
                pendingTapButton = 0;
                uiAccumX = 0;
                uiAccumY = 0;

                if (hookReadyEvent != null)
                {
                    try { hookReadyEvent.Close(); } catch { }
                    hookReadyEvent = null;
                }
                hookReadyEvent = new ManualResetEvent(false);

                dispatchThread = new Thread(DispatchLoop);
                dispatchThread.Name = "Argon-ScrollDispatch";
                dispatchThread.IsBackground = true;
                dispatchThread.Priority = ThreadPriority.AboveNormal;
                dispatchThread.Start();

                hookThread = new Thread(HookThreadLoop);
                hookThread.Name = "Argon-MouseHook";
                hookThread.IsBackground = true;
                hookThread.Priority = ThreadPriority.Highest;
                hookThread.SetApartmentState(ApartmentState.STA);
                hookThread.Start();

                hookReadyEvent.WaitOne(2500);
                startedOk = hookInstallSucceeded && hookId != IntPtr.Zero;

                if (!startedOk)
                {
                    StopLocked();
                }
            }

            Action<bool> handler = StateChanged;
            if (handler != null)
            {
                try { handler(startedOk); } catch { }
            }
            return startedOk;
        }

        public void Stop()
        {
            lock (syncLock)
            {
                StopLocked();
            }

            Action<bool> handler = StateChanged;
            if (handler != null)
            {
                try { handler(false); } catch { }
            }
        }

        private void StopLocked()
        {
            stopRequested = true;
            isScroll = false;
            disableTriggerUp = false;
            Interlocked.Exchange(ref pendingWheelX, 0);
            Interlocked.Exchange(ref pendingWheelY, 0);
            Interlocked.Exchange(ref pendingTapButton, 0);

            uint tid = hookThreadId;
            if (tid != 0)
            {
                try { NativeMethods.PostThreadMessage(tid, NativeMethods.WM_QUIT, UIntPtr.Zero, IntPtr.Zero); } catch { }
            }

            try { dispatchWakeEvent.Set(); } catch { }

            if (hookThread != null && Thread.CurrentThread != hookThread)
            {
                try { hookThread.Join(600); } catch { }
            }
            if (dispatchThread != null && Thread.CurrentThread != dispatchThread)
            {
                try { dispatchThread.Join(600); } catch { }
            }

            if (hookId != IntPtr.Zero)
            {
                try { NativeMethods.UnhookWindowsHookEx(hookId); } catch { }
                hookId = IntPtr.Zero;
            }

            hookThread = null;
            dispatchThread = null;
            hookThreadId = 0;

            if (hookReadyEvent != null)
            {
                try { hookReadyEvent.Close(); } catch { }
                hookReadyEvent = null;
            }
        }

        private void HookThreadLoop()
        {
            IntPtr installedHook = IntPtr.Zero;
            try
            {
                NativeMethods.MSG initMsg;
                NativeMethods.PeekMessage(out initMsg, IntPtr.Zero, 0, 0, NativeMethods.PM_NOREMOVE);
                hookThreadId = NativeMethods.GetCurrentThreadId();

                using (Process curProcess = Process.GetCurrentProcess())
                using (ProcessModule curModule = curProcess.MainModule)
                {
                    IntPtr hMod = NativeMethods.GetModuleHandle(curModule.ModuleName);
                    installedHook = NativeMethods.SetWindowsHookEx(NativeMethods.WH_MOUSE_LL, hookCallback, hMod, 0);
                }

                hookId = installedHook;
                hookInstallSucceeded = (installedHook != IntPtr.Zero);
            }
            catch
            {
                installedHook = IntPtr.Zero;
                hookId = IntPtr.Zero;
                hookInstallSucceeded = false;
            }
            finally
            {
                ManualResetEvent ev = hookReadyEvent;
                if (ev != null)
                {
                    try { ev.Set(); } catch { }
                }
            }

            if (installedHook == IntPtr.Zero)
            {
                return;
            }

            try
            {
                NativeMethods.MSG msg;
                int ret;
                while (!stopRequested && (ret = NativeMethods.GetMessage(out msg, IntPtr.Zero, 0, 0)) > 0)
                {
                    NativeMethods.TranslateMessage(ref msg);
                    NativeMethods.DispatchMessage(ref msg);
                }
            }
            catch { }
            finally
            {
                if (installedHook != IntPtr.Zero)
                {
                    try { NativeMethods.UnhookWindowsHookEx(installedHook); } catch { }
                    if (hookId == installedHook) hookId = IntPtr.Zero;
                }
            }
        }

        private void DispatchLoop()
        {
            while (!stopRequested)
            {
                try
                {
                    dispatchWakeEvent.WaitOne(250);
                }
                catch
                {
                    break;
                }

                if (stopRequested) break;

                int tap = Interlocked.Exchange(ref pendingTapButton, 0);
                if (tap != 0)
                {
                    SendSyntheticClick(tap);
                }

                while (!stopRequested)
                {
                    int dx = Interlocked.Exchange(ref pendingWheelX, 0);
                    int dy = Interlocked.Exchange(ref pendingWheelY, 0);
                    if (dx == 0 && dy == 0) break;

                    SendWheelBatch(dx, dy);

                    uiAccumX += dx;
                    uiAccumY += dy;
                    int nowTick = Environment.TickCount;
                    if (Math.Abs(nowTick - lastUiNotifyTick) >= 50)
                    {
                        lastUiNotifyTick = nowTick;
                        int repX = uiAccumX;
                        int repY = uiAccumY;
                        uiAccumX = 0;
                        uiAccumY = 0;
                        Action<int, int> scHandler = Scrolled;
                        if (scHandler != null)
                        {
                            try { scHandler(repX, repY); } catch { }
                        }
                    }

                    // Coalesce ultra-high polling rate bursts (~250Hz max dispatch cadence)
                    if (!stopRequested && (Thread.VolatileRead(ref pendingWheelX) != 0 || Thread.VolatileRead(ref pendingWheelY) != 0))
                    {
                        Thread.Sleep(4);
                    }
                }
            }
        }

        private static void SendWheelBatch(int dx, int dy)
        {
            int count = (dx != 0 ? 1 : 0) + (dy != 0 ? 1 : 0);
            if (count == 0) return;

            NativeMethods.INPUT[] inputs = new NativeMethods.INPUT[count];
            int idx = 0;
            if (dx != 0)
            {
                inputs[idx].type = NativeMethods.INPUT_MOUSE;
                inputs[idx].u.mi = new NativeMethods.MOUSEINPUT
                {
                    dx = 0,
                    dy = 0,
                    mouseData = dx,
                    dwFlags = NativeMethods.MOUSEEVENTF_HWHEEL,
                    time = 0,
                    dwExtraInfo = ARGON_SYNTHETIC_MARKER
                };
                idx++;
            }
            if (dy != 0)
            {
                inputs[idx].type = NativeMethods.INPUT_MOUSE;
                inputs[idx].u.mi = new NativeMethods.MOUSEINPUT
                {
                    dx = 0,
                    dy = 0,
                    mouseData = dy,
                    dwFlags = NativeMethods.MOUSEEVENTF_WHEEL,
                    time = 0,
                    dwExtraInfo = ARGON_SYNTHETIC_MARKER
                };
            }

            NativeMethods.SendInput((uint)count, inputs, INPUT_SIZE);
        }

        private static void SendSyntheticClick(int tapCode)
        {
            uint downFlag = NativeMethods.MOUSEEVENTF_MIDDLEDOWN;
            uint upFlag = NativeMethods.MOUSEEVENTF_MIDDLEUP;
            int mouseData = 0;

            if (tapCode == 2)
            {
                downFlag = NativeMethods.MOUSEEVENTF_XDOWN;
                upFlag = NativeMethods.MOUSEEVENTF_XUP;
                mouseData = 1;
            }
            else if (tapCode == 3)
            {
                downFlag = NativeMethods.MOUSEEVENTF_XDOWN;
                upFlag = NativeMethods.MOUSEEVENTF_XUP;
                mouseData = 2;
            }

            NativeMethods.INPUT[] inputs = new NativeMethods.INPUT[2];
            inputs[0].type = NativeMethods.INPUT_MOUSE;
            inputs[0].u.mi = new NativeMethods.MOUSEINPUT
            {
                dx = 0,
                dy = 0,
                mouseData = mouseData,
                dwFlags = downFlag,
                time = 0,
                dwExtraInfo = ARGON_SYNTHETIC_MARKER
            };
            inputs[1].type = NativeMethods.INPUT_MOUSE;
            inputs[1].u.mi = new NativeMethods.MOUSEINPUT
            {
                dx = 0,
                dy = 0,
                mouseData = mouseData,
                dwFlags = upFlag,
                time = 0,
                dwExtraInfo = ARGON_SYNTHETIC_MARKER
            };
            NativeMethods.SendInput(2U, inputs, INPUT_SIZE);
        }

        private IntPtr HookProc(int nCode, IntPtr wParam, IntPtr lParam)
        {
            if (nCode < 0 || stopRequested)
            {
                return NativeMethods.CallNextHookEx(hookId, nCode, wParam, lParam);
            }

            try
            {
                NativeMethods.MSLLHOOKSTRUCT hookStruct = (NativeMethods.MSLLHOOKSTRUCT)Marshal.PtrToStructure(lParam, typeof(NativeMethods.MSLLHOOKSTRUCT));

                // Always pass through synthetic mouse events emitted by Argon itself
                if (unchecked((ulong)hookStruct.dwExtraInfo.ToInt64()) == SYNTHETIC_TAG)
                {
                    return NativeMethods.CallNextHookEx(hookId, nCode, wParam, lParam);
                }

                LinuxlikeScrollConfig cfg = Config;
                if (cfg == null)
                {
                    return NativeMethods.CallNextHookEx(hookId, nCode, wParam, lParam);
                }

                int msg = unchecked((int)wParam.ToInt64());
                ScrollTriggerButton trigger = cfg.Trigger;
                bool isTriggerDown = false;
                bool isTriggerUp = false;

                if (trigger == ScrollTriggerButton.MiddleClick)
                {
                    isTriggerDown = (msg == NativeMethods.WM_MBUTTONDOWN);
                    isTriggerUp = (msg == NativeMethods.WM_MBUTTONUP);
                }
                else if (trigger == ScrollTriggerButton.XButton1)
                {
                    int btn = (int)((hookStruct.mouseData >> 16) & 0xFFFF);
                    isTriggerDown = (msg == NativeMethods.WM_XBUTTONDOWN && btn == 1);
                    isTriggerUp = (msg == NativeMethods.WM_XBUTTONUP && btn == 1);
                }
                else if (trigger == ScrollTriggerButton.XButton2)
                {
                    int btn = (int)((hookStruct.mouseData >> 16) & 0xFFFF);
                    isTriggerDown = (msg == NativeMethods.WM_XBUTTONDOWN && btn == 2);
                    isTriggerUp = (msg == NativeMethods.WM_XBUTTONUP && btn == 2);
                }

                if (isTriggerDown)
                {
                    isScroll = true;
                    disableTriggerUp = false;
                    activeTrigger = trigger;
                    startX = hookStruct.pt.x;
                    startY = hookStruct.pt.y;
                    fracX = 0.0;
                    fracY = 0.0;
                    lastDirX = 0;
                    lastDirY = 0;
                    lockedAxis = 0;
                    netX = 0;
                    netY = 0;
                    recX = 0.0;
                    recY = 0.0;
                    Interlocked.Exchange(ref pendingWheelX, 0);
                    Interlocked.Exchange(ref pendingWheelY, 0);
                    return new IntPtr(1);
                }

                // Ensure release still matches even if trigger dropdown changed mid-drag
                if (!isTriggerUp && isScroll)
                {
                    if (activeTrigger == ScrollTriggerButton.MiddleClick && msg == NativeMethods.WM_MBUTTONUP)
                        isTriggerUp = true;
                    else if (activeTrigger == ScrollTriggerButton.XButton1 && msg == NativeMethods.WM_XBUTTONUP && ((int)((hookStruct.mouseData >> 16) & 0xFFFF) == 1))
                        isTriggerUp = true;
                    else if (activeTrigger == ScrollTriggerButton.XButton2 && msg == NativeMethods.WM_XBUTTONUP && ((int)((hookStruct.mouseData >> 16) & 0xFFFF) == 2))
                        isTriggerUp = true;
                }

                if (isTriggerUp && (isScroll || trigger == activeTrigger))
                {
                    bool wasDragged = disableTriggerUp;
                    ScrollTriggerButton tapped = activeTrigger;
                    isScroll = false;
                    disableTriggerUp = false;

                    if (wasDragged)
                    {
                        return new IntPtr(1);
                    }
                    else
                    {
                        int tapCode = 1;
                        if (tapped == ScrollTriggerButton.XButton1) tapCode = 2;
                        else if (tapped == ScrollTriggerButton.XButton2) tapCode = 3;
                        Interlocked.Exchange(ref pendingTapButton, tapCode);
                        dispatchWakeEvent.Set();
                        return new IntPtr(1);
                    }
                }
                else if (isScroll && msg == NativeMethods.WM_MOUSEMOVE)
                {
                    // Measure single-packet displacement against live OS cursor position to eliminate anchor-drift feedback loops
                    NativeMethods.POINT curPt;
                    int baseX = startX;
                    int baseY = startY;
                    if (NativeMethods.GetCursorPos(out curPt))
                    {
                        baseX = curPt.x;
                        baseY = curPt.y;
                    }

                    int stepX = hookStruct.pt.x - baseX;
                    int stepY = hookStruct.pt.y - baseY;

                    if (stepX > MAX_STEP_PX) stepX = MAX_STEP_PX;
                    else if (stepX < -MAX_STEP_PX) stepX = -MAX_STEP_PX;
                    if (stepY > MAX_STEP_PX) stepY = MAX_STEP_PX;
                    else if (stepY < -MAX_STEP_PX) stepY = -MAX_STEP_PX;

                    if (stepX == 0 && stepY == 0)
                    {
                        return new IntPtr(1);
                    }

                    double decay = Math.Exp(-(Math.Abs(stepX) + Math.Abs(stepY)) / AXIS_SOFT_WINDOW);
                    recX = recX * decay + stepX;
                    recY = recY * decay + stepY;

                    bool axisLockEnabled = cfg.AxisLock && cfg.Horizontal.Enabled && cfg.Vertical.Enabled;
                    bool allowX = true;
                    bool allowY = true;
                    bool axisUndecided = false;
                    int moveX = stepX;
                    int moveY = stepY;

                    if (axisLockEnabled)
                    {
                        if (lockedAxis == 0)
                        {
                            netX += stepX;
                            netY += stepY;
                            int absNetX = Math.Abs(netX);
                            int absNetY = Math.Abs(netY);
                            int totalNet = absNetX + absNetY;
                            int lockMin = Math.Max(2, Math.Min(16, cfg.AxisDetectPx));
                            int lockForce = Math.Max(4, lockMin * 2);
                            bool dominant = (absNetY >= AXIS_LOCK_RATIO * absNetX) || (absNetX >= AXIS_LOCK_RATIO * absNetY);
                            if ((totalNet >= lockMin && dominant) || totalNet >= lockForce)
                            {
                                lockedAxis = (absNetY >= absNetX) ? 2 : 1; // 1 = Horizontal (X), 2 = Vertical (Y)
                                moveX = (lockedAxis == 1) ? netX : 0;
                                moveY = (lockedAxis == 2) ? netY : 0;
                                disableTriggerUp = true;
                            }
                        }
                        else
                        {
                            double absRecX = Math.Abs(recX);
                            double absRecY = Math.Abs(recY);
                            int switchTarget = 0;

                            if (lockedAxis == 2 && absRecX >= AXIS_SWITCH_MIN && absRecX >= AXIS_SWITCH_RATIO * absRecY)
                            {
                                switchTarget = 1;
                            }
                            else if (lockedAxis == 1 && absRecY >= AXIS_SWITCH_MIN && absRecY >= AXIS_SWITCH_RATIO * absRecX)
                            {
                                switchTarget = 2;
                            }

                            if (switchTarget != 0)
                            {
                                lockedAxis = switchTarget;
                                fracX = 0.0;
                                fracY = 0.0;
                                lastDirX = 0;
                                lastDirY = 0;
                                if (switchTarget == 2) moveY = (int)Math.Round(recY);
                                else moveX = (int)Math.Round(recX);
                            }
                        }

                        axisUndecided = (lockedAxis == 0);
                        allowX = (lockedAxis == 1);
                        allowY = (lockedAxis == 2);
                    }
                    else
                    {
                        if (stepX != 0 || stepY != 0) disableTriggerUp = true;
                    }

                    bool didQueue = false;

                    if (cfg.Horizontal.Enabled && allowX && !axisUndecided && moveX != 0)
                    {
                        int scrollDelta = ComputeAxisWheelDelta(cfg.Horizontal, moveX, ref fracX, ref lastDirX);
                        if (scrollDelta != 0)
                        {
                            Interlocked.Add(ref pendingWheelX, scrollDelta);
                            didQueue = true;
                            disableTriggerUp = true;
                        }
                    }

                    if (cfg.Vertical.Enabled && allowY && !axisUndecided && moveY != 0)
                    {
                        int scrollDelta = ComputeAxisWheelDelta(cfg.Vertical, moveY, ref fracY, ref lastDirY);
                        if (scrollDelta != 0)
                        {
                            Interlocked.Add(ref pendingWheelY, scrollDelta);
                            didQueue = true;
                            disableTriggerUp = true;
                        }
                    }

                    if (didQueue)
                    {
                        try { dispatchWakeEvent.Set(); } catch { }
                    }

                    return new IntPtr(1);
                }
            }
            catch { }

            return NativeMethods.CallNextHookEx(hookId, nCode, wParam, lParam);
        }

        private static int ComputeAxisWheelDelta(LinuxlikeScrollAxisConfig axis, int movePx, ref double frac, ref int lastDir)
        {
            int dir = movePx > 0 ? 1 : -1;
            if (lastDir != 0 && dir != lastDir) frac = 0.0;
            lastDir = dir;

            double rawUnits = (axis.Invert ? -1.0 : 1.0) * movePx * (double)axis.Speed / Math.Max(1.0, (double)axis.Sensitivity);
            frac += rawUnits;

            int scrollDelta = 0;
            if (axis.Smoothing)
            {
                scrollDelta = (int)Math.Truncate(frac);
                frac -= scrollDelta;
            }
            else
            {
                int notches = (int)Math.Truncate(frac / WHEEL_DELTA);
                if (notches != 0)
                {
                    scrollDelta = notches * WHEEL_DELTA;
                    frac -= scrollDelta;
                }
            }
            return scrollDelta;
        }

        public static bool DetectExternalProcess()
        {
            try
            {
                Process[] p1 = Process.GetProcessesByName("MarbleScrollPlus");
                if (p1 != null && p1.Length > 0) return true;
                Process[] p2 = Process.GetProcessesByName("MarbleScroll");
                if (p2 != null && p2.Length > 0) return true;
            }
            catch { }
            return false;
        }

        public static bool StopExternalProcessAndTask(out string message)
        {
            message = "";
            try
            {
                foreach (Process p in Process.GetProcessesByName("MarbleScrollPlus"))
                {
                    try { p.Kill(); p.WaitForExit(1500); } catch { }
                }
                foreach (Process p in Process.GetProcessesByName("MarbleScroll"))
                {
                    try { p.Kill(); p.WaitForExit(1500); } catch { }
                }

                try
                {
                    ProcessStartInfo psi = new ProcessStartInfo("schtasks", "/Delete /TN \"MarbleScrollPlus\" /F")
                    {
                        CreateNoWindow = true,
                        UseShellExecute = false
                    };
                    using (Process p = Process.Start(psi))
                    {
                        if (p != null) p.WaitForExit(3000);
                    }
                }
                catch { }

                message = "Harici MarbleScrollPlus süreci durduruldu ve zamanlanmış görevi kaldırıldı.";
                return true;
            }
            catch (Exception ex)
            {
                message = "Harici süreç durdurulurken hata: " + ex.Message;
                return false;
            }
        }

        public void Dispose()
        {
            Stop();
            try { dispatchWakeEvent.Close(); } catch { }
        }
    }

    #endregion

    public class LibreHardwareSensorEngine : IDisposable
    {
        private Computer computer;
        private bool isInitialized = false;
        private readonly object syncLock = new object();

        public float CpuPackageTemp = -1f;
        public float CpuTotalLoad = -1f;
        public float CpuClockAvgMhz = -1f;
        public float CpuEffectiveClockMhz = -1f;
        public float CpuPowerWatts = -1f;
        public float CpuCoreVoltage = -1f;
        public float GpuCoreTemp = -1f;
        public float GpuMemoryTemp = -1f;
        public float GpuHotspotTemp = -1f;
        public float GpuCoreLoad = -1f;
        public float GpuCoreClockMhz = -1f;
        public float GpuMemClockMhz = -1f;
        public float GpuFanRpm = -1f;
        public float GpuCoreVoltage = -1f;
        public float GpuMemUsedMb = 0f;
        public float GpuMemTotalMb = 0f;
        public float GpuPowerWatts = 0f;
        public float MemoryUsedGb = -1f;
        public float MemoryTotalGb = -1f;
        public float MemoryLoadPct = -1f;
        public List<string> StorageTemps = new List<string>();
        public string CpuHwName = "";
        public string GpuHwName = "";

        private PerformanceCounter fallbackCpuCounter;

        public void Initialize()
        {
            lock (syncLock)
            {
                if (isInitialized) return;
                try
                {
                    fallbackCpuCounter = new PerformanceCounter("Processor", "% Processor Time", "_Total", true);
                    fallbackCpuCounter.NextValue();
                }
                catch { }

                try
                {
                    computer = new Computer
                    {
                        IsCpuEnabled = true,
                        IsGpuEnabled = true,
                        IsMotherboardEnabled = true,
                        IsMemoryEnabled = true,
                        IsStorageEnabled = true,
                        IsNetworkEnabled = false,
                        IsControllerEnabled = false
                    };
                    computer.Open();
                    isInitialized = true;
                }
                catch { }
            }
        }

        public void PollSensors()
        {
            PollSensors(true, true, true);
        }

        public void PollSensors(bool readCpu, bool readGpuCore, bool readGpuMemHotspot)
        {
            if (!readCpu && !readGpuCore && !readGpuMemHotspot) return;

            lock (syncLock)
            {
                if (!isInitialized) Initialize();

                float cTemp = -1f, cLoad = -1f, cClock = -1f, cEffClock = -1f, cWatts = -1f, cVolt = -1f;
                float gCoreTemp = -1f, gMemTemp = -1f, gHotTemp = -1f, gCoreLoad = -1f, gWatts = 0f;
                float gClock = -1f, gMemClock = -1f, gFan = -1f, gVolt = -1f;
                float memUsed = 0f, memTotal = 0f;
                float ramUsed = -1f, ramAvail = -1f, ramPct = -1f;
                float mbCpuTemp = -1f;
                List<string> driveTemps = new List<string>();

                if (computer != null)
                {
                    try
                    {
                        foreach (IHardware hw in computer.Hardware)
                        {
                            if (hw.HardwareType == HardwareType.Cpu && readCpu)
                            {
                                hw.Update();
                                CpuHwName = hw.Name;
                                float maxCoreClock = -1f;
                                foreach (ISensor s in hw.Sensors)
                                {
                                    if (!s.Value.HasValue) continue;
                                    float val = s.Value.Value;
                                    if (s.SensorType == SensorType.Load && s.Name.IndexOf("Total", StringComparison.OrdinalIgnoreCase) >= 0)
                                        cLoad = val;
                                    else if (s.SensorType == SensorType.Temperature && val > 1f && val < 130f)
                                    {
                                        if (s.Name.IndexOf("Tctl", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                            s.Name.IndexOf("Package", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                            s.Name.IndexOf("Core", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                            cTemp < 0f)
                                        {
                                            cTemp = val;
                                        }
                                    }
                                    else if (s.SensorType == SensorType.Clock && val > 50f)
                                    {
                                        if (s.Name.IndexOf("Average Effective", StringComparison.OrdinalIgnoreCase) >= 0)
                                            cEffClock = val;
                                        else if (s.Name.IndexOf("Average", StringComparison.OrdinalIgnoreCase) >= 0)
                                            cClock = val;
                                        else if (s.Name.IndexOf("Core", StringComparison.OrdinalIgnoreCase) >= 0 && s.Name.IndexOf("Bus", StringComparison.OrdinalIgnoreCase) < 0)
                                            maxCoreClock = Math.Max(maxCoreClock, val);
                                    }
                                    else if (s.SensorType == SensorType.Power && val > 0f)
                                    {
                                        if (s.Name.IndexOf("Package", StringComparison.OrdinalIgnoreCase) >= 0 || cWatts < 0f)
                                            cWatts = val;
                                    }
                                    else if (s.SensorType == SensorType.Voltage && val > 0.2f && val < 2.5f)
                                    {
                                        if (s.Name.IndexOf("Core", StringComparison.OrdinalIgnoreCase) >= 0 && s.Name.IndexOf("VID", StringComparison.OrdinalIgnoreCase) < 0)
                                            cVolt = val;
                                        else if (cVolt < 0f && s.Name.IndexOf("VID", StringComparison.OrdinalIgnoreCase) >= 0)
                                            cVolt = val;
                                    }
                                }
                                if (cClock < 0f && maxCoreClock > 0f) cClock = maxCoreClock;
                            }
                            else if (hw.HardwareType == HardwareType.Motherboard && readCpu && cTemp <= 1f)
                            {
                                hw.Update();
                                foreach (IHardware sub in hw.SubHardware)
                                {
                                    sub.Update();
                                    foreach (ISensor s in sub.Sensors)
                                    {
                                        if (s.SensorType == SensorType.Temperature && s.Value.HasValue && s.Value.Value > 10f && s.Value.Value < 115f)
                                        {
                                            if (s.Name.IndexOf("CPU", StringComparison.OrdinalIgnoreCase) >= 0 || mbCpuTemp < 0f)
                                                mbCpuTemp = s.Value.Value;
                                        }
                                    }
                                }
                            }
                            else if (hw.HardwareType == HardwareType.Memory)
                            {
                                hw.Update();
                                if (hw.Name.IndexOf("Virtual", StringComparison.OrdinalIgnoreCase) < 0)
                                {
                                    foreach (ISensor s in hw.Sensors)
                                    {
                                        if (!s.Value.HasValue) continue;
                                        if (s.SensorType == SensorType.Data && s.Name.Equals("Memory Used", StringComparison.OrdinalIgnoreCase))
                                            ramUsed = s.Value.Value;
                                        else if (s.SensorType == SensorType.Data && s.Name.Equals("Memory Available", StringComparison.OrdinalIgnoreCase))
                                            ramAvail = s.Value.Value;
                                        else if (s.SensorType == SensorType.Load && s.Name.Equals("Memory", StringComparison.OrdinalIgnoreCase))
                                            ramPct = s.Value.Value;
                                    }
                                }
                            }
                            else if (hw.HardwareType == HardwareType.Storage)
                            {
                                hw.Update();
                                float sTemp = -1f;
                                foreach (ISensor s in hw.Sensors)
                                {
                                    if (s.SensorType == SensorType.Temperature && s.Value.HasValue && s.Value.Value > 0f && s.Value.Value < 120f)
                                    {
                                        if (s.Name.Equals("Temperature", StringComparison.OrdinalIgnoreCase) || sTemp < 0f)
                                            sTemp = s.Value.Value;
                                    }
                                }
                                if (sTemp > 0f)
                                    driveTemps.Add(string.Format("{0}: {1:0}°C", hw.Name, sTemp));
                            }
                            else if ((hw.HardwareType == HardwareType.GpuAmd || hw.HardwareType == HardwareType.GpuNvidia || hw.HardwareType == HardwareType.GpuIntel) &&
                                     (readGpuCore || readGpuMemHotspot))
                            {
                                hw.Update();
                                GpuHwName = hw.Name;
                                float d3dMax = -1f;
                                foreach (ISensor s in hw.Sensors)
                                {
                                    if (!s.Value.HasValue) continue;
                                    float val = s.Value.Value;
                                    if (s.SensorType == SensorType.Temperature && val > 1f && val < 140f)
                                    {
                                        if (s.Name.IndexOf("Hot Spot", StringComparison.OrdinalIgnoreCase) >= 0 || s.Name.IndexOf("HotSpot", StringComparison.OrdinalIgnoreCase) >= 0)
                                            gHotTemp = val;
                                        else if (s.Name.IndexOf("Memory", StringComparison.OrdinalIgnoreCase) >= 0 || s.Name.IndexOf("VRAM", StringComparison.OrdinalIgnoreCase) >= 0)
                                            gMemTemp = val;
                                        else if (s.Name.IndexOf("Core", StringComparison.OrdinalIgnoreCase) >= 0 || gCoreTemp < 0f)
                                            gCoreTemp = val;
                                    }
                                    else if (s.SensorType == SensorType.Load)
                                    {
                                        if (s.Name.Equals("GPU Core", StringComparison.OrdinalIgnoreCase))
                                            gCoreLoad = Math.Max(gCoreLoad, val);
                                        else if (s.Name.IndexOf("D3D", StringComparison.OrdinalIgnoreCase) >= 0)
                                            d3dMax = Math.Max(d3dMax, val);
                                    }
                                    else if (s.SensorType == SensorType.Clock)
                                    {
                                        if (s.Name.IndexOf("Core", StringComparison.OrdinalIgnoreCase) >= 0)
                                            gClock = val;
                                        else if (s.Name.IndexOf("Memory", StringComparison.OrdinalIgnoreCase) >= 0)
                                            gMemClock = val;
                                    }
                                    else if (s.SensorType == SensorType.Fan && gFan < 0f)
                                    {
                                        gFan = val;
                                    }
                                    else if (s.SensorType == SensorType.Voltage && val > 0.1f && val < 3.0f && gVolt < 0f)
                                    {
                                        gVolt = val;
                                    }
                                    else if (s.SensorType == SensorType.SmallData)
                                    {
                                        if (s.Name.Equals("GPU Memory Used", StringComparison.OrdinalIgnoreCase) || s.Name.Equals("D3D Dedicated Memory Used", StringComparison.OrdinalIgnoreCase))
                                            memUsed = Math.Max(memUsed, val);
                                        else if (s.Name.Equals("GPU Memory Total", StringComparison.OrdinalIgnoreCase) || s.Name.Equals("D3D Dedicated Memory Total", StringComparison.OrdinalIgnoreCase))
                                            memTotal = Math.Max(memTotal, val);
                                    }
                                    else if (s.SensorType == SensorType.Power)
                                    {
                                        gWatts = Math.Max(gWatts, val);
                                    }
                                }
                                if (gCoreLoad < 0f && d3dMax >= 0f) gCoreLoad = d3dMax;
                            }
                        }
                    }
                    catch { }
                }

                if (readCpu)
                {
                    if (cTemp <= 1f && mbCpuTemp > 1f) cTemp = mbCpuTemp;
                    if (cLoad < 0f && fallbackCpuCounter != null)
                    {
                        try { cLoad = fallbackCpuCounter.NextValue(); } catch { cLoad = 0f; }
                    }
                    CpuPackageTemp = cTemp;
                    CpuTotalLoad = cLoad >= 0f ? Math.Max(0f, Math.Min(100f, cLoad)) : -1f;
                    CpuClockAvgMhz = cClock;
                    CpuEffectiveClockMhz = cEffClock;
                    CpuPowerWatts = cWatts;
                    CpuCoreVoltage = cVolt;
                }

                if (readGpuCore || readGpuMemHotspot)
                {
                    GpuCoreTemp = gCoreTemp;
                    GpuMemoryTemp = gMemTemp;
                    GpuHotspotTemp = gHotTemp;
                    GpuCoreLoad = gCoreLoad >= 0f ? Math.Max(0f, Math.Min(100f, gCoreLoad)) : -1f;
                    GpuCoreClockMhz = gClock;
                    GpuMemClockMhz = gMemClock;
                    GpuFanRpm = gFan;
                    GpuCoreVoltage = gVolt;
                    GpuMemUsedMb = memUsed;
                    GpuMemTotalMb = memTotal;
                    GpuPowerWatts = gWatts;
                }

                if (ramUsed >= 0f && ramAvail >= 0f)
                {
                    MemoryUsedGb = ramUsed;
                    MemoryTotalGb = ramUsed + ramAvail;
                    MemoryLoadPct = ramPct;
                }
                StorageTemps = driveTemps;
            }
        }

        public void Dispose()
        {
            lock (syncLock)
            {
                try { if (computer != null) computer.Close(); } catch { }
                try { if (fallbackCpuCounter != null) fallbackCpuCounter.Dispose(); } catch { }
                isInitialized = false;
            }
        }
    }

    public class StateVault
    {
        private readonly string journalPath;
        public Dictionary<string, RegistryBackupEntry> RegistryBackups = new Dictionary<string, RegistryBackupEntry>(StringComparer.OrdinalIgnoreCase);
        public Dictionary<int, ProcessBackupEntry> ProcessBackups = new Dictionary<int, ProcessBackupEntry>();

        public Guid OriginalPowerScheme = Guid.Empty;
        public Guid SessionCustomPowerScheme = Guid.Empty;
        public Dictionary<string, uint> PowerSettingRequests = new Dictionary<string, uint>();
        public Dictionary<string, uint> PowerSettingRequestsDC = new Dictionary<string, uint>();

        public int[] OriginalMouseAccel = new int[3];
        public int OriginalMouseSensitivity = 10;
        public int OriginalMouseHoverTime = 400;
        public int OriginalKeyboardDelay = 1;
        public int OriginalKeyboardSpeed = 31;
        public NativeMethods.FILTERKEYS OriginalFilterKeys;
        public bool MouseSpiModified = false;
        public bool KeyboardSpiModified = false;
        public bool FilterKeysModified = false;

        public bool NetshModified = false;
        public bool NetshBaselineCaptured = false;
        public string OrigAutoTuning = "normal";
        public string OrigEcn = "disabled";
        public string OrigTimestamps = "disabled";
        public string OrigRsc = "enabled";
        public string OrigRss = "enabled";
        public string OrigNonSack = "disabled";
        public string OrigInitialRto = "3000";
        public string OrigMaxSyn = "2";

        public bool DnsModified = false;
        public string ActiveAdapterName = "Ethernet";
        public List<string> OriginalDnsServers = new List<string>();
        public bool OriginalDnsWasDhcp = true;

        public Dictionary<string, string> LearnedTweakSummaries = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        public bool LoadedFromPersistedProfile = false;
        public bool BaselineRecapturedFresh = false; // journal was missing -> current (possibly tweaked) state became the baseline

        public StateVault()
        {
            string dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "UltraLowLatencyArgon");
            if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
            journalPath = Path.Combine(dir, "original_baseline_backup.txt");

            CaptureInitialSystemBaseline();
            LoadPersistedBaselineIfPresent();
        }

        private void CaptureInitialSystemBaseline()
        {
            try
            {
                IntPtr pGuid;
                if (NativeMethods.PowerGetActiveScheme(IntPtr.Zero, out pGuid) == 0 && pGuid != IntPtr.Zero)
                {
                    OriginalPowerScheme = (Guid)Marshal.PtrToStructure(pGuid, typeof(Guid));
                    NativeMethods.LocalFree(pGuid);
                }
            }
            catch { }

            try
            {
                NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETMOUSE, 0, OriginalMouseAccel, 0);
                NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETMOUSESPEED, 0, out OriginalMouseSensitivity, 0);
                NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETMOUSEHOVERTIME, 0, out OriginalMouseHoverTime, 0);
                NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETKEYBOARDDELAY, 0, out OriginalKeyboardDelay, 0);
                NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETKEYBOARDSPEED, 0, out OriginalKeyboardSpeed, 0);

                OriginalFilterKeys = new NativeMethods.FILTERKEYS();
                OriginalFilterKeys.cbSize = (uint)Marshal.SizeOf(typeof(NativeMethods.FILTERKEYS));
                NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETFILTERKEYS, OriginalFilterKeys.cbSize, ref OriginalFilterKeys, 0);

                // If click sound (FKF_CLICKON = 0x40) or hotkey beep (0x10) was accidentally active, silence it immediately!
                if ((OriginalFilterKeys.dwFlags & 0x50u) != 0)
                {
                    OriginalFilterKeys.dwFlags &= ~0x50u;
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETFILTERKEYS, OriginalFilterKeys.cbSize, ref OriginalFilterKeys, NativeMethods.SPIF_SENDCHANGE);
                }
                // Baseline should always represent standard silent keyboard state when reverting
                OriginalFilterKeys.dwFlags = 2; // FKF_AVAILABLE only (FilterKeys OFF, Click OFF)
                OriginalFilterKeys.iWaitMSec = 0;
                OriginalFilterKeys.iDelayMSec = 1000;
                OriginalFilterKeys.iRepeatMSec = 500;
                OriginalFilterKeys.iBounceMSec = 0;
            }
            catch { }

            try
            {
                foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
                {
                    if (ni.OperationalStatus == OperationalStatus.Up &&
                        ni.NetworkInterfaceType != NetworkInterfaceType.Loopback &&
                        ni.NetworkInterfaceType != NetworkInterfaceType.Tunnel)
                    {
                        ActiveAdapterName = ni.Name;
                        IPInterfaceProperties ipProps = ni.GetIPProperties();
                        foreach (var dns in ipProps.DnsAddresses)
                        {
                            if (dns.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
                                OriginalDnsServers.Add(dns.ToString());
                        }
                        using (RegistryKey k = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\" + ni.Id))
                        {
                            if (k != null)
                            {
                                string ns = k.GetValue("NameServer", "") as string;
                                OriginalDnsWasDhcp = string.IsNullOrEmpty(ns);
                            }
                        }
                        break;
                    }
                }
            }
            catch { }

            try
            {
                string tcpGlobalOut = RunCmdCaptureOutput("netsh", "int tcp show global");
                if (!string.IsNullOrEmpty(tcpGlobalOut))
                {
                    string[] lines = tcpGlobalOut.Split(new char[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                    foreach (string rawLine in lines)
                    {
                        int colon = rawLine.IndexOf(':');
                        if (colon <= 0 || colon >= rawLine.Length - 1) continue;
                        string k = rawLine.Substring(0, colon).Trim().ToLowerInvariant();
                        string v = rawLine.Substring(colon + 1).Trim().ToLowerInvariant();
                        if (k.Contains("auto-tuning") || k.Contains("otomatik")) OrigAutoTuning = v;
                        else if (k.Contains("ecn")) OrigEcn = v;
                        else if (k.Contains("timestamps") || k.Contains("zaman")) OrigTimestamps = v;
                        else if (k.Contains("coalescing")) OrigRsc = v;
                        else if (k.Contains("scaling state")) OrigRss = v;
                        else if (k.Contains("non sack") || k.Contains("nonsack")) OrigNonSack = v;
                        else if (k.Contains("initial rto")) OrigInitialRto = v.Replace("ms", "").Trim();
                        else if (k.Contains("syn retransmissions")) OrigMaxSyn = v;
                    }
                    NetshBaselineCaptured = true;
                }
            }
            catch { }
        }

        private void LoadPersistedBaselineIfPresent()
        {
            try
            {
                if (!File.Exists(journalPath))
                {
                    BaselineRecapturedFresh = true;
                    SaveJournal();
                    return;
                }
                string[] lines = File.ReadAllLines(journalPath, Encoding.UTF8);
                foreach (string line in lines)
                {
                    if (string.IsNullOrWhiteSpace(line)) continue;
                    string[] parts = line.Split(new char[] { '|' }, 9);
                    if (parts[0] == "POWERSCHEME" && parts.Length >= 2)
                    {
                        Guid g;
                        if (Guid.TryParse(parts[1], out g) && g != Guid.Empty)
                            OriginalPowerScheme = g;
                    }
                    else if (parts[0] == "CUSTOMSCHEME" && parts.Length >= 2)
                    {
                        Guid g;
                        if (Guid.TryParse(parts[1], out g) && g != Guid.Empty)
                            SessionCustomPowerScheme = g;
                    }
                    else if (parts[0] == "MOUSE_SPI" && parts.Length >= 6)
                    {
                        OriginalMouseAccel = new int[] { int.Parse(parts[1]), int.Parse(parts[2]), int.Parse(parts[3]) };
                        OriginalMouseSensitivity = int.Parse(parts[4]);
                        OriginalMouseHoverTime = int.Parse(parts[5]);
                        MouseSpiModified = true;
                    }
                    else if (parts[0] == "KBD_SPI" && parts.Length >= 3)
                    {
                        OriginalKeyboardDelay = int.Parse(parts[1]);
                        OriginalKeyboardSpeed = int.Parse(parts[2]);
                        KeyboardSpiModified = true;
                    }
                    else if (parts[0] == "FILTERKEYS_SPI" && parts.Length >= 6)
                    {
                        OriginalFilterKeys = new NativeMethods.FILTERKEYS
                        {
                            cbSize = (uint)Marshal.SizeOf(typeof(NativeMethods.FILTERKEYS)),
                            dwFlags = 2, // Always restore to silent FilterKeys OFF
                            iWaitMSec = 0,
                            iDelayMSec = 1000,
                            iRepeatMSec = 500,
                            iBounceMSec = 0
                        };
                        FilterKeysModified = true;
                    }
                    else if (parts[0] == "NETSH_BASE" && parts.Length >= 9)
                    {
                        OrigAutoTuning = parts[1];
                        OrigEcn = parts[2];
                        OrigTimestamps = parts[3];
                        OrigRsc = parts[4];
                        OrigRss = parts[5];
                        OrigNonSack = parts[6];
                        OrigInitialRto = parts[7];
                        OrigMaxSyn = parts[8];
                        NetshBaselineCaptured = true;
                    }
                    else if (parts[0] == "LEARNED_DEFAULT" && parts.Length >= 3)
                    {
                        LearnedTweakSummaries[parts[1]] = parts[2];
                    }
                    else if (parts[0] == "REG" && parts.Length >= 6)
                    {
                        string hive = parts[1];
                        string subKey = parts[2];
                        string valName = parts[3];
                        bool existed = bool.Parse(parts[4]);
                        RegistryValueKind kind = (RegistryValueKind)Enum.Parse(typeof(RegistryValueKind), parts[5]);
                        string rawVal = parts.Length >= 7 ? parts[6] : "";
                        string friendly = parts.Length >= 8 ? parts[7] : "Kayıt Defteri Ayarı";
                        string keyId = hive + "\\" + subKey + "\\" + valName;
                        if (!RegistryBackups.ContainsKey(keyId))
                        {
                            RegistryBackups[keyId] = new RegistryBackupEntry
                            {
                                HiveName = hive,
                                SubKey = subKey,
                                ValueName = valName,
                                ExistedBefore = existed,
                                Kind = kind,
                                SerializedValue = rawVal,
                                CurrentAppliedSummary = ReadRegistryDisplay(hive, subKey, valName, rawVal),
                                FriendlyTweakName = friendly
                            };
                        }
                    }
                }
                LoadedFromPersistedProfile = true;
            }
            catch { }
        }

        public void LearnMachineDefaultsForCatalog(List<TweakDefinition> tweaks)
        {
            bool newlyLearned = false;
            foreach (var t in tweaks)
            {
                try
                {
                    if (LearnedTweakSummaries.ContainsKey(t.Id) && !string.IsNullOrEmpty(LearnedTweakSummaries[t.Id]))
                    {
                        t.CapturedOriginalSummary = LearnedTweakSummaries[t.Id];
                    }
                    else
                    {
                        string queried = t.QueryOriginalOrDefaultSummary != null ? t.QueryOriginalOrDefaultSummary() : "Varsayılan";
                        t.CapturedOriginalSummary = queried;
                        LearnedTweakSummaries[t.Id] = queried;
                        newlyLearned = true;
                    }
                }
                catch { }
            }
            if (newlyLearned)
                SaveJournal();
        }

        public string ReadPowerAcSettingDisplay(Guid subGroup, Guid setting, string fallback)
        {
            try
            {
                Guid scheme = OriginalPowerScheme;
                if (scheme == Guid.Empty)
                {
                    IntPtr pGuid;
                    if (NativeMethods.PowerGetActiveScheme(IntPtr.Zero, out pGuid) == 0 && pGuid != IntPtr.Zero)
                    {
                        scheme = (Guid)Marshal.PtrToStructure(pGuid, typeof(Guid));
                        NativeMethods.LocalFree(pGuid);
                    }
                }
                if (scheme != Guid.Empty)
                {
                    uint acVal;
                    if (NativeMethods.PowerReadACValueIndex(IntPtr.Zero, ref scheme, ref subGroup, ref setting, out acVal) == 0)
                        return acVal.ToString();
                }
            }
            catch { }
            return fallback;
        }

        public bool TryReadActivePowerValues(Guid subGroup, Guid setting, out uint acVal, out uint dcVal)
        {
            acVal = 0;
            dcVal = 0;
            try
            {
                IntPtr pGuid;
                if (NativeMethods.PowerGetActiveScheme(IntPtr.Zero, out pGuid) == 0 && pGuid != IntPtr.Zero)
                {
                    Guid scheme = (Guid)Marshal.PtrToStructure(pGuid, typeof(Guid));
                    NativeMethods.LocalFree(pGuid);
                    uint a = 0, d = 0;
                    bool okA = (NativeMethods.PowerReadACValueIndex(IntPtr.Zero, ref scheme, ref subGroup, ref setting, out a) == 0);
                    bool okD = (NativeMethods.PowerReadDCValueIndex(IntPtr.Zero, ref scheme, ref subGroup, ref setting, out d) == 0);
                    if (okA || okD)
                    {
                        acVal = okA ? a : d;
                        dcVal = okD ? d : a;
                        return true;
                    }
                }
            }
            catch { }
            return false;
        }

        public string GetActivePowerSchemeInfo(out Guid activeGuid)
        {
            activeGuid = Guid.Empty;
            try
            {
                IntPtr pGuid;
                if (NativeMethods.PowerGetActiveScheme(IntPtr.Zero, out pGuid) == 0 && pGuid != IntPtr.Zero)
                {
                    activeGuid = (Guid)Marshal.PtrToStructure(pGuid, typeof(Guid));
                    NativeMethods.LocalFree(pGuid);

                    StringBuilder sb = new StringBuilder(256);
                    uint bufSize = (uint)sb.Capacity * 2;
                    if (NativeMethods.PowerReadFriendlyName(IntPtr.Zero, ref activeGuid, IntPtr.Zero, IntPtr.Zero, sb, ref bufSize) == 0 && sb.Length > 0)
                    {
                        return sb.ToString();
                    }
                }
            }
            catch { }
            return "Aktif Güç Planı";
        }

        public void SaveJournal()
        {
            try
            {
                List<string> lines = new List<string>();
                if (OriginalPowerScheme != Guid.Empty)
                    lines.Add("POWERSCHEME|" + OriginalPowerScheme.ToString());
                if (SessionCustomPowerScheme != Guid.Empty)
                    lines.Add("CUSTOMSCHEME|" + SessionCustomPowerScheme.ToString());
                if (MouseSpiModified)
                    lines.Add(string.Format("MOUSE_SPI|{0}|{1}|{2}|{3}|{4}", OriginalMouseAccel[0], OriginalMouseAccel[1], OriginalMouseAccel[2], OriginalMouseSensitivity, OriginalMouseHoverTime));
                if (KeyboardSpiModified)
                    lines.Add(string.Format("KBD_SPI|{0}|{1}", OriginalKeyboardDelay, OriginalKeyboardSpeed));
                if (FilterKeysModified)
                    lines.Add(string.Format("FILTERKEYS_SPI|{0}|{1}|{2}|{3}|{4}",
                        OriginalFilterKeys.dwFlags, OriginalFilterKeys.iWaitMSec, OriginalFilterKeys.iDelayMSec, OriginalFilterKeys.iRepeatMSec, OriginalFilterKeys.iBounceMSec));
                if (NetshBaselineCaptured)
                    lines.Add(string.Format("NETSH_BASE|{0}|{1}|{2}|{3}|{4}|{5}|{6}|{7}",
                        OrigAutoTuning, OrigEcn, OrigTimestamps, OrigRsc, OrigRss, OrigNonSack, OrigInitialRto, OrigMaxSyn));

                foreach (var kv in LearnedTweakSummaries)
                {
                    lines.Add(string.Format("LEARNED_DEFAULT|{0}|{1}", kv.Key, (kv.Value ?? "").Replace("|", "/")));
                }

                foreach (var kv in RegistryBackups.Values)
                {
                    lines.Add(string.Format("REG|{0}|{1}|{2}|{3}|{4}|{5}|{6}",
                        kv.HiveName, kv.SubKey, kv.ValueName, kv.ExistedBefore, kv.Kind, kv.SerializedValue ?? "", (kv.FriendlyTweakName ?? "").Replace("|", "/")));
                }
                WriteAllLinesAtomic(journalPath, lines.ToArray());
            }
            catch { }
        }

        private static string SerializeRegistryValue(object obj, RegistryValueKind kind)
        {
            if (obj == null) return "";
            if (kind == RegistryValueKind.Binary && obj is byte[])
                return Convert.ToBase64String((byte[])obj);
            if (kind == RegistryValueKind.MultiString && obj is string[])
                return string.Join("\0", (string[])obj);
            return Convert.ToString(obj);
        }

        private static string FormatRegistryDisplaySummary(object obj)
        {
            if (obj == null) return "";
            if (obj is byte[])
                return "0x" + BitConverter.ToString((byte[])obj).Replace("-", "");
            if (obj is string[])
                return string.Join("; ", (string[])obj);
            return Convert.ToString(obj);
        }

        public bool SetRegistryTracked(string friendlyTweakName, string hiveName, string subKey, string valueName, object newValue, RegistryValueKind kind)
        {
            string keyId = hiveName + "\\" + subKey + "\\" + valueName;
            try
            {
                RegistryKey baseKey = (hiveName == "HKLM") ? Registry.LocalMachine : Registry.CurrentUser;
                if (!RegistryBackups.ContainsKey(keyId))
                {
                    RegistryBackupEntry backup = new RegistryBackupEntry
                    {
                        HiveName = hiveName,
                        SubKey = subKey,
                        ValueName = valueName,
                        ExistedBefore = false,
                        Kind = kind,
                        SerializedValue = "",
                        FriendlyTweakName = friendlyTweakName
                    };

                    using (RegistryKey existingKey = baseKey.OpenSubKey(subKey, false))
                    {
                        if (existingKey != null)
                        {
                            object oldObj = existingKey.GetValue(valueName, null);
                            if (oldObj != null)
                            {
                                backup.ExistedBefore = true;
                                backup.Kind = existingKey.GetValueKind(valueName);
                                backup.SerializedValue = SerializeRegistryValue(oldObj, backup.Kind);
                            }
                        }
                    }
                    RegistryBackups[keyId] = backup;
                }

                using (RegistryKey writeKey = baseKey.CreateSubKey(subKey))
                {
                    if (writeKey == null) return false;
                    writeKey.SetValue(valueName, newValue, kind);
                }

                RegistryBackups[keyId].CurrentAppliedSummary = FormatRegistryDisplaySummary(newValue);
                SaveJournal();
                return true;
            }
            catch
            {
                return false;
            }
        }

        public bool DeleteRegistryTracked(string friendlyTweakName, string hiveName, string subKey, string valueName)
        {
            string keyId = hiveName + "\\" + subKey + "\\" + valueName;
            try
            {
                RegistryKey baseKey = (hiveName == "HKLM") ? Registry.LocalMachine : Registry.CurrentUser;
                if (!RegistryBackups.ContainsKey(keyId))
                {
                    RegistryBackupEntry backup = new RegistryBackupEntry
                    {
                        HiveName = hiveName,
                        SubKey = subKey,
                        ValueName = valueName,
                        ExistedBefore = false,
                        Kind = RegistryValueKind.String,
                        SerializedValue = "",
                        FriendlyTweakName = friendlyTweakName
                    };

                    using (RegistryKey existingKey = baseKey.OpenSubKey(subKey, false))
                    {
                        if (existingKey != null)
                        {
                            object oldObj = existingKey.GetValue(valueName, null);
                            if (oldObj != null)
                            {
                                backup.ExistedBefore = true;
                                backup.Kind = existingKey.GetValueKind(valueName);
                                backup.SerializedValue = SerializeRegistryValue(oldObj, backup.Kind);
                            }
                        }
                    }
                    RegistryBackups[keyId] = backup;
                }

                using (RegistryKey writeKey = baseKey.OpenSubKey(subKey, true))
                {
                    if (writeKey != null)
                        writeKey.DeleteValue(valueName, false);
                }

                RegistryBackups[keyId].CurrentAppliedSummary = "(Varsayılan / Kaldırıldı)";
                SaveJournal();
                return true;
            }
            catch
            {
                return false;
            }
        }

        public const string DirectXUserGpuPreferencesPath = @"Software\Microsoft\DirectX\UserGpuPreferences";
        public const string DirectXGlobalValueName = "DirectXUserGlobalSettings";
        public const string AppCompatLayersPath = @"Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers";

        public static Dictionary<string, string> ParseSemicolonSettings(string raw)
        {
            Dictionary<string, string> dict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrEmpty(raw)) return dict;
            string[] parts = raw.Split(new char[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
            foreach (string part in parts)
            {
                int eq = part.IndexOf('=');
                if (eq > 0)
                {
                    string k = part.Substring(0, eq).Trim();
                    string v = part.Substring(eq + 1).Trim();
                    if (!string.IsNullOrEmpty(k))
                        dict[k] = v;
                }
            }
            return dict;
        }

        public static string FormatSemicolonSettings(Dictionary<string, string> dict)
        {
            if (dict == null || dict.Count == 0) return "";
            StringBuilder sb = new StringBuilder();
            foreach (var kv in dict)
            {
                sb.Append(kv.Key).Append("=").Append(kv.Value).Append(";");
            }
            return sb.ToString();
        }

        public bool UpdateDirectXPreferenceTokensTracked(string friendlyTweakName, string valueName, Dictionary<string, string> updates)
        {
            string currentRaw = ReadRegistryDisplay("HKCU", DirectXUserGpuPreferencesPath, valueName, "");
            Dictionary<string, string> tokens = ParseSemicolonSettings(currentRaw);
            foreach (var kv in updates)
            {
                if (kv.Value == null)
                    tokens.Remove(kv.Key);
                else
                    tokens[kv.Key] = kv.Value;
            }
            string updated = FormatSemicolonSettings(tokens);
            if (string.IsNullOrEmpty(updated))
                return DeleteRegistryTracked(friendlyTweakName, "HKCU", DirectXUserGpuPreferencesPath, valueName);
            return SetRegistryTracked(friendlyTweakName, "HKCU", DirectXUserGpuPreferencesPath, valueName, updated, RegistryValueKind.String);
        }

        public bool UpdateAppCompatLayerFlagTracked(string friendlyTweakName, string exeFullPath, string flagName, bool enable)
        {
            string raw = ReadRegistryDisplay("HKCU", AppCompatLayersPath, exeFullPath, "").Trim();
            List<string> flags = new List<string>();
            if (!string.IsNullOrEmpty(raw))
            {
                string[] parts = raw.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                foreach (string part in parts)
                {
                    if (part == "~") continue;
                    if (!string.Equals(part, flagName, StringComparison.OrdinalIgnoreCase))
                        flags.Add(part);
                }
            }
            if (enable && !flags.Contains(flagName))
                flags.Add(flagName);

            if (flags.Count == 0)
                return DeleteRegistryTracked(friendlyTweakName, "HKCU", AppCompatLayersPath, exeFullPath);

            string newValue = "~ " + string.Join(" ", flags.ToArray());
            return SetRegistryTracked(friendlyTweakName, "HKCU", AppCompatLayersPath, exeFullPath, newValue, RegistryValueKind.String);
        }

        public void RevertRegistryTracked(string hiveName, string subKey, string valueName)
        {
            string keyId = hiveName + "\\" + subKey + "\\" + valueName;
            if (!RegistryBackups.ContainsKey(keyId)) return;

            var entry = RegistryBackups[keyId];
            RestoreSingleRegistryEntry(entry.HiveName, entry.SubKey, entry.ValueName, entry.ExistedBefore, entry.Kind, entry.SerializedValue);
            RegistryBackups.Remove(keyId);
            SaveJournal();
        }

        private void RestoreSingleRegistryEntry(string hiveName, string subKey, string valueName, bool existedBefore, RegistryValueKind kind, string serializedValue)
        {
            try
            {
                RegistryKey baseKey = (hiveName == "HKLM") ? Registry.LocalMachine : Registry.CurrentUser;
                using (RegistryKey writeKey = existedBefore ? baseKey.CreateSubKey(subKey) : baseKey.OpenSubKey(subKey, true))
                {
                    if (writeKey == null) return;
                    if (!existedBefore)
                    {
                        writeKey.DeleteValue(valueName, false);
                    }
                    else
                    {
                        if (kind == RegistryValueKind.DWord)
                        {
                            int v;
                            if (int.TryParse(serializedValue, out v))
                                writeKey.SetValue(valueName, v, RegistryValueKind.DWord);
                        }
                        else if (kind == RegistryValueKind.QWord)
                        {
                            long v;
                            if (long.TryParse(serializedValue, out v))
                                writeKey.SetValue(valueName, v, RegistryValueKind.QWord);
                        }
                        else if (kind == RegistryValueKind.Binary)
                        {
                            byte[] bytes = string.IsNullOrEmpty(serializedValue) ? new byte[0] : Convert.FromBase64String(serializedValue);
                            writeKey.SetValue(valueName, bytes, RegistryValueKind.Binary);
                        }
                        else if (kind == RegistryValueKind.MultiString)
                        {
                            string[] items = string.IsNullOrEmpty(serializedValue) ? new string[0] : serializedValue.Split(new char[] { '\0' }, StringSplitOptions.RemoveEmptyEntries);
                            writeKey.SetValue(valueName, items, RegistryValueKind.MultiString);
                        }
                        else
                        {
                            writeKey.SetValue(valueName, serializedValue, RegistryValueKind.String);
                        }
                    }
                }
            }
            catch { }
        }

        public string ReadRegistryDisplay(string hiveName, string subKey, string valueName, string fallback)
        {
            try
            {
                RegistryKey baseKey = (hiveName == "HKLM") ? Registry.LocalMachine : Registry.CurrentUser;
                using (RegistryKey k = baseKey.OpenSubKey(subKey, false))
                {
                    if (k == null) return fallback;
                    object val = k.GetValue(valueName, null);
                    if (val == null) return fallback;
                    return FormatRegistryDisplaySummary(val);
                }
            }
            catch
            {
                return fallback;
            }
        }

        public void ApplyPowerSettingTracked(string keyTag, Guid subGroup, Guid setting, uint acValue, uint dcValue)
        {
            PowerSettingRequests[keyTag] = acValue;
            PowerSettingRequestsDC[keyTag] = dcValue;
            RebuildSessionPowerPlan();
        }

        public void ApplyPowerSettingTracked(string keyTag, Guid subGroup, Guid setting, uint acValue)
        {
            ApplyPowerSettingTracked(keyTag, subGroup, setting, acValue, acValue);
        }

        public void RemovePowerSettingTracked(string keyTag)
        {
            if (PowerSettingRequests.ContainsKey(keyTag))
                PowerSettingRequests.Remove(keyTag);
            if (PowerSettingRequestsDC.ContainsKey(keyTag))
                PowerSettingRequestsDC.Remove(keyTag);
            RebuildSessionPowerPlan();
        }

        private void RebuildSessionPowerPlan()
        {
            try
            {
                if (PowerSettingRequests.Count == 0)
                {
                    RevertPowerPlanCompletely();
                    return;
                }

                if (SessionCustomPowerScheme == Guid.Empty)
                {
                    IntPtr pDest;
                    Guid source = OriginalPowerScheme != Guid.Empty ? OriginalPowerScheme : new Guid("381b4222-f694-41f0-9685-ff5bb260df2e");
                    if (NativeMethods.PowerDuplicateScheme(IntPtr.Zero, ref source, out pDest) == 0 && pDest != IntPtr.Zero)
                    {
                        SessionCustomPowerScheme = (Guid)Marshal.PtrToStructure(pDest, typeof(Guid));
                        NativeMethods.LocalFree(pDest);
                        SaveJournal();
                    }
                }

                if (SessionCustomPowerScheme != Guid.Empty)
                {
                    foreach (var kv in PowerSettingRequests)
                    {
                        string[] parts = kv.Key.Split('|');
                        Guid sub = new Guid(parts[0]);
                        Guid set = new Guid(parts[1]);
                        uint acVal = kv.Value;
                        uint dcVal = PowerSettingRequestsDC.ContainsKey(kv.Key) ? PowerSettingRequestsDC[kv.Key] : acVal;
                        NativeMethods.PowerWriteACValueIndex(IntPtr.Zero, ref SessionCustomPowerScheme, ref sub, ref set, acVal);
                        NativeMethods.PowerWriteDCValueIndex(IntPtr.Zero, ref SessionCustomPowerScheme, ref sub, ref set, dcVal);
                    }
                    NativeMethods.PowerSetActiveScheme(IntPtr.Zero, ref SessionCustomPowerScheme);
                }
            }
            catch { }
        }

        public void RevertPowerPlanCompletely()
        {
            try
            {
                PowerSettingRequests.Clear();
                PowerSettingRequestsDC.Clear();
                if (OriginalPowerScheme != Guid.Empty)
                    NativeMethods.PowerSetActiveScheme(IntPtr.Zero, ref OriginalPowerScheme);
                if (SessionCustomPowerScheme != Guid.Empty)
                {
                    NativeMethods.PowerDeleteScheme(IntPtr.Zero, ref SessionCustomPowerScheme);
                    SessionCustomPowerScheme = Guid.Empty;
                }
                SaveJournal();
            }
            catch { }
        }

        public void RollbackAllAndCleanSession()
        {
            List<RegistryBackupEntry> regList = new List<RegistryBackupEntry>(RegistryBackups.Values);
            foreach (var entry in regList)
            {
                RestoreSingleRegistryEntry(entry.HiveName, entry.SubKey, entry.ValueName, entry.ExistedBefore, entry.Kind, entry.SerializedValue);
            }
            RegistryBackups.Clear();

            RevertPowerPlanCompletely();

            if (MouseSpiModified)
            {
                try
                {
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETMOUSE, 0, OriginalMouseAccel, NativeMethods.SPIF_SENDCHANGE);
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETMOUSESPEED, 0, (IntPtr)OriginalMouseSensitivity, NativeMethods.SPIF_SENDCHANGE);
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETMOUSEHOVERTIME, (uint)OriginalMouseHoverTime, IntPtr.Zero, NativeMethods.SPIF_SENDCHANGE);
                }
                catch { }
                MouseSpiModified = false;
            }

            if (KeyboardSpiModified)
            {
                try
                {
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETKEYBOARDDELAY, (uint)OriginalKeyboardDelay, IntPtr.Zero, NativeMethods.SPIF_SENDCHANGE);
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETKEYBOARDSPEED, (uint)OriginalKeyboardSpeed, IntPtr.Zero, NativeMethods.SPIF_SENDCHANGE);
                }
                catch { }
                KeyboardSpiModified = false;
            }

            if (FilterKeysModified)
            {
                try
                {
                    OriginalFilterKeys.cbSize = (uint)Marshal.SizeOf(typeof(NativeMethods.FILTERKEYS));
                    NativeMethods.SystemParametersInfo(NativeMethods.SPI_SETFILTERKEYS, OriginalFilterKeys.cbSize, ref OriginalFilterKeys, NativeMethods.SPIF_SENDCHANGE);
                }
                catch { }
                FilterKeysModified = false;
            }

            if (NetshModified)
            {
                RunHiddenCmd("netsh", string.Format("int tcp set global autotuninglevel={0} ecncapability={1} timestamps={2} rsc={3} rss={4} nonsackrttresiliency={5} initialRto={6} maxsynretransmissions={7}",
                    OrigAutoTuning, OrigEcn, OrigTimestamps, OrigRsc, OrigRss, OrigNonSack, OrigInitialRto, OrigMaxSyn));
                NetshModified = false;
            }

            if (DnsModified)
            {
                if (OriginalDnsWasDhcp)
                {
                    RunHiddenCmd("netsh", string.Format("interface ip set dns name=\"{0}\" source=dhcp", ActiveAdapterName));
                }
                else if (OriginalDnsServers.Count > 0)
                {
                    RunHiddenCmd("netsh", string.Format("interface ip set dns name=\"{0}\" static {1} primary", ActiveAdapterName, OriginalDnsServers[0]));
                    if (OriginalDnsServers.Count > 1)
                        RunHiddenCmd("netsh", string.Format("interface ip add dns name=\"{0}\" {1} index=2", ActiveAdapterName, OriginalDnsServers[1]));
                }
                NativeMethods.DnsFlushResolverCache();
                DnsModified = false;
            }

            foreach (var pb in ProcessBackups.Values)
            {
                try
                {
                    Process p = Process.GetProcessById(pb.Pid);
                    if (!p.HasExited)
                    {
                        p.PriorityClass = pb.OriginalPriority;
                        p.ProcessorAffinity = (IntPtr)pb.OriginalAffinity;
                        p.PriorityBoostEnabled = pb.OriginalBoost;
                    }
                }
                catch { }
            }
            ProcessBackups.Clear();

            SaveJournal();
        }

        public void RestoreAllProcessBackups()
        {
            foreach (var pb in ProcessBackups.Values)
            {
                try
                {
                    Process p = Process.GetProcessById(pb.Pid);
                    if (!p.HasExited)
                    {
                        p.PriorityClass = pb.OriginalPriority;
                        p.ProcessorAffinity = (IntPtr)pb.OriginalAffinity;
                        p.PriorityBoostEnabled = pb.OriginalBoost;
                    }
                }
                catch { }
            }
            ProcessBackups.Clear();
        }

        public static void WriteAllLinesAtomic(string path, string[] lines)
        {
            string tmp = path + ".tmp";
            File.WriteAllLines(tmp, lines, Encoding.UTF8);
            if (File.Exists(path)) File.Replace(tmp, path, null);
            else File.Move(tmp, path);
        }

        public static void RunHiddenCmd(string file, string args)
        {
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(file, args)
                {
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    WindowStyle = ProcessWindowStyle.Hidden
                };
                using (Process p = Process.Start(psi))
                {
                    if (p != null) p.WaitForExit(1500);
                }
            }
            catch { }
        }

        public static string RunCmdCaptureOutput(string file, string args)
        {
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(file, args)
                {
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    WindowStyle = ProcessWindowStyle.Hidden
                };
                using (Process p = Process.Start(psi))
                {
                    if (p == null) return "";
                    string output = p.StandardOutput.ReadToEnd();
                    p.WaitForExit(1500);
                    return output ?? "";
                }
            }
            catch { return ""; }
        }
    }

    #endregion

    #region DXGI & DWM Presentation Advisor

    public class DxgiAdapterInfo
    {
        public int Index = 0;
        public string Description = "";
        public uint VendorId = 0;
        public uint DeviceId = 0;
        public ulong DedicatedVramMb = 0;
        public bool IsSoftware = false;
    }

    public class DxgiOutputInfo
    {
        public string AdapterName = "";
        public string DeviceName = "";
        public int Left = 0;
        public int Top = 0;
        public int Width = 0;
        public int Height = 0;
        public uint RefreshRateHz = 0;
        public uint BitsPerColor = 8;
        public int ColorSpace = 0;
        public bool IsHdrActive = false;
        public float MaxLuminanceNits = 0f;
        public bool SupportsOverlaysMpo = false;
        public bool HwCompFullscreen = false;
        public bool HwCompWindowed = false;
        public bool HwCompCursorStretched = false;
        public bool HasOutput6 = false;
        public bool AttachedToDesktop = false;
    }

    public class DxgiHardwareReport
    {
        public List<DxgiAdapterInfo> Adapters = new List<DxgiAdapterInfo>();
        public List<DxgiOutputInfo> Outputs = new List<DxgiOutputInfo>();
        public bool DwmTimingOk = false;
        public double DwmRefreshHz = 0.0;
        public double DwmComposeHz = 0.0;
        public ulong DwmFramesDropped = 0;
        public ulong DwmFramesMissed = 0;
        public string ProbeError = "";
    }

    public static class DxgiPresentationProbe
    {
        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int EnumAdapters1Del(IntPtr pFactory, uint index, out IntPtr ppAdapter);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int AdapterGetDesc1Del(IntPtr pAdapter, out NativeMethods.DXGI_ADAPTER_DESC1 pDesc);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int EnumOutputsDel(IntPtr pAdapter, uint index, out IntPtr ppOutput);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int OutputGetDescDel(IntPtr pOutput, out NativeMethods.DXGI_OUTPUT_DESC pDesc);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int SupportsOverlaysDel(IntPtr pOutput2);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int OutputGetDesc1Del(IntPtr pOutput6, out NativeMethods.DXGI_OUTPUT_DESC1 pDesc1);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        private delegate int CheckHwCompDel(IntPtr pOutput6, out uint pFlags);

        public static DxgiHardwareReport ProbeSystemDisplays()
        {
            DxgiHardwareReport report = new DxgiHardwareReport();

            // 1. Live DWM Composition Timing (must pass IntPtr.Zero on Win8/10/11)
            try
            {
                NativeMethods.DWM_TIMING_INFO ti = new NativeMethods.DWM_TIMING_INFO();
                ti.cbSize = (uint)Marshal.SizeOf(typeof(NativeMethods.DWM_TIMING_INFO));
                int hrDwm = NativeMethods.DwmGetCompositionTimingInfo(IntPtr.Zero, ref ti);
                if (hrDwm == 0)
                {
                    report.DwmTimingOk = true;
                    if (ti.rateRefresh.uiDenominator > 0)
                        report.DwmRefreshHz = (double)ti.rateRefresh.uiNumerator / ti.rateRefresh.uiDenominator;
                    if (ti.rateCompose.uiDenominator > 0)
                        report.DwmComposeHz = (double)ti.rateCompose.uiNumerator / ti.rateCompose.uiDenominator;
                    report.DwmFramesDropped = ti.cFramesDropped;
                    report.DwmFramesMissed = ti.cFramesMissed;
                }
            }
            catch { }

            // 2. Native DXGI 1.1 / 1.3 / 1.6 Hardware Probe
            IntPtr pFactory = IntPtr.Zero;
            try
            {
                Guid iidFactory1 = new Guid("770aae78-f26f-4dba-a829-253c83d1b387");
                int hrFactory = NativeMethods.CreateDXGIFactory1(ref iidFactory1, out pFactory);
                if (hrFactory != 0 || pFactory == IntPtr.Zero)
                {
                    report.ProbeError = string.Format("CreateDXGIFactory1 HR=0x{0:X}", hrFactory);
                    return report;
                }

                IntPtr vtFactory = Marshal.ReadIntPtr(pFactory);
                EnumAdapters1Del enumAdapters1 = (EnumAdapters1Del)Marshal.GetDelegateForFunctionPointer(
                    Marshal.ReadIntPtr(vtFactory, IntPtr.Size * 12), typeof(EnumAdapters1Del));

                uint adapterIdx = 0;
                IntPtr pAdapter = IntPtr.Zero;
                while (enumAdapters1(pFactory, adapterIdx, out pAdapter) == 0 && pAdapter != IntPtr.Zero)
                {
                    try
                    {
                        IntPtr vtAdapter = Marshal.ReadIntPtr(pAdapter);
                        AdapterGetDesc1Del getAdapterDesc1 = (AdapterGetDesc1Del)Marshal.GetDelegateForFunctionPointer(
                            Marshal.ReadIntPtr(vtAdapter, IntPtr.Size * 10), typeof(AdapterGetDesc1Del));
                        EnumOutputsDel enumOutputs = (EnumOutputsDel)Marshal.GetDelegateForFunctionPointer(
                            Marshal.ReadIntPtr(vtAdapter, IntPtr.Size * 7), typeof(EnumOutputsDel));

                        NativeMethods.DXGI_ADAPTER_DESC1 aDesc;
                        DxgiAdapterInfo aInfo = new DxgiAdapterInfo { Index = (int)adapterIdx };
                        if (getAdapterDesc1(pAdapter, out aDesc) == 0)
                        {
                            aInfo.Description = (aDesc.Description ?? "").Trim();
                            aInfo.VendorId = aDesc.VendorId;
                            aInfo.DeviceId = aDesc.DeviceId;
                            aInfo.DedicatedVramMb = aDesc.DedicatedVideoMemory.ToUInt64() / (1024UL * 1024UL);
                            aInfo.IsSoftware = (aDesc.Flags & 0x2) != 0;
                        }
                        report.Adapters.Add(aInfo);

                        if (!aInfo.IsSoftware)
                        {
                            uint outIdx = 0;
                            IntPtr pOutput = IntPtr.Zero;
                            while (enumOutputs(pAdapter, outIdx, out pOutput) == 0 && pOutput != IntPtr.Zero)
                            {
                                try
                                {
                                    DxgiOutputInfo oInfo = ProbeSingleOutput(pOutput, aInfo.Description);
                                    if (oInfo != null && oInfo.AttachedToDesktop)
                                        report.Outputs.Add(oInfo);
                                }
                                finally
                                {
                                    Marshal.Release(pOutput);
                                }
                                outIdx++;
                            }
                        }
                    }
                    finally
                    {
                        Marshal.Release(pAdapter);
                    }
                    adapterIdx++;
                }
            }
            catch (Exception ex)
            {
                report.ProbeError = ex.Message;
            }
            finally
            {
                if (pFactory != IntPtr.Zero) Marshal.Release(pFactory);
            }

            return report;
        }

        private static DxgiOutputInfo ProbeSingleOutput(IntPtr pOutput, string adapterName)
        {
            DxgiOutputInfo info = new DxgiOutputInfo();
            info.AdapterName = adapterName ?? "";

            Guid iidOutput6 = new Guid("068346e8-aaec-4b84-add7-137f513f77a1");
            IntPtr pOutput6 = IntPtr.Zero;
            if (Marshal.QueryInterface(pOutput, ref iidOutput6, out pOutput6) == 0 && pOutput6 != IntPtr.Zero)
            {
                try
                {
                    info.HasOutput6 = true;
                    IntPtr vt = Marshal.ReadIntPtr(pOutput6);
                    SupportsOverlaysDel supportsOv = (SupportsOverlaysDel)Marshal.GetDelegateForFunctionPointer(
                        Marshal.ReadIntPtr(vt, IntPtr.Size * 23), typeof(SupportsOverlaysDel));
                    OutputGetDesc1Del getDesc1 = (OutputGetDesc1Del)Marshal.GetDelegateForFunctionPointer(
                        Marshal.ReadIntPtr(vt, IntPtr.Size * 27), typeof(OutputGetDesc1Del));
                    CheckHwCompDel checkHw = (CheckHwCompDel)Marshal.GetDelegateForFunctionPointer(
                        Marshal.ReadIntPtr(vt, IntPtr.Size * 28), typeof(CheckHwCompDel));

                    info.SupportsOverlaysMpo = (supportsOv(pOutput6) != 0);

                    NativeMethods.DXGI_OUTPUT_DESC1 d1;
                    if (getDesc1(pOutput6, out d1) == 0)
                    {
                        info.DeviceName = (d1.DeviceName ?? "").Trim();
                        info.Left = d1.DesktopCoordinates.Left;
                        info.Top = d1.DesktopCoordinates.Top;
                        info.Width = d1.DesktopCoordinates.Width;
                        info.Height = d1.DesktopCoordinates.Height;
                        info.AttachedToDesktop = (d1.AttachedToDesktop != 0);
                        info.BitsPerColor = d1.BitsPerColor;
                        info.ColorSpace = d1.ColorSpace;
                        // DXGI_COLOR_SPACE_RGB_FULL_G2084_NONE_P2020 (12) = HDR10
                        info.IsHdrActive = (d1.ColorSpace == 12);
                        info.MaxLuminanceNits = d1.MaxLuminance;
                    }

                    uint flags = 0;
                    if (checkHw(pOutput6, out flags) == 0)
                    {
                        info.HwCompFullscreen = (flags & 0x1) != 0;
                        info.HwCompWindowed = (flags & 0x2) != 0;
                        info.HwCompCursorStretched = (flags & 0x4) != 0;
                    }
                }
                finally
                {
                    Marshal.Release(pOutput6);
                }
            }
            else
            {
                // Fallback to IDXGIOutput (slot 7) & IDXGIOutput2 (slot 23) for older Windows builds
                IntPtr vtBase = Marshal.ReadIntPtr(pOutput);
                OutputGetDescDel getDesc = (OutputGetDescDel)Marshal.GetDelegateForFunctionPointer(
                    Marshal.ReadIntPtr(vtBase, IntPtr.Size * 7), typeof(OutputGetDescDel));
                NativeMethods.DXGI_OUTPUT_DESC d;
                if (getDesc(pOutput, out d) == 0)
                {
                    info.DeviceName = (d.DeviceName ?? "").Trim();
                    info.Left = d.DesktopCoordinates.Left;
                    info.Top = d.DesktopCoordinates.Top;
                    info.Width = d.DesktopCoordinates.Width;
                    info.Height = d.DesktopCoordinates.Height;
                    info.AttachedToDesktop = (d.AttachedToDesktop != 0);
                }

                Guid iidOutput2 = new Guid("595e39d1-2724-4663-99b1-da969de28364");
                IntPtr pOutput2 = IntPtr.Zero;
                if (Marshal.QueryInterface(pOutput, ref iidOutput2, out pOutput2) == 0 && pOutput2 != IntPtr.Zero)
                {
                    try
                    {
                        IntPtr vt2 = Marshal.ReadIntPtr(pOutput2);
                        SupportsOverlaysDel supportsOv2 = (SupportsOverlaysDel)Marshal.GetDelegateForFunctionPointer(
                            Marshal.ReadIntPtr(vt2, IntPtr.Size * 23), typeof(SupportsOverlaysDel));
                        info.SupportsOverlaysMpo = (supportsOv2(pOutput2) != 0);
                    }
                    finally
                    {
                        Marshal.Release(pOutput2);
                    }
                }
            }

            if (!string.IsNullOrEmpty(info.DeviceName))
            {
                uint mw, mh, mhz, mbpp;
                if (NativeMethods.QueryDisplayModeMetrics(info.DeviceName, out mw, out mh, out mhz, out mbpp))
                {
                    info.RefreshRateHz = mhz;
                    if (mw > 0 && mh > 0)
                    {
                        info.Width = (int)mw;
                        info.Height = (int)mh;
                    }
                }
            }

            return info;
        }
    }

    public class PerGameDirectXRule
    {
        public string ExePath = "";
        public string ExeName = "";
        public int GpuPreference = 0; // 0 = Windows Decide, 1 = Power Saving iGPU, 2 = High Perf dGPU
        public int SwapEffectUpgradeOverride = -1; // -1 = Global Default, 0 = Force Off, 1 = Force On
        public bool DisableFullscreenOptimizations = false;
        public string RawDxTokens = "";
        public string RawAppCompat = "";
    }

    public class PresentationPolicySnapshot
    {
        public int OsMajor = 0;
        public int OsMinor = 0;
        public int OsBuild = 0;
        public int OsUbr = 0;
        public string OsDisplayVersion = "";
        public string OsFriendlyName = "";
        public bool IsWin11 = false;
        public bool SupportsWindowedOptimizationsOs = false;

        public DxgiHardwareReport Hardware = new DxgiHardwareReport();

        public int HagsMode = -1; // -1=Default/Absent, 0=Disabled, 1=Off, 2=On
        public string TdrDelay = "";
        public string OverlayTestMode = ""; // "5" = disabled
        public string DisableOverlays = ""; // "1" = disabled
        public bool MpoRegistryBlocked = false;

        public string RawDirectXGlobalSettings = "";
        public int SwapEffectUpgradeEnable = -1; // -1=Absent, 0=Off, 1=On
        public int VrrOptimizeEnable = -1;
        public int AutoHdrEnable = -1;

        public string GameDvrEnabled = "";
        public string AppCaptureEnabled = "";
        public string FseBehaviorMode = "";
        public string HonorUserFseBehaviorMode = "";
        public string DxgiHonorFseCompatible = "";
        public string DseBehavior = "";

        public bool StaleWrongKeyExists = false;

        public List<PerGameDirectXRule> PerGameRules = new List<PerGameDirectXRule>();
        public List<string> Conflicts = new List<string>();
        public List<string> Advisories = new List<string>();
    }

    public static class PresentationAdvisorEngine
    {
        public static PresentationPolicySnapshot CaptureSnapshot(StateVault vault)
        {
            PresentationPolicySnapshot snap = new PresentationPolicySnapshot();

            NativeMethods.GetRealOsVersionInfo(out snap.OsMajor, out snap.OsMinor, out snap.OsBuild, out snap.OsUbr, out snap.OsDisplayVersion);
            snap.IsWin11 = (snap.OsMajor >= 10 && snap.OsBuild >= 22000);
            snap.SupportsWindowedOptimizationsOs = (snap.OsMajor >= 10 && snap.OsBuild >= 22621);
            snap.OsFriendlyName = snap.IsWin11
                ? string.Format("Windows 11 {0} (Build {1}.{2})", snap.OsDisplayVersion, snap.OsBuild, snap.OsUbr).Replace("  ", " ")
                : string.Format("Windows {0}.{1} {2} (Build {3}.{4})", snap.OsMajor, snap.OsMinor, snap.OsDisplayVersion, snap.OsBuild, snap.OsUbr).Replace("  ", " ");

            snap.Hardware = DxgiPresentationProbe.ProbeSystemDisplays();

            // Read GraphicsDrivers
            string gfxKey = @"SYSTEM\CurrentControlSet\Control\GraphicsDrivers";
            string hagsRaw = vault.ReadRegistryDisplay("HKLM", gfxKey, "HwSchMode", "");
            int hagsVal;
            if (int.TryParse(hagsRaw, out hagsVal)) snap.HagsMode = hagsVal;
            snap.TdrDelay = vault.ReadRegistryDisplay("HKLM", gfxKey, "TdrDelay", "");
            snap.DisableOverlays = vault.ReadRegistryDisplay("HKLM", gfxKey, "DisableOverlays", "");

            // Read DWM MPO Registry
            snap.OverlayTestMode = vault.ReadRegistryDisplay("HKLM", @"SOFTWARE\Microsoft\Windows\Dwm", "OverlayTestMode", "");
            snap.MpoRegistryBlocked = (snap.OverlayTestMode == "5" || snap.DisableOverlays == "1");

            // Read DirectX Global Settings
            snap.RawDirectXGlobalSettings = vault.ReadRegistryDisplay("HKCU", StateVault.DirectXUserGpuPreferencesPath, StateVault.DirectXGlobalValueName, "");
            Dictionary<string, string> dxTokens = StateVault.ParseSemicolonSettings(snap.RawDirectXGlobalSettings);
            snap.SwapEffectUpgradeEnable = ParseTokenInt(dxTokens, "SwapEffectUpgradeEnable", -1);
            snap.VrrOptimizeEnable = ParseTokenInt(dxTokens, "VRROptimizeEnable", -1);
            snap.AutoHdrEnable = ParseTokenInt(dxTokens, "AutoHDREnable", -1);

            // Check stale dead key from older Argon bug (`UserGlobalSettings`)
            try
            {
                using (RegistryKey kStale = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\DirectX\UserGlobalSettings", false))
                {
                    if (kStale != null) snap.StaleWrongKeyExists = true;
                }
            }
            catch { }

            // Read GameConfigStore & GameDVR
            string gcKey = @"System\GameConfigStore";
            snap.GameDvrEnabled = vault.ReadRegistryDisplay("HKCU", gcKey, "GameDVR_Enabled", "");
            snap.FseBehaviorMode = vault.ReadRegistryDisplay("HKCU", gcKey, "GameDVR_FSEBehaviorMode", "");
            snap.HonorUserFseBehaviorMode = vault.ReadRegistryDisplay("HKCU", gcKey, "GameDVR_HonorUserFSEBehaviorMode", "");
            snap.DxgiHonorFseCompatible = vault.ReadRegistryDisplay("HKCU", gcKey, "GameDVR_DXGIHonorFSEWindowsCompatible", "");
            snap.DseBehavior = vault.ReadRegistryDisplay("HKCU", gcKey, "GameDVR_DSEBehavior", "");
            snap.AppCaptureEnabled = vault.ReadRegistryDisplay("HKCU", @"SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR", "AppCaptureEnabled", "");

            // Read Per-Game DirectX & AppCompat rules
            LoadPerGameRules(snap);

            // Evaluate Conflicts & Advisories
            AnalyzeConflicts(snap);

            return snap;
        }

        private static int ParseTokenInt(Dictionary<string, string> tokens, string key, int fallback)
        {
            string val;
            int parsed;
            if (tokens.TryGetValue(key, out val) && int.TryParse(val, out parsed))
                return parsed;
            return fallback;
        }

        private static void LoadPerGameRules(PresentationPolicySnapshot snap)
        {
            Dictionary<string, PerGameDirectXRule> map = new Dictionary<string, PerGameDirectXRule>(StringComparer.OrdinalIgnoreCase);

            try
            {
                using (RegistryKey dxKey = Registry.CurrentUser.OpenSubKey(StateVault.DirectXUserGpuPreferencesPath, false))
                {
                    if (dxKey != null)
                    {
                        foreach (string valName in dxKey.GetValueNames())
                        {
                            if (string.IsNullOrEmpty(valName) || string.Equals(valName, StateVault.DirectXGlobalValueName, StringComparison.OrdinalIgnoreCase))
                                continue;
                            if (!valName.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                                continue;

                            string raw = Convert.ToString(dxKey.GetValue(valName, ""));
                            var toks = StateVault.ParseSemicolonSettings(raw);
                            PerGameDirectXRule rule = new PerGameDirectXRule();
                            rule.ExePath = valName;
                            rule.ExeName = Path.GetFileName(valName);
                            rule.RawDxTokens = raw;
                            rule.GpuPreference = ParseTokenInt(toks, "GpuPreference", 0);
                            rule.SwapEffectUpgradeOverride = ParseTokenInt(toks, "SwapEffectUpgradeEnable", -1);
                            map[valName] = rule;
                        }
                    }
                }
            }
            catch { }

            try
            {
                using (RegistryKey acKey = Registry.CurrentUser.OpenSubKey(StateVault.AppCompatLayersPath, false))
                {
                    if (acKey != null)
                    {
                        foreach (string valName in acKey.GetValueNames())
                        {
                            if (string.IsNullOrEmpty(valName) || !valName.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                                continue;
                            string raw = Convert.ToString(acKey.GetValue(valName, ""));
                            bool disFso = raw.IndexOf("DISABLEDXMAXIMIZEDWINDOWEDMODE", StringComparison.OrdinalIgnoreCase) >= 0;
                            if (!map.ContainsKey(valName) && !disFso)
                                continue;

                            PerGameDirectXRule rule;
                            if (!map.TryGetValue(valName, out rule))
                            {
                                rule = new PerGameDirectXRule();
                                rule.ExePath = valName;
                                rule.ExeName = Path.GetFileName(valName);
                                map[valName] = rule;
                            }
                            rule.DisableFullscreenOptimizations = disFso;
                            rule.RawAppCompat = raw;
                        }
                    }
                }
            }
            catch { }

            foreach (var r in map.Values)
                snap.PerGameRules.Add(r);

            snap.PerGameRules.Sort((a, b) => string.Compare(a.ExeName, b.ExeName, StringComparison.OrdinalIgnoreCase));
        }

        private static void AnalyzeConflicts(PresentationPolicySnapshot snap)
        {
            bool anyLiveMpo = false;
            bool allOutputsHaveLiveMpo = snap.Hardware.Outputs.Count > 0;
            HashSet<uint> distinctHz = new HashSet<uint>();

            foreach (var o in snap.Hardware.Outputs)
            {
                if (o.SupportsOverlaysMpo) anyLiveMpo = true;
                else allOutputsHaveLiveMpo = false;
                if (o.RefreshRateHz > 0) distinctHz.Add(o.RefreshRateHz);
            }

            // Conflict 1: MPO Disabled vs Borderless / Windowed Optimizations
            if (snap.MpoRegistryBlocked && snap.SwapEffectUpgradeEnable == 1)
            {
                snap.Conflicts.Add(
                    "MPO Devre Dışı (OverlayTestMode=5 / DisableOverlays=1) ↔ Pencereli Oyun Optimizasyonları (SwapEffectUpgradeEnable=1): " +
                    "MPO kapalıyken oyun üzerinde herhangi bir katman (Discord/Steam/Ses çubuğu/FPS sayacı) çıktığında Windows DWM donanımsal katman birleştirmeyi " +
                    "(Hardware Composed: Independent Flip) kullanamaz ve DWM kompozisyonuna (Composed: Flip) düşer. Çift ekran titreme sorununuz yoksa MPO'yu Etkin tutmanız önerilir.");
            }

            // Conflict 2: Pending reboot verification between Registry MPO setting and live DXGI driver state
            if (snap.Hardware.Outputs.Count > 0)
            {
                if (snap.MpoRegistryBlocked && anyLiveMpo)
                {
                    snap.Conflicts.Add("Bekleyen Yeniden Başlatma: Kayıt defterinde MPO kapalı ayarlanmış ancak DXGI sürücüsü hâlâ SupportsOverlays=TRUE bildiriyor. Değişikliğin aktifleşmesi için Windows'u yeniden başlatın.");
                }
                else if (!snap.MpoRegistryBlocked && !allOutputsHaveLiveMpo)
                {
                    snap.Advisories.Add("Bilgi: Kayıt defterinde MPO engeli yok ancak DXGI sürücüsü SupportsOverlays=FALSE döndürüyor (yeniden başlatma bekleniyor olabilir veya monitör kablosu/sürücü yapılandırması MPO plane ayırmamış olabilir).");
                }
            }

            // Conflict 3: Global FSEBehaviorMode=2 vs Win11 Borderless Flip Model & VRR
            if (snap.FseBehaviorMode == "2" && snap.SwapEffectUpgradeEnable == 1)
            {
                snap.Advisories.Add(
                    "Karma FSO Politikası: GameDVR_FSEBehaviorMode=2 küresel olarak Tam Ekran İyileştirmelerini kapatmaya zorluyor. " +
                    "Modern DX12 oyunlarında gerçek Exclusive Fullscreen zaten yoktur (daima Flip Model çalışır); DX10/11 pencereli/kenarsız oyunlarda hızlı Alt+Tab için Mod=0 + SwapEffectUpgradeEnable=1 daha tutarlıdır.");
            }

            // Advisory: Mixed refresh rate monitors
            if (distinctHz.Count >= 2)
            {
                StringBuilder hzStr = new StringBuilder();
                foreach (uint hz in distinctHz)
                {
                    if (hzStr.Length > 0) hzStr.Append(" / ");
                    hzStr.Append(hz).Append("Hz");
                }
                snap.Advisories.Add(string.Format("Karışık Yenileme Hızı Algılandı ({0}): Birden fazla farklı Hz monitör kullanımında MPO kapalıysa yan ekranda video/tarayıcı açıkken DWM zamanlama dalgalanması yaşanabilir.", hzStr.ToString()));
            }

            if (snap.StaleWrongKeyExists)
            {
                snap.Advisories.Add("Eski Sürüm Artığı Tespit Edildi: HKCU\\Software\\Microsoft\\DirectX\\UserGlobalSettings alt anahtarı (Windows'un okumadığı hatalı yol) sistemde mevcut; dilerseniz temizleyebilirsiniz.");
            }
        }

        public static bool CleanupStaleWrongDirectXKey()
        {
            try
            {
                Registry.CurrentUser.DeleteSubKeyTree(@"Software\Microsoft\DirectX\UserGlobalSettings", false);
                return true;
            }
            catch
            {
                return false;
            }
        }

        public static string InspectTargetWindowAndSwapchain(IntPtr hwnd, PresentationPolicySnapshot snap, string presentMonBin)
        {
            StringBuilder sb = new StringBuilder();
            try
            {
                if (hwnd == IntPtr.Zero)
                    return "❌ Geçerli bir ön plan penceresi yakalanamadı.";

                uint pid = 0;
                NativeMethods.GetWindowThreadProcessId(hwnd, out pid);
                string procName = "Bilinmiyor";
                string exePath = "";
                try
                {
                    if (pid > 0)
                    {
                        using (Process p = Process.GetProcessById((int)pid))
                        {
                            procName = p.ProcessName + ".exe";
                            try { exePath = p.MainModule.FileName; } catch { }
                        }
                    }
                }
                catch { }

                StringBuilder titleSb = new StringBuilder(256);
                NativeMethods.GetWindowText(hwnd, titleSb, 256);
                string winTitle = titleSb.ToString();

                NativeMethods.RECT rc = new NativeMethods.RECT();
                NativeMethods.GetWindowRect(hwnd, out rc);

                uint style = NativeMethods.GetWindowStyleSafe(hwnd, NativeMethods.GWL_STYLE);
                int cloaked = 0;
                NativeMethods.DwmGetWindowAttribute(hwnd, NativeMethods.DWMWA_CLOAKED, out cloaked, 4);

                bool isBorderlessPopup = (style & NativeMethods.WS_CAPTION) == 0 && (style & NativeMethods.WS_POPUP) != 0;
                Screen matchedScreen = Screen.FromHandle(hwnd) ?? Screen.PrimaryScreen;
                bool coversMonitor = matchedScreen != null && rc.Width >= matchedScreen.Bounds.Width && rc.Height >= matchedScreen.Bounds.Height;

                DxgiOutputInfo matchedOutput = null;
                if (matchedScreen != null)
                {
                    foreach (var o in snap.Hardware.Outputs)
                    {
                        if (string.Equals(o.DeviceName, matchedScreen.DeviceName, StringComparison.OrdinalIgnoreCase))
                        {
                            matchedOutput = o;
                            break;
                        }
                    }
                }

                bool isArgonSelf = procName.ToLowerInvariant().Contains("argon");

                sb.AppendLine("═══════════════════════════════════════════════════════════════════════════════════════════");
                sb.AppendLine(string.Format("• YAKALANAN PENCERE SÜRECİ : {0} (PID: {1}) — Başlık: '{2}'", procName, pid, winTitle));
                if (!string.IsNullOrEmpty(exePath))
                    sb.AppendLine(string.Format("• ÇALIŞTIRILAN DOSYA YOLU  : {0}", exePath));

                string winKind = coversMonitor
                    ? (isBorderlessPopup ? "Kenarsız / Tam Ekran Kapsamında (Borderless/Fullscreen)" : "Tam Ekran Pencere Kapsamında")
                    : "Standart Pencereli Mod (Masaüstü Boyutundan Küçük)";
                sb.AppendLine(string.Format("• PENCERE GEOMETRİSİ       : {0}x{1} | {2}{3}", rc.Width, rc.Height, winKind, cloaked != 0 ? " [Gizli/Cloaked]" : ""));

                if (matchedOutput != null)
                {
                    sb.AppendLine(string.Format("• HEDEF MONİTÖR (DXGI)     : {0} ({1}x{2} @ {3}Hz, {4}-bit {5})",
                        matchedOutput.DeviceName, matchedOutput.Width, matchedOutput.Height, matchedOutput.RefreshRateHz,
                        matchedOutput.BitsPerColor, matchedOutput.IsHdrActive ? "HDR10" : "SDR"));
                    sb.AppendLine(string.Format("• DONANIM KOMPOZİSYON YET. : MPO={0} | Windowed HW Comp={1} | Fullscreen HW Comp={2}",
                        matchedOutput.SupportsOverlaysMpo ? "AÇIK (Destekli)" : "KAPALI",
                        matchedOutput.HwCompWindowed ? "EVET" : "HAYIR",
                        matchedOutput.HwCompFullscreen ? "EVET" : "HAYIR"));
                }

                // Per-game rule check
                if (!string.IsNullOrEmpty(exePath))
                {
                    PerGameDirectXRule foundRule = null;
                    foreach (var r in snap.PerGameRules)
                    {
                        if (string.Equals(r.ExePath, exePath, StringComparison.OrdinalIgnoreCase))
                        {
                            foundRule = r;
                            break;
                        }
                    }
                    if (foundRule != null)
                    {
                        sb.AppendLine(string.Format("• OYUN ÖZEL KURALI         : GPU Tercihi={0} | Pencereli Opt={1} | FSO Devre Dışı={2}",
                            foundRule.GpuPreference == 2 ? "Yüksek Performans dGPU" : (foundRule.GpuPreference == 1 ? "Güç Tasarrufu iGPU" : "Sistem"),
                            foundRule.SwapEffectUpgradeOverride == 1 ? "Açık" : (foundRule.SwapEffectUpgradeOverride == 0 ? "Kapalı" : "Genel"),
                            foundRule.DisableFullscreenOptimizations ? "EVET (DISABLEDXMAXIMIZEDWINDOWEDMODE)" : "Hayır"));
                    }
                }

                sb.AppendLine("───────────────────────────────────────────────────────────────────────────────────────────");

                if (isArgonSelf)
                {
                    sb.AppendLine("⚠️ NOT: Ön plan penceresi şu anda Argon'un kendisi! Gerçek oyununuzu analiz etmek için");
                    sb.AppendLine("   '⏱️ 5 Sn Gecikmeli Yakala' butonuna basıp hemen oyuna geçiş (Alt+Tab) yapın.");
                }
                else
                {
                    // Check PresentMon ETW if binary available
                    string etwResult = TryRunQuickPresentMonPresentMode(pid, procName, presentMonBin);
                    sb.AppendLine(etwResult);
                }

                sb.AppendLine("═══════════════════════════════════════════════════════════════════════════════════════════");
            }
            catch (Exception ex)
            {
                sb.AppendLine("Ön plan analizi sırasında hata: " + ex.Message);
            }
            return sb.ToString();
        }

        private static string TryRunQuickPresentMonPresentMode(uint pid, string procName, string presentMonBin)
        {
            if (string.IsNullOrEmpty(presentMonBin) || !File.Exists(presentMonBin))
            {
                return "ℹ️ SWAPCHAIN PRESENTMODE (ETW ÖLÇÜLMEDİ): Intel PresentMon bulunamadı (DXGI/ETW swapchain kanıtı için\n" +
                       "   uygulama yanına veya 'tools\\PresentMon.exe' klasörüne yerleştirin).\n" +
                       "   Argon kayıt defteri tahminiyle sahte '0 ms Independent Flip' iddiasında BULUNMAZ; yalnızca yukarıdaki\n" +
                       "   gerçek DXGI donanım yeterliliği ve Windows politika durumu raporlanır.";
            }

            string tempCsv = Path.Combine(Path.GetTempPath(), "argon_pm_pres_" + Guid.NewGuid().ToString("N") + ".csv");
            try
            {
                string args = string.Format("-process_id {0} -timed 3 -output_file \"{1}\" -no_top", pid, tempCsv);
                ProcessStartInfo psi = new ProcessStartInfo
                {
                    FileName = presentMonBin,
                    Arguments = args,
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };
                using (Process pmProc = Process.Start(psi))
                {
                    pmProc.WaitForExit(7000);
                }

                if (!File.Exists(tempCsv))
                    return "⚠️ PresentMon ETW çıktısı oluşturulamadı (yönetici yetkisi / ETW oturumu veya hedef DXGI sunumu yok).";

                string[] lines = File.ReadAllLines(tempCsv);
                if (lines.Length <= 1)
                    return "⚠️ PresentMon 3 saniyede kare yakalayamadı (hedef süreç DXGI/Vulkan swapchain çizmiyor olabilir).";

                string[] headers = lines[0].Split(',');
                int pmCol = -1;
                int tearingCol = -1;
                int syncCol = -1;
                for (int h = 0; h < headers.Length; h++)
                {
                    string hn = headers[h].Trim().ToLowerInvariant();
                    if (hn == "presentmode") pmCol = h;
                    else if (hn == "allowstearing") tearingCol = h;
                    else if (hn == "syncinterval") syncCol = h;
                }

                if (pmCol < 0)
                    return "⚠️ PresentMon CSV dosyasında PresentMode sütunu bulunamadı.";

                Dictionary<string, int> modeCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                int totalFrames = 0;
                int tearingCount = 0;
                Dictionary<string, int> syncCounts = new Dictionary<string, int>();

                for (int i = 1; i < lines.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(lines[i])) continue;
                    string[] row = lines[i].Split(',');
                    if (row.Length <= pmCol) continue;

                    string mode = row[pmCol].Trim();
                    if (string.IsNullOrEmpty(mode)) continue;
                    totalFrames++;
                    if (!modeCounts.ContainsKey(mode)) modeCounts[mode] = 0;
                    modeCounts[mode]++;

                    if (tearingCol >= 0 && row.Length > tearingCol)
                    {
                        string tVal = row[tearingCol].Trim();
                        if (tVal == "1" || string.Equals(tVal, "true", StringComparison.OrdinalIgnoreCase))
                            tearingCount++;
                    }
                    if (syncCol >= 0 && row.Length > syncCol)
                    {
                        string sVal = row[syncCol].Trim();
                        if (!syncCounts.ContainsKey(sVal)) syncCounts[sVal] = 0;
                        syncCounts[sVal]++;
                    }
                }

                if (totalFrames == 0)
                    return "⚠️ PresentMon CSV içinde geçerli kare satırı bulunamadı.";

                StringBuilder outSb = new StringBuilder();
                outSb.AppendLine(string.Format("📊 ÖLÇÜLEN SWAPCHAIN PRESENTMODE (Intel PresentMon ETW — {0} kare, {1}):", totalFrames, procName));
                foreach (var kv in modeCounts)
                {
                    double pct = (kv.Value * 100.0) / totalFrames;
                    outSb.AppendLine(string.Format("   • {0,-38} : {1,4} kare (%{2:0.0})", kv.Key, kv.Value, pct));
                }
                if (tearingCol >= 0)
                {
                    outSb.AppendLine(string.Format("   • AllowsTearing (VRR/Yırtılma İzni) : %{0:0.0} karede etkin", (tearingCount * 100.0) / totalFrames));
                }
                return outSb.ToString().TrimEnd();
            }
            catch (Exception ex)
            {
                return "⚠️ PresentMon ETW ölçümü hatası: " + ex.Message;
            }
            finally
            {
                try { if (File.Exists(tempCsv)) File.Delete(tempCsv); } catch { }
            }
        }
    }

    #endregion

    #region InputLab Raw Input & USB Topology Engine

    public struct InputEventSample
    {
        public double DeltaMs;
        public int Dx;
        public int Dy;
        public IntPtr DeviceHandle;
    }

    public class InputDeliveryMetrics
    {
        public int SampleCount = 0;
        public double AvgDeltaMs = 0;
        public double MedianDeltaMs = 0;
        public double P95DeltaMs = 0;
        public double P99DeltaMs = 0;
        public double MinDeltaMs = 0;
        public double MaxDeltaMs = 0;
        public double JitterStdDevMs = 0;
        public double EquivalentAvgHz = 0;
        public double EquivalentMedianHz = 0;
        public double BatchPercent = 0;
        public int GapCount = 0;
        public double ConsistencyScore = 0;
        public IntPtr ActiveDeviceHandle = IntPtr.Zero;
        public string ActiveDeviceName = "";
        public List<double> RecentDeltasMs = new List<double>();
    }

    public class RawInputSampleTracker : IDisposable
    {
        private readonly object syncLock = new object();
        private readonly List<InputEventSample> samples = new List<InputEventSample>(4096);
        private readonly int maxCapacity;
        private long lastTick = 0;
        private IntPtr lastDeviceHandle = IntPtr.Zero;
        private string cachedLastDeviceName = "";
        private IntPtr reusableBuffer = IntPtr.Zero;
        private uint reusableBufferSize = 256;

        public RawInputSampleTracker(int maxCapacity)
        {
            this.maxCapacity = Math.Max(128, maxCapacity);
            this.reusableBuffer = Marshal.AllocHGlobal((int)reusableBufferSize);
        }

        public void Reset()
        {
            lock (syncLock)
            {
                samples.Clear();
                lastTick = 0;
            }
        }

        public void Dispose()
        {
            lock (syncLock)
            {
                if (reusableBuffer != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(reusableBuffer);
                    reusableBuffer = IntPtr.Zero;
                }
            }
        }

        public void RecordRawMouseMessage(IntPtr hRawInput)
        {
            long now = Stopwatch.GetTimestamp();
            uint hdrSize = (uint)Marshal.SizeOf(typeof(NativeMethods.RAWINPUTHEADER));
            uint dwSize = 0;
            if (NativeMethods.GetRawInputData(hRawInput, NativeMethods.RID_INPUT, IntPtr.Zero, ref dwSize, hdrSize) == uint.MaxValue || dwSize == 0)
                return;

            IntPtr buf;
            bool tempAlloc = false;
            lock (syncLock)
            {
                if (dwSize <= reusableBufferSize && reusableBuffer != IntPtr.Zero)
                {
                    buf = reusableBuffer;
                }
                else
                {
                    buf = Marshal.AllocHGlobal((int)dwSize);
                    tempAlloc = true;
                }

                try
                {
                    uint readBytes = NativeMethods.GetRawInputData(hRawInput, NativeMethods.RID_INPUT, buf, ref dwSize, hdrSize);
                    if (readBytes == uint.MaxValue || readBytes < hdrSize + Marshal.SizeOf(typeof(NativeMethods.RAWMOUSE)))
                        return;

                    NativeMethods.RAWINPUTHEADER header = (NativeMethods.RAWINPUTHEADER)Marshal.PtrToStructure(buf, typeof(NativeMethods.RAWINPUTHEADER));
                    if (header.dwType != NativeMethods.RIM_TYPEMOUSE)
                        return;

                    IntPtr mousePtr = new IntPtr(buf.ToInt64() + hdrSize);
                    NativeMethods.RAWMOUSE mouse = (NativeMethods.RAWMOUSE)Marshal.PtrToStructure(mousePtr, typeof(NativeMethods.RAWMOUSE));

                    // Skip zero-delta status packets with no button action
                    if (mouse.lLastX == 0 && mouse.lLastY == 0 && mouse.usButtonFlags == 0)
                        return;

                    if (header.hDevice != lastDeviceHandle)
                    {
                        lastDeviceHandle = header.hDevice;
                        cachedLastDeviceName = NativeMethods.GetRawInputDeviceNameSafe(header.hDevice);
                    }

                    if (lastTick != 0)
                    {
                        double deltaMs = ((now - lastTick) * 1000.0) / Stopwatch.Frequency;
                        if (deltaMs >= 0.01 && deltaMs <= 120.0)
                        {
                            if (samples.Count >= maxCapacity)
                                samples.RemoveAt(0);
                            samples.Add(new InputEventSample
                            {
                                DeltaMs = deltaMs,
                                Dx = mouse.lLastX,
                                Dy = mouse.lLastY,
                                DeviceHandle = header.hDevice
                            });
                        }
                    }
                    lastTick = now;
                }
                finally
                {
                    if (tempAlloc) Marshal.FreeHGlobal(buf);
                }
            }
        }

        public InputDeliveryMetrics ComputeMetrics(int windowCount)
        {
            InputDeliveryMetrics m = new InputDeliveryMetrics();
            List<double> rawVals;
            lock (syncLock)
            {
                m.ActiveDeviceHandle = lastDeviceHandle;
                m.ActiveDeviceName = cachedLastDeviceName ?? "";
                if (samples.Count == 0) return m;

                int start = (windowCount > 0 && samples.Count > windowCount) ? (samples.Count - windowCount) : 0;
                int count = samples.Count - start;
                rawVals = new List<double>(count);
                for (int i = start; i < samples.Count; i++)
                {
                    rawVals.Add(samples[i].DeltaMs);
                    m.RecentDeltasMs.Add(samples[i].DeltaMs);
                }
            }

            m.SampleCount = rawVals.Count;
            if (m.SampleCount == 0) return m;

            double sum = 0;
            int batchCount = 0;
            for (int i = 0; i < rawVals.Count; i++)
            {
                double v = rawVals[i];
                sum += v;
                if (v < 0.12) batchCount++;
            }
            m.AvgDeltaMs = sum / m.SampleCount;
            m.EquivalentAvgHz = m.AvgDeltaMs > 0 ? (1000.0 / m.AvgDeltaMs) : 0;
            m.BatchPercent = (batchCount * 100.0) / m.SampleCount;

            List<double> sorted = new List<double>(rawVals);
            sorted.Sort();
            m.MinDeltaMs = sorted[0];
            m.MaxDeltaMs = sorted[sorted.Count - 1];
            m.MedianDeltaMs = sorted[sorted.Count / 2];
            m.P95DeltaMs = sorted[Math.Min(sorted.Count - 1, (int)(sorted.Count * 0.95))];
            m.P99DeltaMs = sorted[Math.Min(sorted.Count - 1, (int)(sorted.Count * 0.99))];
            m.EquivalentMedianHz = m.MedianDeltaMs > 0 ? (1000.0 / m.MedianDeltaMs) : 0;

            double gapThreshold = Math.Max(2.2, m.MedianDeltaMs * 2.5);
            double varSum = 0;
            int gaps = 0;
            for (int i = 0; i < rawVals.Count; i++)
            {
                double v = rawVals[i];
                double diff = v - m.AvgDeltaMs;
                varSum += diff * diff;
                if (v > gapThreshold) gaps++;
            }
            m.GapCount = gaps;
            m.JitterStdDevMs = Math.Sqrt(varSum / Math.Max(1, m.SampleCount - 1));
            double baselineDelta = m.MedianDeltaMs > 0 ? m.MedianDeltaMs : m.AvgDeltaMs;
            m.ConsistencyScore = Math.Max(0.0, Math.Min(100.0, 100.0 - ((m.JitterStdDevMs / Math.Max(0.1, baselineDelta)) * 45.0) - (gaps * 1.5)));

            return m;
        }

        public bool ExportCsv(string filePath)
        {
            List<InputEventSample> copy;
            lock (syncLock)
            {
                copy = new List<InputEventSample>(samples);
            }
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("SampleIndex,DeltaMs,Dx,Dy,DeviceHandleHex");
            for (int i = 0; i < copy.Count; i++)
            {
                sb.AppendLine(string.Format(System.Globalization.CultureInfo.InvariantCulture,
                    "{0},{1:0.0000},{2},{3},0x{4:X}",
                    i + 1, copy[i].DeltaMs, copy[i].Dx, copy[i].Dy, copy[i].DeviceHandle.ToInt64()));
            }
            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
            return true;
        }
    }

    public class RawInputHookNativeWindow : NativeWindow
    {
        private readonly Action<IntPtr> onRawInput;
        private bool registered = false;

        public RawInputHookNativeWindow(Action<IntPtr> onRawInputCallback)
        {
            this.onRawInput = onRawInputCallback;
        }

        public bool AttachAndRegister(IntPtr hwnd)
        {
            if (hwnd == IntPtr.Zero) return false;
            try
            {
                if (this.Handle != hwnd)
                {
                    if (this.Handle != IntPtr.Zero) ReleaseHandle();
                    AssignHandle(hwnd);
                }

                NativeMethods.RAWINPUTDEVICE[] rid = new NativeMethods.RAWINPUTDEVICE[1];
                rid[0].usUsagePage = NativeMethods.HID_USAGE_PAGE_GENERIC;
                rid[0].usUsage = NativeMethods.HID_USAGE_GENERIC_MOUSE;
                rid[0].dwFlags = 0; // Active only while application window has focus
                rid[0].hwndTarget = hwnd;

                registered = NativeMethods.RegisterRawInputDevices(rid, 1, (uint)Marshal.SizeOf(typeof(NativeMethods.RAWINPUTDEVICE)));
                return registered;
            }
            catch
            {
                return false;
            }
        }

        public void UnregisterAndDetach()
        {
            try
            {
                if (registered)
                {
                    NativeMethods.RAWINPUTDEVICE[] rid = new NativeMethods.RAWINPUTDEVICE[1];
                    rid[0].usUsagePage = NativeMethods.HID_USAGE_PAGE_GENERIC;
                    rid[0].usUsage = NativeMethods.HID_USAGE_GENERIC_MOUSE;
                    rid[0].dwFlags = NativeMethods.RIDEV_REMOVE;
                    rid[0].hwndTarget = IntPtr.Zero;
                    NativeMethods.RegisterRawInputDevices(rid, 1, (uint)Marshal.SizeOf(typeof(NativeMethods.RAWINPUTDEVICE)));
                    registered = false;
                }
            }
            catch { }

            try
            {
                if (this.Handle != IntPtr.Zero) ReleaseHandle();
            }
            catch { }
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == NativeMethods.WM_INPUT && onRawInput != null)
            {
                onRawInput(m.LParam);
            }
            base.WndProc(ref m);
        }
    }

    public class UsbAttachedDeviceInfo
    {
        public string ControllerName = "";
        public string ControllerPnpId = "";
        public string DeviceName = "";
        public string DeviceClass = "";
        public string PnpId = "";
        public string RoleTag = ""; // "Fare / Mouse", "Klavye", "Hub", "Ses/Kamera", "Bluetooth", "Diğer"
        public string PowerFlagsSummary = "";
        public bool HasPowerSavingOn = false;
        public bool IsRawInputMouse = false;
        public bool IsRawInputKeyboard = false;
    }

    public class UsbTopologyReport
    {
        public List<string> Controllers = new List<string>();
        public List<UsbAttachedDeviceInfo> Devices = new List<UsbAttachedDeviceInfo>();
        public List<string> Findings = new List<string>();
        public string MouseQueueSize = "";
        public string KeyboardQueueSize = "";
        public bool UsbSelectiveSuspendDisabled = false;
        public string ScanError = "";
    }

    public static class UsbInputTopologyScanner
    {
        private class PnpInfo
        {
            public string PnpId;
            public string Name;
            public string PnpClass;
        }

        private static string ExtractDeviceIdFromWmiRef(string wmiRef)
        {
            if (string.IsNullOrEmpty(wmiRef)) return "";
            int idx = wmiRef.IndexOf("DeviceID=", StringComparison.OrdinalIgnoreCase);
            if (idx < 0) return "";
            string sub = wmiRef.Substring(idx + 9).Trim().Trim('"');
            return sub.Replace("\\\\", "\\");
        }

        private static string ExtractVidPid(string id)
        {
            if (string.IsNullOrEmpty(id)) return "";
            string up = id.ToUpperInvariant();
            int vIdx = up.IndexOf("VID_");
            if (vIdx < 0) return "";
            int pIdx = up.IndexOf("PID_", vIdx);
            if (pIdx < 0 || pIdx + 8 > up.Length) return "";
            return up.Substring(vIdx, Math.Min(17, pIdx + 8 - vIdx));
        }

        public static UsbTopologyReport ScanUsbTopology(StateVault vault)
        {
            UsbTopologyReport report = new UsbTopologyReport();
            try
            {
                // 1. Enumerate Raw Input Mice & Keyboards
                HashSet<string> rawMouseVidPids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                HashSet<string> rawKbdVidPids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                uint rawCount = 0;
                uint rawStructSize = (uint)Marshal.SizeOf(typeof(NativeMethods.RAWINPUTDEVICELIST));
                if (NativeMethods.GetRawInputDeviceList(IntPtr.Zero, ref rawCount, rawStructSize) == 0 && rawCount > 0 && rawCount < 512)
                {
                    IntPtr pList = Marshal.AllocHGlobal((int)(rawCount * rawStructSize));
                    try
                    {
                        uint actual = NativeMethods.GetRawInputDeviceList(pList, ref rawCount, rawStructSize);
                        if (actual != uint.MaxValue)
                        {
                            for (int i = 0; i < (int)actual; i++)
                            {
                                IntPtr cur = new IntPtr(pList.ToInt64() + i * rawStructSize);
                                NativeMethods.RAWINPUTDEVICELIST item = (NativeMethods.RAWINPUTDEVICELIST)Marshal.PtrToStructure(cur, typeof(NativeMethods.RAWINPUTDEVICELIST));
                                string devName = NativeMethods.GetRawInputDeviceNameSafe(item.hDevice);
                                string vp = ExtractVidPid(devName);
                                if (!string.IsNullOrEmpty(vp))
                                {
                                    if (item.dwType == NativeMethods.RIM_TYPEMOUSE) rawMouseVidPids.Add(vp);
                                    else if (item.dwType == NativeMethods.RIM_TYPEKEYBOARD) rawKbdVidPids.Add(vp);
                                }
                            }
                        }
                    }
                    finally
                    {
                        Marshal.FreeHGlobal(pList);
                    }
                }

                // 2. Single fast WMI query for active PnP devices
                Dictionary<string, PnpInfo> pnpMap = new Dictionary<string, PnpInfo>(StringComparer.OrdinalIgnoreCase);
                using (ManagementObjectSearcher sPnp = new ManagementObjectSearcher("SELECT PNPDeviceID, Name, PNPClass FROM Win32_PnPEntity WHERE Status = 'OK'"))
                {
                    foreach (ManagementObject obj in sPnp.Get())
                    {
                        string id = Convert.ToString(obj["PNPDeviceID"] ?? "");
                        if (string.IsNullOrEmpty(id)) continue;
                        pnpMap[id] = new PnpInfo
                        {
                            PnpId = id,
                            Name = Convert.ToString(obj["Name"] ?? id),
                            PnpClass = Convert.ToString(obj["PNPClass"] ?? "")
                        };
                    }
                }

                // 3. Single fast WMI query for USB Controller -> Attached Device tree
                Dictionary<string, string> controllerDisplayNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                Dictionary<string, int> controllerDeviceCount = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                Dictionary<string, List<string>> controllerMiceNames = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
                Dictionary<string, int> controllerHeavyPeers = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

                using (ManagementObjectSearcher sUsb = new ManagementObjectSearcher("SELECT Antecedent, Dependent FROM Win32_USBControllerDevice"))
                {
                    foreach (ManagementObject rel in sUsb.Get())
                    {
                        string ctlId = ExtractDeviceIdFromWmiRef(Convert.ToString(rel["Antecedent"] ?? ""));
                        string depId = ExtractDeviceIdFromWmiRef(Convert.ToString(rel["Dependent"] ?? ""));
                        if (string.IsNullOrEmpty(ctlId) || string.IsNullOrEmpty(depId)) continue;

                        string ctlDisplayName;
                        if (!controllerDisplayNames.TryGetValue(ctlId, out ctlDisplayName))
                        {
                            PnpInfo ctlInfo;
                            string baseCtlName = pnpMap.TryGetValue(ctlId, out ctlInfo) ? ctlInfo.Name : ctlId;
                            string tag = "";
                            int devIdx = ctlId.IndexOf("DEV_", StringComparison.OrdinalIgnoreCase);
                            if (devIdx >= 0 && devIdx + 8 <= ctlId.Length)
                                tag = ctlId.Substring(devIdx, 8).ToUpperInvariant();
                            string candidateName = string.IsNullOrEmpty(tag)
                                ? string.Format("{0} (#{1})", baseCtlName, controllerDisplayNames.Count + 1)
                                : string.Format("{0} [{1}]", baseCtlName, tag);
                            if (report.Controllers.Contains(candidateName))
                                candidateName = string.Format("{0} (#{1})", candidateName, controllerDisplayNames.Count + 1);
                            ctlDisplayName = candidateName;
                            controllerDisplayNames[ctlId] = ctlDisplayName;
                            report.Controllers.Add(ctlDisplayName);
                        }

                        PnpInfo depInfo;
                        if (!pnpMap.TryGetValue(depId, out depInfo)) continue;

                        string cls = depInfo.PnpClass ?? "";
                        string nameLower = (depInfo.Name ?? "").ToLowerInvariant();
                        string vp = ExtractVidPid(depId);
                        bool isMouse = string.Equals(cls, "Mouse", StringComparison.OrdinalIgnoreCase) || (!string.IsNullOrEmpty(vp) && rawMouseVidPids.Contains(vp));
                        bool isKbd = string.Equals(cls, "Keyboard", StringComparison.OrdinalIgnoreCase) || (!string.IsNullOrEmpty(vp) && rawKbdVidPids.Contains(vp));
                        bool isHub = depId.IndexOf("ROOT_HUB", StringComparison.OrdinalIgnoreCase) >= 0 || nameLower.Contains("hub");
                        bool isBt = string.Equals(cls, "Bluetooth", StringComparison.OrdinalIgnoreCase) || nameLower.Contains("bluetooth");
                        bool isHeavy = string.Equals(cls, "MEDIA", StringComparison.OrdinalIgnoreCase) || string.Equals(cls, "Camera", StringComparison.OrdinalIgnoreCase) ||
                                       string.Equals(cls, "AudioEndpoint", StringComparison.OrdinalIgnoreCase) || string.Equals(cls, "DiskDrive", StringComparison.OrdinalIgnoreCase) ||
                                       string.Equals(cls, "Net", StringComparison.OrdinalIgnoreCase) || isBt;

                        string role = isMouse ? "🖱️ Fare / Mouse"
                                    : (isKbd ? "⌨️ Klavye"
                                    : (isHub ? "🔌 USB Hub"
                                    : (isBt ? "📶 Bluetooth"
                                    : (isHeavy ? "🎧 Bant Genişliği (Ses/Kamera/Ağ)"
                                    : (!string.IsNullOrEmpty(cls) ? cls : "USB Bileşeni")))));

                        // Inspect Registry Device Parameters Power Flags
                        bool powSave = false;
                        List<string> powTokens = new List<string>();
                        try
                        {
                            using (RegistryKey dpKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum\" + depId + @"\Device Parameters", false))
                            {
                                if (dpKey != null)
                                {
                                    object epm = dpKey.GetValue("EnhancedPowerManagementEnabled", null);
                                    if (epm != null)
                                    {
                                        int ev = Convert.ToInt32(epm);
                                        powTokens.Add("EnhPwrMgmt=" + ev);
                                        if (ev == 1) powSave = true;
                                    }
                                    object idle = dpKey.GetValue("AllowIdleIrpInD3", null);
                                    if (idle != null)
                                    {
                                        int iv = Convert.ToInt32(idle);
                                        powTokens.Add("IdleD3=" + iv);
                                        if (iv == 1) powSave = true;
                                    }
                                    object sel = dpKey.GetValue("SelectiveSuspendEnabled", null);
                                    if (sel != null)
                                    {
                                        int sv = Convert.ToInt32(sel);
                                        powTokens.Add("SelSusp=" + sv);
                                        if (sv == 1) powSave = true;
                                    }
                                }
                            }
                        }
                        catch { }

                        if (!controllerDeviceCount.ContainsKey(ctlId)) controllerDeviceCount[ctlId] = 0;
                        controllerDeviceCount[ctlId]++;

                        if (isMouse)
                        {
                            if (!controllerMiceNames.ContainsKey(ctlId)) controllerMiceNames[ctlId] = new List<string>();
                            if (!controllerMiceNames[ctlId].Contains(depInfo.Name)) controllerMiceNames[ctlId].Add(depInfo.Name);
                        }
                        if (isHeavy)
                        {
                            if (!controllerHeavyPeers.ContainsKey(ctlId)) controllerHeavyPeers[ctlId] = 0;
                            controllerHeavyPeers[ctlId]++;
                        }

                        report.Devices.Add(new UsbAttachedDeviceInfo
                        {
                            ControllerName = ctlDisplayName,
                            ControllerPnpId = ctlId,
                            DeviceName = depInfo.Name,
                            DeviceClass = cls,
                            PnpId = depId,
                            RoleTag = role,
                            PowerFlagsSummary = powTokens.Count > 0 ? string.Join(", ", powTokens.ToArray()) : "Standart",
                            HasPowerSavingOn = powSave,
                            IsRawInputMouse = isMouse,
                            IsRawInputKeyboard = isKbd
                        });
                    }
                }

                // 4. Read HID Queue & USB Suspend settings
                report.MouseQueueSize = vault.ReadRegistryDisplay("HKLM", @"SYSTEM\CurrentControlSet\Services\mouclass\Parameters", "MouseDataQueueSize", "100 (Varsayılan)");
                report.KeyboardQueueSize = vault.ReadRegistryDisplay("HKLM", @"SYSTEM\CurrentControlSet\Services\kbdclass\Parameters", "KeyboardDataQueueSize", "100 (Varsayılan)");
                string usbSusp = vault.ReadRegistryDisplay("HKLM", @"SYSTEM\CurrentControlSet\Services\USB", "DisableSelectiveSuspend", "");
                report.UsbSelectiveSuspendDisabled = (usbSusp == "1");

                // 5. Generate evidence-based topology findings
                if (report.Controllers.Count >= 2)
                {
                    report.Findings.Add(string.Format("ℹ️ Sistemde {0} adet ayrı USB xHCI Host Denetleyicisi algılandı.", report.Controllers.Count));
                    foreach (var kv in controllerMiceNames)
                    {
                        int heavyCount = controllerHeavyPeers.ContainsKey(kv.Key) ? controllerHeavyPeers[kv.Key] : 0;
                        string ctlLabel = controllerDisplayNames.ContainsKey(kv.Key) ? controllerDisplayNames[kv.Key] : kv.Key;
                        if (heavyCount > 0)
                        {
                            report.Findings.Add(string.Format(
                                "⚠️ Fare denetleyici paylaşımı: '{0}' denetleyicisi hem farenizi hem de {1} adet Bluetooth/Ses/Kamera/Ağ aygıtını taşıyor. Mümkünse fareyi diğer boş USB denetleyici port grubuna takıp InputLab Jitter farkını test edin.",
                                ctlLabel, heavyCount));
                        }
                    }
                }

                int idleWarnCount = 0;
                foreach (var d in report.Devices)
                {
                    if ((d.IsRawInputMouse || d.IsRawInputKeyboard) && d.HasPowerSavingOn)
                        idleWarnCount++;
                }
                if (idleWarnCount > 0)
                {
                    report.Findings.Add(string.Format("⚠️ {0} giriş/HID bileşeninde EnhancedPowerManagement veya AllowIdleIrpInD3 etkin (uyku uyanma mikro-gecikme riski).", idleWarnCount));
                }
                if (!report.UsbSelectiveSuspendDisabled)
                {
                    report.Findings.Add("ℹ️ Global USB Selective Suspend kapatılmamış (DisableSelectiveSuspend yok). Timer sekmesinden USB uyku korumasını yönetebilirsiniz.");
                }
            }
            catch (Exception ex)
            {
                report.ScanError = ex.Message;
            }
            return report;
        }
    }

    #endregion

    #region PCI Interrupt & MSI Mode Engine

    public class PciInterruptDeviceInfo
    {
        public string FriendlyName = "";
        public string ClassName = "";
        public string ClassTag = ""; // Display, Net, USB, Storage, HDC, MEDIA
        public string InstancePath = ""; // PCI\VEN_...
        public string RegistrySubKey = ""; // SYSTEM\CurrentControlSet\Enum\PCI\...
        public int? MsiSupported = null;
        public int? MessageNumberLimit = null;
        public int? DevicePolicy = null;
        public int? DevicePriority = null;
        public ulong AssignmentMask = 0;
        public bool HasAssignmentBytes = false;
        public bool IsPresentInOs = false;
        public string SafetyAdvisory = "";
    }

    public static class PciInterruptScanner
    {
        private static readonly Dictionary<string, string> ClassGuidMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "{4d36e968-e325-11ce-bfc1-08002be10318}", "Display" },
            { "{4d36e972-e325-11ce-bfc1-08002be10318}", "Net" },
            { "{36fc9e60-c465-11cf-8056-444553540000}", "USB" },
            { "{4d36e97b-e325-11ce-bfc1-08002be10318}", "Storage" },
            { "{4d36e96a-e325-11ce-bfc1-08002be10318}", "HDC" },
            { "{4d36e96c-e325-11ce-bfc1-08002be10318}", "MEDIA" }
        };

        public static string GetDevicePolicyLabel(int? policy)
        {
            if (!policy.HasValue) return "Sistem Varsayılanı";
            switch (policy.Value)
            {
                case 0: return "0 - Makine Varsayılanı (MachineDefault)";
                case 1: return "1 - Yakın Çekirdekler (AllClose)";
                case 2: return "2 - Tek Yakın Çekirdek (OneClose)";
                case 3: return "3 - Tüm Çekirdekler (AllProcessors)";
                case 4: return "4 - Özel Çekirdek Maskesi (Specified)";
                case 5: return "5 - MSI-X Mesajlarını Yay (Spread)";
                default: return policy.Value.ToString();
            }
        }

        public static string DecodeMaskToCoreList(ulong mask)
        {
            if (mask == 0) return "-";
            List<string> cores = new List<string>();
            int limit = Math.Min(64, Environment.ProcessorCount);
            for (int i = 0; i < limit; i++)
            {
                if ((mask & (1UL << i)) != 0)
                    cores.Add("CPU " + i);
            }
            if (cores.Count == 0) return "0x" + mask.ToString("X");
            return string.Join(", ", cores.ToArray()) + string.Format(" (0x{0:X})", mask);
        }

        public static List<PciInterruptDeviceInfo> ScanPciDevices(bool includeStorageAndAudio)
        {
            List<PciInterruptDeviceInfo> list = new List<PciInterruptDeviceInfo>();
            Dictionary<string, string> activeNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            try
            {
                using (ManagementObjectSearcher s = new ManagementObjectSearcher("SELECT PNPDeviceID, Name, Status FROM Win32_PnPEntity WHERE Status = 'OK'"))
                {
                    foreach (ManagementObject obj in s.Get())
                    {
                        string id = Convert.ToString(obj["PNPDeviceID"] ?? "");
                        if (id.StartsWith("PCI\\", StringComparison.OrdinalIgnoreCase))
                        {
                            activeNames[id] = Convert.ToString(obj["Name"] ?? id);
                        }
                    }
                }
            }
            catch { }

            try
            {
                using (RegistryKey pciRoot = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum\PCI", false))
                {
                    if (pciRoot == null) return list;
                    foreach (string devKeyName in pciRoot.GetSubKeyNames())
                    {
                        using (RegistryKey devKey = pciRoot.OpenSubKey(devKeyName, false))
                        {
                            if (devKey == null) continue;
                            foreach (string instName in devKey.GetSubKeyNames())
                            {
                                string pnpId = "PCI\\" + devKeyName + "\\" + instName;
                                bool isPresent = activeNames.ContainsKey(pnpId);
                                if (!isPresent && activeNames.Count > 0) continue; // Filter phantom/disconnected instances

                                string regSub = @"SYSTEM\CurrentControlSet\Enum\" + pnpId;
                                using (RegistryKey instKey = devKey.OpenSubKey(instName, false))
                                {
                                    if (instKey == null) continue;
                                    string clsGuid = Convert.ToString(instKey.GetValue("ClassGUID", "")).Trim();
                                    string clsTag;
                                    if (!ClassGuidMap.TryGetValue(clsGuid, out clsTag)) continue;

                                    if (!includeStorageAndAudio && (clsTag == "HDC" || clsTag == "MEDIA"))
                                        continue;

                                    string friendly = isPresent ? activeNames[pnpId] : Convert.ToString(instKey.GetValue("FriendlyName", "") ?? "");
                                    if (string.IsNullOrEmpty(friendly))
                                    {
                                        string desc = Convert.ToString(instKey.GetValue("DeviceDesc", pnpId) ?? pnpId);
                                        int semi = desc.LastIndexOf(';');
                                        friendly = (semi >= 0 && semi < desc.Length - 1) ? desc.Substring(semi + 1) : desc;
                                    }

                                    PciInterruptDeviceInfo info = new PciInterruptDeviceInfo
                                    {
                                        FriendlyName = friendly,
                                        ClassName = clsTag == "Display" ? "GPU / Ekran" : (clsTag == "Net" ? "Ağ Kartı" : (clsTag == "USB" ? "USB xHCI" : (clsTag == "Storage" ? "NVMe / Depolama" : (clsTag == "HDC" ? "AHCI / SATA" : "Ses / Audio")))),
                                        ClassTag = clsTag,
                                        InstancePath = pnpId,
                                        RegistrySubKey = regSub,
                                        IsPresentInOs = isPresent
                                    };

                                    using (RegistryKey msiKey = instKey.OpenSubKey(@"Device Parameters\Interrupt Management\MessageSignaledInterruptProperties", false))
                                    {
                                        if (msiKey != null)
                                        {
                                            object ms = msiKey.GetValue("MSISupported", null);
                                            if (ms != null) info.MsiSupported = Convert.ToInt32(ms);
                                            object ml = msiKey.GetValue("MessageNumberLimit", null);
                                            if (ml != null) info.MessageNumberLimit = Convert.ToInt32(ml);
                                        }
                                    }

                                    using (RegistryKey affKey = instKey.OpenSubKey(@"Device Parameters\Interrupt Management\Affinity Policy", false))
                                    {
                                        if (affKey != null)
                                        {
                                            object dp = affKey.GetValue("DevicePolicy", null);
                                            if (dp != null) info.DevicePolicy = Convert.ToInt32(dp);
                                            object pr = affKey.GetValue("DevicePriority", null);
                                            if (pr != null) info.DevicePriority = Convert.ToInt32(pr);

                                            object ao = affKey.GetValue("AssignmentSetOverride", null);
                                            if (ao is byte[])
                                            {
                                                byte[] b = (byte[])ao;
                                                ulong m = 0;
                                                for (int bi = 0; bi < b.Length && bi < 8; bi++)
                                                    m |= ((ulong)b[bi]) << (bi * 8);
                                                info.AssignmentMask = m;
                                                info.HasAssignmentBytes = true;
                                            }
                                            else if (ao != null)
                                            {
                                                try
                                                {
                                                    info.AssignmentMask = Convert.ToUInt64(ao);
                                                    info.HasAssignmentBytes = true;
                                                }
                                                catch { }
                                            }
                                        }
                                    }

                                    // Safety advisory
                                    if (clsTag == "Display" || clsTag == "Net" || clsTag == "USB")
                                    {
                                        if (!info.MsiSupported.HasValue || info.MsiSupported.Value == 0)
                                            info.SafetyAdvisory = "⚠️ Line-Based IRQ veya tanımsız: Modern GPU/NIC/USB aygıtlarında MSI (1) paylaşımlı IRQ çatışmasını önler (Restart gerekir).";
                                        else
                                            info.SafetyAdvisory = "✅ MSI Modu Etkin (1). Yalnızca spesifik çekirdek izolasyonu testi yapacaksanız Affinity Policy değiştirin.";
                                    }
                                    else if (clsTag == "Storage" || clsTag == "HDC")
                                    {
                                        info.SafetyAdvisory = "ℹ️ NVMe/AHCI aygıtlarında Policy=5 (Spread) çoklu I/O kuyruklarını tüm çekirdeklere dağıtır; tek çekirdeğe kilitlemek disk gecikmesini bozabilir.";
                                    }
                                    else
                                    {
                                        info.SafetyAdvisory = "ℹ️ Ses denetleyicilerinde MSI desteği bazı eski kodeklerde cızırtıya yol açabilir; önce yalnızca MSI/IRQ durumunu izleyin.";
                                    }

                                    list.Add(info);
                                }
                            }
                        }
                    }
                }
            }
            catch { }

            list.Sort((a, b) =>
            {
                int cmp = string.Compare(a.ClassTag, b.ClassTag, StringComparison.OrdinalIgnoreCase);
                if (cmp != 0) return cmp;
                return string.Compare(a.FriendlyName, b.FriendlyName, StringComparison.OrdinalIgnoreCase);
            });
            return list;
        }

        public static bool ApplyDeviceSettingsTracked(StateVault vault, PciInterruptDeviceInfo dev, int msiOption, int policyOption, ulong affinityMask, int priorityOption, out string verificationSummary)
        {
            verificationSummary = "";
            if (vault == null || dev == null || string.IsNullOrEmpty(dev.RegistrySubKey)) return false;

            string tag = "MSI/IRQ: " + dev.FriendlyName;
            string msiPath = dev.RegistrySubKey + @"\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties";
            string affPath = dev.RegistrySubKey + @"\Device Parameters\Interrupt Management\Affinity Policy";

            bool ok = true;
            if (msiOption == -1)
                ok &= vault.DeleteRegistryTracked(tag, "HKLM", msiPath, "MSISupported");
            else
                ok &= vault.SetRegistryTracked(tag, "HKLM", msiPath, "MSISupported", msiOption, RegistryValueKind.DWord);

            if (policyOption == -1)
            {
                ok &= vault.DeleteRegistryTracked(tag, "HKLM", affPath, "DevicePolicy");
                ok &= vault.DeleteRegistryTracked(tag, "HKLM", affPath, "AssignmentSetOverride");
            }
            else
            {
                ok &= vault.SetRegistryTracked(tag, "HKLM", affPath, "DevicePolicy", policyOption, RegistryValueKind.DWord);
                if (policyOption == 4)
                {
                    if (affinityMask == 0) affinityMask = 1UL;
                    byte[] maskBytes = BitConverter.GetBytes(affinityMask);
                    ok &= vault.SetRegistryTracked(tag, "HKLM", affPath, "AssignmentSetOverride", maskBytes, RegistryValueKind.Binary);
                }
                else
                {
                    vault.DeleteRegistryTracked(tag, "HKLM", affPath, "AssignmentSetOverride");
                }
            }

            if (priorityOption == -1)
                ok &= vault.DeleteRegistryTracked(tag, "HKLM", affPath, "DevicePriority");
            else
                ok &= vault.SetRegistryTracked(tag, "HKLM", affPath, "DevicePriority", priorityOption, RegistryValueKind.DWord);

            // Immediate read-back verification
            string rbMsi = vault.ReadRegistryDisplay("HKLM", msiPath, "MSISupported", "Varsayılan");
            string rbPol = vault.ReadRegistryDisplay("HKLM", affPath, "DevicePolicy", "Varsayılan");
            string rbMask = vault.ReadRegistryDisplay("HKLM", affPath, "AssignmentSetOverride", "-");
            verificationSummary = string.Format("Read-Back: MSISupported={0} | DevicePolicy={1} | Mask={2}", rbMsi, rbPol, rbMask);
            return ok;
        }

        public static void RevertDeviceSettingsTracked(StateVault vault, PciInterruptDeviceInfo dev)
        {
            if (vault == null || dev == null || string.IsNullOrEmpty(dev.RegistrySubKey)) return;
            string msiPath = dev.RegistrySubKey + @"\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties";
            string affPath = dev.RegistrySubKey + @"\Device Parameters\Interrupt Management\Affinity Policy";

            vault.RevertRegistryTracked("HKLM", msiPath, "MSISupported");
            vault.RevertRegistryTracked("HKLM", affPath, "DevicePolicy");
            vault.RevertRegistryTracked("HKLM", affPath, "AssignmentSetOverride");
            vault.RevertRegistryTracked("HKLM", affPath, "DevicePriority");
        }
    }

