    public class CustomParameterDialog : Form
    {
        private TweakDefinition tweak;
        private CustomParamConfig cfg;
        private NumericUpDown numValue;

        public CustomParameterDialog(TweakDefinition tweak)
        {
            this.tweak = tweak;
            this.cfg = tweak.CustomParam;

            this.Text = Loc.T("Argon Makineye Özel Parametre Ayarı", "Argon Machine-Specific Parameter Config");
            this.Size = new Size(590, 490);
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = false;
            this.ShowInTaskbar = false;
            this.StartPosition = FormStartPosition.CenterParent;
            this.BackColor = Color.FromArgb(15, 20, 28);
            this.ForeColor = Color.FromArgb(226, 232, 240);

            // Header Panel
            Panel pnlHeader = new Panel
            {
                Dock = DockStyle.Top,
                Height = 60,
                BackColor = Color.FromArgb(20, 28, 42),
                Padding = new Padding(16, 8, 16, 8)
            };
            pnlHeader.Paint += (s, e) =>
            {
                using (Pen p = new Pen(Color.FromArgb(56, 189, 248), 1))
                {
                    e.Graphics.DrawLine(p, 0, pnlHeader.Height - 1, pnlHeader.Width, pnlHeader.Height - 1);
                }
            };

            Label lblTitle = new Label
            {
                Text = "⚙ " + tweak.Title,
                Font = new Font("Segoe UI", 10.5f, FontStyle.Bold),
                ForeColor = Color.FromArgb(56, 189, 248),
                AutoSize = true,
                Location = new Point(14, 8)
            };
            pnlHeader.Controls.Add(lblTitle);

            Label lblSub = new Label
            {
                Text = cfg.DisplayLabel + " — " + (tweak.TargetPathOrApi ?? "Kernel / Win32 API"),
                Font = new Font("Segoe UI", 8.2f, FontStyle.Regular),
                ForeColor = Color.FromArgb(148, 163, 184),
                AutoSize = true,
                Location = new Point(14, 32)
            };
            pnlHeader.Controls.Add(lblSub);
            this.Controls.Add(pnlHeader);

            // Body Panel
            Panel pnlBody = new Panel
            {
                Location = new Point(16, 70),
                Size = new Size(542, 335),
                BackColor = Color.Transparent
            };

            int currentLiveVal = cfg.ReadCurrentValueFunc != null ? cfg.ReadCurrentValueFunc() : cfg.DefaultValue;

            Label lblRegPath = new Label
            {
                Text = Loc.T("Sistem Hedefi (Kayıt Defteri):", "System Target (Registry):") + " " + (cfg.RegeditTargetPath ?? ""),
                Font = new Font("Consolas", 8.2f, FontStyle.Regular),
                ForeColor = Color.FromArgb(125, 211, 252),
                Location = new Point(0, 4),
                Size = new Size(542, 18),
                AutoEllipsis = true
            };
            pnlBody.Controls.Add(lblRegPath);

            Label lblLiveTruth = new Label
            {
                Text = string.Format(Loc.T("Windows'taki Canlı Değer: {0} {1}", "Current Windows Value: {0} {1}"), currentLiveVal, cfg.Unit),
                Font = new Font("Segoe UI", 8.8f, FontStyle.Bold),
                ForeColor = Color.FromArgb(52, 211, 153),
                Location = new Point(0, 26),
                Size = new Size(542, 20)
            };
            pnlBody.Controls.Add(lblLiveTruth);

            Label lblDesc = new Label
            {
                Text = cfg.TechnicalDescription ?? "",
                Font = new Font("Segoe UI", 8.4f, FontStyle.Regular),
                ForeColor = Color.FromArgb(203, 213, 225),
                Location = new Point(0, 52),
                Size = new Size(542, 42)
            };
            pnlBody.Controls.Add(lblDesc);

            // Security Floor Badge Panel
            Panel pnlBadge = new Panel
            {
                Location = new Point(0, 100),
                Size = new Size(542, 34),
                BackColor = Color.FromArgb(32, 26, 18)
            };
            pnlBadge.Paint += (s, e) =>
            {
                using (Pen p = new Pen(Color.FromArgb(245, 158, 11), 1))
                {
                    e.Graphics.DrawRectangle(p, 0, 0, pnlBadge.Width - 1, pnlBadge.Height - 1);
                }
            };

            Label lblBadge = new Label
            {
                Text = string.Format(Loc.T(
                    "🛡️ Kesin Güvenlik Tabanı: En Az {0} {1} ({0} altı değerler donanım bütünlüğü için engellenir)",
                    "🛡️ Strict Security Floor: Minimum {0} {1} (Values below {0} are blocked for stability)"),
                    cfg.MinValue, cfg.Unit),
                Font = new Font("Segoe UI", 8.5f, FontStyle.Bold),
                ForeColor = Color.FromArgb(251, 191, 36),
                AutoSize = true,
                Location = new Point(10, 8)
            };
            pnlBadge.Controls.Add(lblBadge);
            pnlBody.Controls.Add(pnlBadge);

            // Numeric Input Section
            Label lblInputPrompt = new Label
            {
                Text = Loc.T("Makineye Özel Değer Belirleyin:", "Specify Machine-Specific Value:"),
                Font = new Font("Segoe UI", 9.0f, FontStyle.Bold),
                ForeColor = Color.FromArgb(226, 232, 240),
                Location = new Point(0, 148),
                AutoSize = true
            };
            pnlBody.Controls.Add(lblInputPrompt);

            numValue = new NumericUpDown
            {
                Minimum = 0,
                Maximum = cfg.MaxValue,
                Value = Math.Max(0, Math.Min(cfg.MaxValue, cfg.CurrentCustomValue > 0 ? cfg.CurrentCustomValue : currentLiveVal)),
                Font = new Font("Consolas", 13.5f, FontStyle.Bold),
                BackColor = Color.FromArgb(24, 32, 46),
                ForeColor = Color.FromArgb(56, 189, 248),
                Location = new Point(0, 172),
                Size = new Size(130, 32)
            };
            pnlBody.Controls.Add(numValue);

            Label lblUnit = new Label
            {
                Text = cfg.Unit,
                Font = new Font("Segoe UI", 9.5f, FontStyle.Bold),
                ForeColor = Color.FromArgb(148, 163, 184),
                Location = new Point(136, 178),
                AutoSize = true
            };
            pnlBody.Controls.Add(lblUnit);

            // Quick Preset Chips
            if (cfg.PresetQuickChips != null && cfg.PresetQuickChips.Length > 0)
            {
                Label lblChipsCaption = new Label
                {
                    Text = Loc.T("Hızlı Seçim Önerileri:", "Quick Preset Suggestions:"),
                    Font = new Font("Segoe UI", 8.2f, FontStyle.Regular),
                    ForeColor = Color.FromArgb(148, 163, 184),
                    Location = new Point(0, 215),
                    AutoSize = true
                };
                pnlBody.Controls.Add(lblChipsCaption);

                int chipX = 0;
                for (int i = 0; i < cfg.PresetQuickChips.Length; i++)
                {
                    int valChip = cfg.PresetQuickChips[i];
                    string chipText = (cfg.PresetChipLabels != null && i < cfg.PresetChipLabels.Length)
                        ? cfg.PresetChipLabels[i]
                        : (valChip.ToString() + " " + cfg.Unit);

                    Button btnChip = new Button
                    {
                        Text = chipText,
                        Font = new Font("Segoe UI", 8.0f, FontStyle.Regular),
                        ForeColor = Color.FromArgb(203, 213, 225),
                        BackColor = Color.FromArgb(22, 29, 41),
                        FlatStyle = FlatStyle.Flat,
                        AutoSize = true,
                        Height = 26,
                        Location = new Point(chipX, 236),
                        Cursor = Cursors.Hand
                    };
                    btnChip.FlatAppearance.BorderSize = 1;
                    btnChip.FlatAppearance.BorderColor = Color.FromArgb(51, 65, 85);
                    btnChip.Click += (s, e) =>
                    {
                        numValue.Value = valChip;
                    };
                    pnlBody.Controls.Add(btnChip);
                    chipX += btnChip.PreferredSize.Width + 8;
                }
            }

            // Info Link to Security Guidance
            Button btnWhySecurity = new Button
            {
                Text = Loc.T("ℹ️ Neden Güvenlik Kilidi Var? / Manuel Regedit Rehberi", "ℹ️ Why Security Lock? / Manual Regedit Guide"),
                Font = new Font("Segoe UI", 8.2f, FontStyle.Underline),
                ForeColor = Color.FromArgb(248, 113, 113),
                BackColor = Color.Transparent,
                FlatStyle = FlatStyle.Flat,
                Size = new Size(542, 28),
                Location = new Point(0, 282),
                TextAlign = ContentAlignment.MiddleLeft,
                Cursor = Cursors.Hand
            };
            btnWhySecurity.FlatAppearance.BorderSize = 0;
            btnWhySecurity.Click += (s, e) =>
            {
                using (SecurityLockGuidanceDialog lockDlg = new SecurityLockGuidanceDialog(tweak, cfg, (int)numValue.Value))
                {
                    lockDlg.ShowDialog(this);
                }
            };
            pnlBody.Controls.Add(btnWhySecurity);

            this.Controls.Add(pnlBody);

            // Bottom Action Bar
            Panel pnlBottom = new Panel
            {
                Dock = DockStyle.Bottom,
                Height = 60,
                BackColor = Color.FromArgb(20, 25, 36)
            };
            pnlBottom.Paint += (s, e) =>
            {
                using (Pen p = new Pen(Color.FromArgb(30, 41, 59), 1))
                {
                    e.Graphics.DrawLine(p, 0, 0, pnlBottom.Width, 0);
                }
            };

            Button btnRegedit = new Button
            {
                Text = Loc.T("📂 Regedit", "📂 Regedit"),
                Font = new Font("Segoe UI", 8.5f, FontStyle.Regular),
                ForeColor = Color.FromArgb(56, 189, 248),
                BackColor = Color.FromArgb(18, 28, 40),
                FlatStyle = FlatStyle.Flat,
                Size = new Size(100, 34),
                Location = new Point(16, 13),
                Cursor = Cursors.Hand
            };
            btnRegedit.FlatAppearance.BorderSize = 1;
            btnRegedit.FlatAppearance.BorderColor = Color.FromArgb(45, 68, 98);
            btnRegedit.Click += (s, e) => GuidanceHelpers.OpenRegeditAtKey(cfg.RegeditTargetPath);
            pnlBottom.Controls.Add(btnRegedit);

            Button btnGoogle = new Button
            {
                Text = Loc.T("🌐 Google", "🌐 Google"),
                Font = new Font("Segoe UI", 8.5f, FontStyle.Regular),
                ForeColor = Color.FromArgb(167, 139, 250),
                BackColor = Color.FromArgb(26, 20, 38),
                FlatStyle = FlatStyle.Flat,
                Size = new Size(100, 34),
                Location = new Point(122, 13),
                Cursor = Cursors.Hand
            };
            btnGoogle.FlatAppearance.BorderSize = 1;
            btnGoogle.FlatAppearance.BorderColor = Color.FromArgb(68, 51, 98);
            btnGoogle.Click += (s, e) => GuidanceHelpers.OpenGoogleSearch(cfg.GoogleSearchQuery);
            pnlBottom.Controls.Add(btnGoogle);

            Button btnApply = new Button
            {
                Text = Loc.T("✓ Uygula & Kaydet", "✓ Apply & Save"),
                Font = new Font("Segoe UI", 9.0f, FontStyle.Bold),
                ForeColor = Color.White,
                BackColor = Color.FromArgb(16, 185, 129),
                FlatStyle = FlatStyle.Flat,
                Size = new Size(140, 34),
                Location = new Point(310, 13),
                Cursor = Cursors.Hand
            };
            btnApply.FlatAppearance.BorderSize = 0;
            btnApply.Click += (s, e) =>
            {
                int val = (int)numValue.Value;
                if (val < cfg.MinValue)
                {
                    // Trigger Strict Security Lock!
                    using (SecurityLockGuidanceDialog lockDlg = new SecurityLockGuidanceDialog(tweak, cfg, val))
                    {
                        lockDlg.ShowDialog(this);
                    }
                    return;
                }

                cfg.CurrentCustomValue = val;
                if (cfg.ApplyCustomAction != null)
                {
                    cfg.ApplyCustomAction(val);
                }
                this.DialogResult = DialogResult.OK;
                this.Close();
            };
            pnlBottom.Controls.Add(btnApply);

            Button btnCancel = new Button
            {
                Text = Loc.T("İptal", "Cancel"),
                Font = new Font("Segoe UI", 8.5f, FontStyle.Regular),
                ForeColor = Color.FromArgb(203, 213, 225),
                BackColor = Color.FromArgb(30, 41, 59),
                FlatStyle = FlatStyle.Flat,
                Size = new Size(95, 34),
                Location = new Point(458, 13),
                Cursor = Cursors.Hand,
                DialogResult = DialogResult.Cancel
            };
            btnCancel.FlatAppearance.BorderSize = 1;
            btnCancel.FlatAppearance.BorderColor = Color.FromArgb(51, 65, 85);
            btnCancel.Click += (s, e) => this.Close();
            pnlBottom.Controls.Add(btnCancel);

            this.Controls.Add(pnlBottom);
        }
    }

    public class GameWatchdogRuleDialog : Form
    {
        public GameWatchdogRule RuleResult { get; private set; }

        private TextBox txtTitle;
        private TextBox txtProcName;
        private ComboBox cmbPriority;
        private ComboBox cmbAffinity;
        private CheckBox chkEcoCage;
        private CheckBox chkIoBoost;
        private CheckBox chkEnabled;

        public GameWatchdogRuleDialog(GameWatchdogRule ruleToEdit)
        {
            this.Text = (ruleToEdit == null) ? "Yeni Oyun Nöbetçisi Kuralı Ekle" : "Oyun Nöbetçisi Kuralını Düzenle";
            this.Size = new Size(520, 420);
            this.StartPosition = FormStartPosition.CenterParent;
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = false;
            this.BackColor = Color.FromArgb(13, 16, 23);
            this.ForeColor = Color.White;
            this.Font = new Font("Segoe UI", 8.5f, FontStyle.Regular);

            Panel pnlHeader = new Panel
            {
                Dock = DockStyle.Top,
                Height = 48,
                BackColor = Color.FromArgb(18, 23, 34)
            };
            this.Controls.Add(pnlHeader);

            Label lblTitle = new Label
            {
                Text = "🎮 OYUN YAŞAM DÖNGÜSÜ & ÖZEL PERFORMANS KURALI",
                Font = new Font("Segoe UI", 9.0f, FontStyle.Bold),
                ForeColor = Color.FromArgb(52, 211, 153),
                Location = new Point(14, 14),
                AutoSize = true
            };
            pnlHeader.Controls.Add(lblTitle);

            int curY = 60;

            // Oyun Başlığı
            Label lblName = new Label { Text = "Oyun Başlığı:", ForeColor = Color.FromArgb(148, 163, 184), Location = new Point(18, curY + 2), AutoSize = true, Font = new Font("Segoe UI", 8.2f, FontStyle.Bold) };
            this.Controls.Add(lblName);
            txtTitle = new TextBox { Location = new Point(165, curY), Size = new Size(315, 22), BackColor = Color.FromArgb(18, 23, 34), ForeColor = Color.White, BorderStyle = BorderStyle.FixedSingle };
            this.Controls.Add(txtTitle);
            curY += 32;

            // Süreç Adı (.exe)
            Label lblExe = new Label { Text = "Süreç Adı (.exe):", ForeColor = Color.FromArgb(148, 163, 184), Location = new Point(18, curY + 2), AutoSize = true, Font = new Font("Segoe UI", 8.2f, FontStyle.Bold) };
            this.Controls.Add(lblExe);
            txtProcName = new TextBox { Location = new Point(165, curY), Size = new Size(225, 22), BackColor = Color.FromArgb(18, 23, 34), ForeColor = Color.White, BorderStyle = BorderStyle.FixedSingle };
            this.Controls.Add(txtProcName);

            Button btnBrowse = new Button
            {
                Text = "Gözat...",
                Location = new Point(398, curY - 1),
                Size = new Size(82, 24),
                FlatStyle = FlatStyle.Flat,
                BackColor = Color.FromArgb(30, 41, 59),
                ForeColor = Color.FromArgb(226, 232, 240),
                Cursor = Cursors.Hand
            };
            btnBrowse.FlatAppearance.BorderColor = Color.FromArgb(51, 65, 85);
            btnBrowse.Click += (s, e) =>
            {
                using (OpenFileDialog ofd = new OpenFileDialog())
                {
                    ofd.Filter = "Çalıştırılabilir Dosyalar (*.exe)|*.exe|Tüm Dosyalar (*.*)|*.*";
                    ofd.Title = "Oyun Yürütülebilir Dosyasını (.exe) Seçin";
                    if (ofd.ShowDialog() == DialogResult.OK)
                    {
                        string exeName = Path.GetFileNameWithoutExtension(ofd.FileName);
                        txtProcName.Text = exeName;
                        if (string.IsNullOrEmpty(txtTitle.Text.Trim()))
                            txtTitle.Text = exeName;
                    }
                }
            };
            this.Controls.Add(btnBrowse);
            curY += 32;

            // CPU Önceliği
            Label lblPrio = new Label { Text = "Hedef CPU Önceliği:", ForeColor = Color.FromArgb(148, 163, 184), Location = new Point(18, curY + 2), AutoSize = true, Font = new Font("Segoe UI", 8.2f, FontStyle.Bold) };
            this.Controls.Add(lblPrio);
            cmbPriority = new ComboBox { Location = new Point(165, curY), Size = new Size(315, 22), DropDownStyle = ComboBoxStyle.DropDownList, BackColor = Color.FromArgb(18, 23, 34), ForeColor = Color.White };
            cmbPriority.Items.Add("High (Yüksek - Espor Standardı)");
            cmbPriority.Items.Add("AboveNormal (Normal Üstü)");
            cmbPriority.Items.Add("Normal (Varsayılan)");
            cmbPriority.SelectedIndex = 0;
            this.Controls.Add(cmbPriority);
            curY += 32;

            // Çekirdek Politikası
            Label lblAff = new Label { Text = "Çekirdek Politikası:", ForeColor = Color.FromArgb(148, 163, 184), Location = new Point(18, curY + 2), AutoSize = true, Font = new Font("Segoe UI", 8.2f, FontStyle.Bold) };
            this.Controls.Add(lblAff);
            cmbAffinity = new ComboBox { Location = new Point(165, curY), Size = new Size(315, 22), DropDownStyle = ComboBoxStyle.DropDownList, BackColor = Color.FromArgb(18, 23, 34), ForeColor = Color.White };
            cmbAffinity.Items.Add("0: Tüm Çekirdekler (İşletim Sistemi Yönetimi)");
            cmbAffinity.Items.Add("1: Core 0 İzole (DPC/Kesme Koruması - Önerilen)");
            cmbAffinity.Items.Add("2: Fiziksel Çekirdekler (SMT/HT Devre Dışı)");
            cmbAffinity.Items.Add("3: Fiziksel Çekirdekler + Core 0 İzole");
            cmbAffinity.Items.Add("4: AMD 3D V-Cache CCD0 Kilidi (X3D L3 İzolasyonu)");
            cmbAffinity.Items.Add("5: Intel P-Cores Kilidi (E-Core Filtresi)");
            cmbAffinity.SelectedIndex = 1;
            this.Controls.Add(cmbAffinity);
            curY += 34;

            // Checkboxes
            chkEcoCage = new CheckBox
            {
                Text = "Gürültülü Arka Plan Uygulamalarını EcoQoS Kalkanına Al (Discord, Chrome vb.)",
                Location = new Point(18, curY),
                Size = new Size(470, 22),
                ForeColor = Color.FromArgb(226, 232, 240),
                Checked = true
            };
            this.Controls.Add(chkEcoCage);
            curY += 26;

            chkIoBoost = new CheckBox
            {
                Text = "Yüksek I/O ve Sayfa Önceliği Uygula (Disk & Bellek Gecikme Kalkanı)",
                Location = new Point(18, curY),
                Size = new Size(470, 22),
                ForeColor = Color.FromArgb(226, 232, 240),
                Checked = true
            };
            this.Controls.Add(chkIoBoost);
            curY += 26;

            chkEnabled = new CheckBox
            {
                Text = "Bu Kuralı Aktif Et",
                Location = new Point(18, curY),
                Size = new Size(470, 22),
                ForeColor = Color.FromArgb(52, 211, 153),
                Checked = true,
                Font = new Font("Segoe UI", 8.2f, FontStyle.Bold)
            };
            this.Controls.Add(chkEnabled);
            curY += 34;

            if (ruleToEdit != null)
            {
                txtTitle.Text = ruleToEdit.GameTitle;
                txtProcName.Text = ruleToEdit.ProcessName;
                if (ruleToEdit.TargetPriority == ProcessPriorityClass.AboveNormal) cmbPriority.SelectedIndex = 1;
                else if (ruleToEdit.TargetPriority == ProcessPriorityClass.Normal) cmbPriority.SelectedIndex = 2;
                else cmbPriority.SelectedIndex = 0;

                cmbAffinity.SelectedIndex = Math.Max(0, Math.Min(5, ruleToEdit.AffinityMode));
                chkEcoCage.Checked = ruleToEdit.EnableEcoCage;
                chkIoBoost.Checked = ruleToEdit.EnableIoBoost;
                chkEnabled.Checked = ruleToEdit.IsEnabled;
            }

            // Bottom Buttons
            Panel pnlBottom = new Panel
            {
                Dock = DockStyle.Bottom,
                Height = 50,
                BackColor = Color.FromArgb(18, 23, 34)
            };
            this.Controls.Add(pnlBottom);

            Button btnSave = new Button
            {
                Text = "Kuralı Kaydet",
                Location = new Point(pnlBottom.Width - 215, 11),
                Size = new Size(105, 28),
                FlatStyle = FlatStyle.Flat,
                BackColor = Color.FromArgb(16, 185, 129),
                ForeColor = Color.Black,
                Font = new Font("Segoe UI", 8.2f, FontStyle.Bold),
                Cursor = Cursors.Hand
            };
            btnSave.FlatAppearance.BorderSize = 0;
            btnSave.Click += (s, e) =>
            {
                string proc = txtProcName.Text.Trim().ToLowerInvariant().Replace(".exe", "");
                if (string.IsNullOrEmpty(proc))
                {
                    MessageBox.Show("Lütfen geçerli bir süreç (.exe) adı belirtin.", "Eksik Bilgi", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                GameWatchdogRule res = ruleToEdit != null ? ruleToEdit : new GameWatchdogRule();
                res.ProcessName = proc;
                res.GameTitle = string.IsNullOrEmpty(txtTitle.Text.Trim()) ? proc : txtTitle.Text.Trim();

                if (cmbPriority.SelectedIndex == 1) res.TargetPriority = ProcessPriorityClass.AboveNormal;
                else if (cmbPriority.SelectedIndex == 2) res.TargetPriority = ProcessPriorityClass.Normal;
                else res.TargetPriority = ProcessPriorityClass.High;

                res.AffinityMode = cmbAffinity.SelectedIndex;
                res.EnableEcoCage = chkEcoCage.Checked;
                res.EnableIoBoost = chkIoBoost.Checked;
                res.IsEnabled = chkEnabled.Checked;

                RuleResult = res;
                this.DialogResult = DialogResult.OK;
                this.Close();
            };
            pnlBottom.Controls.Add(btnSave);

            Button btnCancel = new Button
            {
                Text = "İptal",
                Location = new Point(pnlBottom.Width - 100, 11),
                Size = new Size(85, 28),
                FlatStyle = FlatStyle.Flat,
                BackColor = Color.FromArgb(30, 41, 59),
                ForeColor = Color.FromArgb(203, 213, 225),
                Cursor = Cursors.Hand,
                DialogResult = DialogResult.Cancel
            };
            btnCancel.FlatAppearance.BorderColor = Color.FromArgb(51, 65, 85);
