            btnTabUsb.BackColor = (idx == 1) ? Color.FromArgb(56, 189, 248) : Color.FromArgb(24, 31, 46);
            btnTabUsb.ForeColor = (idx == 1) ? Color.Black : Color.FromArgb(148, 163, 184);
        }

