                        ResetAction = v => v.RevertRegistryTracked("HKCU", @"Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement", "ScoobeSystemSettingEnabled")
                    },
                    new CustomizeOptionDef
                    {
                        OptionId = "priv_cdm",
