            AppendConsoleLog("GPU: " + detectedHw.GpuName);
            ProbeLiveNetworkSidebarDetails();

            RebuildBookmarksMenuAndTree();
            NavigateToPageKey("tab:11", true);
            RefreshHardwareMatrixCards();
