        private void BuildSystemMonitorView()
        {
            viewSystemMonitor = new Panel
            {
                Dock = DockStyle.Fill,
                AutoScroll = true,
                BackColor = ArgonTheme.BgCanvas,
                Padding = new Padding(22, 16, 22, 20),
