            pnlOverview.Controls.Add(tblKpi);

            monSysOsVal = CreateMonitorKpiCell(tblKpi, 0, Loc.T("İŞLETİM SİSTEMİ", "OPERATING SYSTEM"), "--");
            monSysPlanVal = CreateMonitorKpiCell(tblKpi, 1, Loc.T("GÜÇ PLANI / YETKİ", "POWER PLAN / MODE"), "--");
