            // ── 2. ROW 1: CPU & GPU CARDS ───────────────────────────────────────
            TableLayoutPanel tblRow1 = new TableLayoutPanel
            {
                Dock = DockStyle.Top,
                Height = 296,
                ColumnCount = 2,
                RowCount = 1,
                BackColor = ArgonTheme.BgCanvas,
