        private Panel CreateMonitorCardPanel(Padding margin)
        {
            Panel p = new Panel
            {
                Dock = DockStyle.Fill,
                BackColor = ArgonTheme.BgSurface,
                Margin = margin
            };
            p.Paint += (s, e) =>
            {
                using (Pen border = new Pen(ArgonTheme.BorderSubtle, 1))
                    e.Graphics.DrawRectangle(border, 0, 0, p.Width - 1, p.Height - 1);
            };
            return p;
        }

