                        if (selectedMonIdx == 0 && qolConfig.NotificationMonitorIndex >= 0 && qolConfig.NotificationMonitorIndex < screens.Length)
                        {
                            selectedMonIdx = qolConfig.NotificationMonitorIndex + 1;
