        private void RunKernelSleepDriftBenchmark()
        {
            btnRunSleepTest.Enabled = false;
            lblSleepTestReport.Text = "⏳ 25 iterasyonlu Thread.Sleep(1) çekirdek sapma ölçümü yapılıyor...";

            ThreadPool.QueueUserWorkItem(_ =>
            {
                List<double> samples = new List<double>();
                Stopwatch sw = new Stopwatch();
                for (int i = 0; i < 25; i++)
                {
                    sw.Restart();
                    Thread.Sleep(1);
                    sw.Stop();
                    samples.Add(sw.Elapsed.TotalMilliseconds);
                    Thread.Sleep(4);
                }

                double sum = 0, min = double.MaxValue, max = double.MinValue;
                foreach (double v in samples)
                {
                    sum += v;
                    if (v < min) min = v;
                    if (v > max) max = v;
                }
                double avg = sum / samples.Count;
                double jitter = max - min;

                uint minR, maxR, curR;
                NativeMethods.NtQueryTimerResolution(out minR, out maxR, out curR);
                double curTimerMs = curR / 10000.0;

                this.BeginInvoke((MethodInvoker)delegate
                {
                    btnRunSleepTest.Enabled = true;
                    lblSleepTestReport.Text = string.Format(
                        "📊 KERNEL ZAMANLAYICI TEST SONUCU:\n" +
                        "──────────────────────────────────────────\n" +
                        "• Aktif Kernel Tick Süresi : {0:0.000} ms ({1:0} Hz)\n" +
                        "• Ortalama Sleep(1) Uyanma : {2:0.00} ms\n" +
                        "• En Hızlı / En Yavaş      : {3:0.00} ms / {4:0.00} ms\n" +
                        "• Zamanlayıcı Jitter       : {5:0.00} ms\n\n" +
                        "{6}",
                        curTimerMs, 1000.0 / curTimerMs, avg, min, max, jitter,
                        avg <= 2.1
                            ? "✅ MÜKEMMEL: 0.5ms zamanlayıcı aktif! Girdi ve kare zamanlama sapması minimumda."
                            : "⚠️ STANDART: Zamanlayıcı 15.6ms varsayılanda. Latency sekmesinden 0.500ms kilidini açın.");
                });
            });
        }

        private void RunDetailedMultiServerPingBenchmark()
        {
            btnRunMultiPingTest.Enabled = false;
            lblPingTestReport.Text = "⏳ Cloudflare (1.1.1.1) ve Google (8.8.8.8) üzerinden Jitter analizi yapılıyor...";

            ThreadPool.QueueUserWorkItem(_ =>
            {
                List<long> cfTimes = new List<long>();
                List<long> ggTimes = new List<long>();

                using (Ping p = new Ping())
                {
                    for (int i = 0; i < 8; i++)
                    {
                        try
                        {
                            var r1 = p.Send("1.1.1.1", 1000);
                            if (r1 != null && r1.Status == IPStatus.Success) cfTimes.Add(r1.RoundtripTime);
                            var r2 = p.Send("8.8.8.8", 1000);
                            if (r2 != null && r2.Status == IPStatus.Success) ggTimes.Add(r2.RoundtripTime);
                        }
                        catch { }
                        Thread.Sleep(25);
                    }
                }

                double cfAvg = 0, cfJitter = 0, ggAvg = 0, ggJitter = 0;
                if (cfTimes.Count > 0)
                {
                    long min = long.MaxValue, max = long.MinValue, sum = 0;
                    foreach (long t in cfTimes) { sum += t; if (t < min) min = t; if (t > max) max = t; }
                    cfAvg = (double)sum / cfTimes.Count;
                    cfJitter = max - min;
                }
                if (ggTimes.Count > 0)
                {
                    long min = long.MaxValue, max = long.MinValue, sum = 0;
                    foreach (long t in ggTimes) { sum += t; if (t < min) min = t; if (t > max) max = t; }
                    ggAvg = (double)sum / ggTimes.Count;
                    ggJitter = max - min;
                }

                this.BeginInvoke((MethodInvoker)delegate
                {
                    btnRunMultiPingTest.Enabled = true;
                    lblPingTestReport.Text = string.Format(
                        "🌐 AĞ & JITTER ANALİZ SONUCU (8 Paket):\n" +
                        "──────────────────────────────────────────\n" +
                        "• Cloudflare (1.1.1.1) Ort : {0:0.0} ms  |  Jitter: {1:0.0} ms\n" +
                        "• Google DNS (8.8.8.8) Ort : {2:0.0} ms  |  Jitter: {3:0.0} ms\n" +
                        "• Paket Kaybı (Loss)       : %{4:0}\n\n" +
                        "{5}",
                        cfAvg, cfJitter, ggAvg, ggJitter,
                        ((8 - cfTimes.Count) * 100.0) / 8.0,
                        cfJitter <= 3.0
                            ? "✅ STABİL HAT: Jitter 3ms altında, rekabetçi oyunlar için sıfır dalgalanma."
                            : "💡 İPUCU: Jitter yüksekse Network sekmesinden Nagle, Interrupt Moderation ve Restricted Auto-Tuning açın.");
                });
            });
        }

        // Windows 11 Presentation Mode & DXGI Display Pipeline Diagnostics (Supported DXGI + PresentMon)
        private void RunPresentationModeDiagnostics()
        {
            try
            {
                PresentationPolicySnapshot snap = PresentationAdvisorEngine.CaptureSnapshot(vault);
                StringBuilder report = new StringBuilder();
                report.AppendLine("═════════════════════════════════════════════════════════════════════════════════════════════");
                report.AppendLine(string.Format("• İŞLETİM SİSTEMİ & DWM     : {0}{1}",
                    snap.OsFriendlyName,
                    snap.Hardware.DwmTimingOk ? string.Format(" | DWM Compose: {0:0.0}Hz (Dropped:{1}, Missed:{2})", snap.Hardware.DwmComposeHz, snap.Hardware.DwmFramesDropped, snap.Hardware.DwmFramesMissed) : ""));

                if (snap.Hardware.Outputs.Count > 0)
                {
                    for (int i = 0; i < snap.Hardware.Outputs.Count && i < 2; i++)
                    {
                        var o = snap.Hardware.Outputs[i];
                        report.AppendLine(string.Format("• DXGI ÇIKIŞ [{0}]         : {1}x{2}@{3}Hz ({4}b {5}) | MPO={6} | HWComp(Win:{7}, FSE:{8})",
                            o.DeviceName.Replace("\\\\.\\", ""), o.Width, o.Height, o.RefreshRateHz,
                            o.BitsPerColor, o.IsHdrActive ? "HDR" : "SDR",
                            o.SupportsOverlaysMpo ? "AÇIK" : "KAPALI",
                            o.HwCompWindowed ? "Evet" : "Hayır",
                            o.HwCompFullscreen ? "Evet" : "Hayır"));
                    }
                    if (snap.Hardware.Outputs.Count > 2)
                        report.AppendLine(string.Format("  (+ {0} ek monitör — tamamını görmek için 'Flip-Model & MPO Danışmanı'nı açın)", snap.Hardware.Outputs.Count - 2));
                }

                report.AppendLine(string.Format("• DWM / DIRECTX POLİTİKASI  : WinOpt(SwapEffect)={0} | VRR={1} | HAGS={2} | FSEMode={3} | MPOEngeli={4}",
                    snap.SwapEffectUpgradeEnable == 1 ? "Açık" : (snap.SwapEffectUpgradeEnable == 0 ? "Kapalı" : "Vars."),
                    snap.VrrOptimizeEnable == 1 ? "Açık" : (snap.VrrOptimizeEnable == 0 ? "Kapalı" : "Vars."),
                    snap.HagsMode == 2 ? "Açık(2)" : (snap.HagsMode == 1 ? "Kapalı(1)" : "Vars."),
                    string.IsNullOrEmpty(snap.FseBehaviorMode) ? "0" : snap.FseBehaviorMode,
                    snap.MpoRegistryBlocked ? ("EVET(" + snap.OverlayTestMode + ")") : "Yok"));

                report.AppendLine("─────────────────────────────────────────────────────────────────────────────────────────────");
                if (snap.Conflicts.Count > 0)
                {
                    report.AppendLine("⚠️ ÇAKIŞMA / UYARI: " + snap.Conflicts[0]);
                }
                else
                {
                    report.AppendLine("✅ YAPILANDIRMA TUTARLI: Kayıt defteri DWM / DirectX politikaları arasında çakışma algılanmadı.");
                }
                report.AppendLine("ℹ️ Canlı oyun swapchain PresentMode kanıtı için '5 Sn Gecikmeli Ön Plan Oyunu Yakala'ya tıklayıp oyuna geçin.");
                report.AppendLine("═════════════════════════════════════════════════════════════════════════════════════════════");

                if (lblPresentationReport != null)
                    lblPresentationReport.Text = report.ToString();
            }
            catch (Exception ex)
            {
                if (lblPresentationReport != null)
                    lblPresentationReport.Text = "Ekran sunum tanısı çalıştırılırken hata oluştu: " + ex.Message;
            }
        }

        private void RunDelayedForegroundPresentationCapture()
        {
            if (presCountdownTimer != null && presCountdownTimer.Enabled) return;
            presCountdownLeft = 5;
            if (btnDelayedGamePresCapture != null)
            {
                btnDelayedGamePresCapture.Enabled = false;
                btnDelayedGamePresCapture.Text = string.Format("⏳ Oyuna Geçin... {0} sn", presCountdownLeft);
            }

            if (presCountdownTimer == null)
            {
                presCountdownTimer = new System.Windows.Forms.Timer { Interval = 1000 };
                presCountdownTimer.Tick += (s, e) =>
                {
                    presCountdownLeft--;
                    if (presCountdownLeft > 0)
                    {
                        if (btnDelayedGamePresCapture != null)
                            btnDelayedGamePresCapture.Text = string.Format("⏳ Oyuna Geçin... {0} sn", presCountdownLeft);
                    }
                    else
                    {
                        presCountdownTimer.Stop();
                        if (btnDelayedGamePresCapture != null)
                            btnDelayedGamePresCapture.Text = "🔍 Yakalanıyor...";

                        IntPtr fgHwnd = NativeMethods.GetForegroundWindow();
                        string pmBin = FindPresentMonBinary();
                        ThreadPool.QueueUserWorkItem(_ =>
                        {
                            PresentationPolicySnapshot snap = PresentationAdvisorEngine.CaptureSnapshot(vault);
                            string outReport = PresentationAdvisorEngine.InspectTargetWindowAndSwapchain(fgHwnd, snap, pmBin);
                            try
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    if (lblPresentationReport != null)
                                        lblPresentationReport.Text = outReport;
                                    if (btnDelayedGamePresCapture != null)
                                    {
                                        btnDelayedGamePresCapture.Text = "⏱️ 5 Sn Gecikmeli Ön Plan Oyunu Yakala";
                                        btnDelayedGamePresCapture.Enabled = true;
                                    }
                                    try { System.Media.SystemSounds.Asterisk.Play(); } catch { }
                                });
                            }
                            catch { }
                        });
                    }
                };
            }
            presCountdownTimer.Start();
        }

        private void OnCard3RawMouse(IntPtr hRawInput)
        {
            if (currentActiveTabIndex != 8 || card3RawTracker == null || pnlMouseTestArea == null || !pnlMouseTestArea.Visible)
                return;
            if (!this.ContainsFocus)
                return;
            Point localPt = pnlMouseTestArea.PointToClient(Cursor.Position);
            if (!pnlMouseTestArea.ClientRectangle.Contains(localPt))
                return;
            card3RawTracker.RecordRawMouseMessage(hRawInput);
        }

        private void ResetCard3RawTracker()
        {
